INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997742656', 'Hidratante De Couro Cadillac Tratamento Para Couro 500ml', 'Tratamento de Couro Hidratante de Couro Descrição: Com fórmula balanceada e inovadora, o TRATAMENTO DE COURO CADILLAC® hidrata a superfície e resgata a originalidade, conservando a estética de materiais de couro. O resultado é o couro protegido e revitalizado, com aspecto original e delicioso aroma de couro natural. Revitaliza e Protege Disponível nas versões: 200mL & 500mL Categoria: Cuidados Internos', 54.8, 45.03, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-820ma-mq0muwsu6m804a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1228411998%2F23997742656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
