INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694829365', 'Farol Palio 96 97 98 99 2000 Cromado Lente Policarbonato', 'Código do Produto: 168168 Farol Palio 96 97 98 99 2000 Cromado VALOR ANUNCIADO REFERENTE A UNIDADE. O farol é uma peça essencial para sinalização e visibilidade em vias noturnas e para maior segurança eles devem estar sempre em bom estado. E aqui temos o produto ideal para você. Este item possui material de alta qualidade e resistência, composto com sua lente em Policarbonato, encaixe da lâmpada H4 que suporta até 55W e um design que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Fiat - Palio 1996 - Palio 1997 - Palio 1998 - Palio 1999 - Palio 2000 Especificações Técnicas: - Lente Estriada - Máscara Cromada - Lente Policarbonato - Foco Simples - Encaixe da Lâmpada H4 - Material da Carcaça em Plástico - Suporta Lâmpadas de até 55W', 143.9, 143.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mju4g6bak3cxbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F374148566%2F22694829365', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
