INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22395943008', '6 Painel Led 18w Quadrado Embutir 6500K Comércio Casa Avant', 'Painel Led Pop de Embutir Quadrado 6500W 18W Avant A linha PAINEL POP EMBUTIR QUADRADO é versátil e pode ser usada em ambientes residenciais, comerciais e corporativos, proporcionando uma iluminação homogênea com design clean e moderno. - Corpo e difusor em policarbonato - Fluxo luminoso constante em toda faixa de tensão. - Baixo consumo de energia. ATENÇÃO: - Na instalação do transformador eletrônico, certifique-se de que o mesmo não ficará em contato com a luminária, pois toda a base da luminária funciona como dissipador de calor, o que pode causar danos e interferências no funcionamento do transformador. - Para melhor fixação do painel POP de embutir, a espessura do forro deve ser de pelo menos 1cm. - Para garantia da vida útil do painel POP, recomenda-se uma distância de pelo menos 10 cm entre o forro e a laje. Referencia: 0775 - Código: 903011374 - Modelo:PAINEL POP QUADRADO EMBUTIR - Marca: Avant - Potência: 18w - Fluxo Luminoso: 1080 Lumens - Eficiência Luminosa: 70lm/w - Ângulo de Abertura: 120 Graus - Temperatura da Cor: 6500K - Emissão de Luz: Branco - Tipo de instalação: Embutir - Temperatura ambiente: -5C a 40C. - Tensão nominal: 100V a 240V. - Fator de Potência: 0,50 Dimensões Aproximadas do Produto: - Altura: 220mm - Largura: 220mm - Comprimento: 18mm - Nicho de Corte: 210 x 210mm *** GARANTIA DE 1 ANO CONCEDIDO PELO FABRICANTE ***', 194.22, 99.0, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7reoe-m8makgqdlb5s1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F22395943008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18757309375', 'Sabonete Líquido Nivea Óleo De Banho 200ml', 'O Sabonete Líquido Nivea Natural Oil é indicado para todos os tipos de pele. Sua sedosa textura de óleos naturais forma uma espuma cremosa e extremamente suave, contém ainda 55% de óleos naturais, responsáveis por uma sensação de hidratação, combinado com um perfume delicioso. Limpa delicadamente a pele substituindo o sabonete regular durante o banho e deixando sua pele macia e sedosa mesmo depois da secagem com a toalha. Benefícios: - Prolonga o bronzeado. - Substitui o sabonete. - Rende até 60 banhos. - Com 54% de óleos naturais. - Todos os tipos de pele.', 47.24, 47.24, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-82588-mq7tvtih7bpr15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F18757309375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52062691240', 'Filtro Ar condicionado Corolla Yaris Hilux Sw4 + Higienizador Limpa Ar', 'KIT FILTRO DE CABINE BOSCH 0986BF0558 + HIGIENIZADOR ORBI AIR 200ML Aplicação 🚗 Toyota Corolla – 2008 a 2014 🚗 Toyota Yaris Sedan – 2018 em diante 🚗 Toyota Yaris Hatch – 2018 em diante 🚗 Toyota Hilux – 2005 a 2015 🚗 Toyota SW4 – 2005 a 2015 🚗 Toyota RAV4 – 2012 a 2018 🚗 Toyota Corolla Cross – 2020 em diante Dimensões do Filtro 📏 Comprimento: 215 mm 📏 Largura: 195 mm 📏 Altura: 30 mm Conteúdo da Embalagem ✅ 1 Filtro de Ar Condicionado Bosch 0986BF0558 ✅ 1 Higienizador Orbi Air 200ml Benefícios do Filtro de Cabine Bosch ✔ Filtra poeira, pólen, fuligem e outras impurezas presentes no ar ✔ Auxilia na retenção de partículas nocivas ao sistema respiratório ✔ Maior resistência à umidade e à formação de micro-organismos ✔ Mantém o interior do veículo mais limpo e saudável ✔ Protege os componentes do sistema de ventilação e ar-condicionado ✔ Produto original Bosch com alto padrão de qualidade Os filtros de cabine Bosch ajudam a proporcionar um ambiente mais confortável para motoristas e passageiros, reduzindo a entrada de impurezas e contribuindo para a conservação dos componentes do sistema de climatização do veículo. Higienizador Orbi Air 200ml ✅ Produto Notificado na ANVISA O Orbi Air realiza a higienização dos dutos do sistema de ventilação e ar-condicionado, ajudando a eliminar odores desagradáveis e proporcionando um ambiente mais agradável dentro do veículo. Benefícios ✔ Elimina maus odores ✔ Auxilia no combate a fungos e bactérias ✔ Limpa todo o sistema de ventilação ✔ Fragrância agradável e duradoura ✔ Aplicação automática tipo granada ✔ Dispensa equipamentos especiais ✔ Fácil e rápida aplicação ✔ Liberação rápida do veículo após o uso Modo de Aplicação 1️⃣ Recomenda-se substituir o filtro de cabine antes da higienização. 2️⃣ Retire os tapetes de borracha e deixe os vidros dianteiros abertos cerca de 5 cm. 3️⃣ Ligue o veículo e coloque o ar-condicionado na função de recirculação. 4️⃣ Ajuste o ventilador na velocidade máxima e selecione ar frio. 5️⃣ Agite a embalagem e posicione-a no assoalho do passageiro. 6️⃣ Acione a válvula até o travamento e saia do veículo. 7️⃣ Aguarde o término da aplicação (aproximadamente 4 minutos). 8️⃣ Após a aplicação, aguarde mais 10 minutos antes de entrar no veículo. 9️⃣ Abra todas as janelas por cerca de 5 minutos antes da utilização. Importante ⚠ Verifique a compatibilidade antes da compra. ⚠ Em caso de dúvidas, informe o modelo, ano e motorização do veículo no campo de perguntas. ⚠ Recomendamos a instalação por profissional qualificado. ⚠ Produto novo, original e acompanhado de nota fiscal. ⚠ As imagens são ilustrativas. ⚠ Certifique-se de que o código Bosch 0986BF0558 corresponde à aplicação desejada antes de finalizar a compra.', 54.99, 44.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820lf-mptz8lguj30g0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560163381%2F52062691240', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15248590109', 'Kit 6 Desodorantes em Barra Old Spice Brisa do Mar 50g', 'O Kit contém: 6 Desodorantes em Barra Old Spice Brisa do Mar com 50g cada. Aproveite mais refrescância e proteção contra o suor e o mau cheiro com o desodorante antitranspirante em barra Old Spice Brisa do Mar! Conte com uma poderosa fragrância herbal, com notas cítricas e amadeiradas. • 2x mais proteção que sprays**Vs. Old Spice Spray • Perfume duradouro • Fragrância herbal, com notas cítricas e amadeiradas • Você longe do cheiro de cecê ou suor • Dura até 40 días****Com base na instruçao de uso para 1.2g por día', 166.99, 166.99, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rdyh-mbxvzzz6i4ie14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F15248590109', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
