INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697741696', 'Fogão de Mesa a Gás Stelar Euro 1 Boca Preto', 'Fogão de Bancada Portátil Stelar Euro: Estabilidade e Eficiência para Pequenos Espaços! O Fogão de Bancada Stelar Euro de 01 Queimador, é a solução ideal para espaços compactos, como bancadas de trailers, barcos e espaços gourmet. Com sua trempe individual, oferece maior estabilidade às panelas, facilitando o preparo dos alimentos e proporcionando segurança ao usuário. Características em Destaque: Estabilidade Aprimorada: A trempe individual oferece maior estabilidade às panelas, evitando deslizamentos e balanços durante o uso. Eficiência Energética: Equipado com um queimador rápido de 2000 watts, proporciona potência e eficiência para o preparo dos alimentos. Acendimento Manual: Sistema de acendimento manual simples e prático. Material Durável: Fabricado com vidro temperado de 6mm de espessura e trempe de aço esmaltado, garantindo durabilidade e resistência. Praticidade e Segurança: A trempe com suporte de aço revestido com Teflon preto proporciona segurança ao usuário, evitando deslizamentos indesejados. Compacto e Leve: Seu design portátil permite a instalação em qualquer local, oferecendo praticidade e versatilidade. Especificações Técnicas: Marca: Stelar Modelo: Euro Cor: Preto Tipo de Instalação: De Bancada Tipo de Funcionamento: A Gás Tipo de Gás: GLP Número de Queimadores: 01 Potência do Queimador: 1 Rápido (2000W) Acendimento: Manual Material/Composição: Vidro Temperado e Aço Esmaltado Suporte da Trempe: Aço revestido com Teflon preto Produto Nacional: Sim Dimensões e Peso: Dimensões do Produto (AxLxP): 14 x 29 x 29 cm Peso do Produto :3kg Observação de Envio: O produto é enviado para gás liquefeito de petróleo (GLP) e não pode ser convertido para GN. Garantia: 12 meses contra defeitos de fabricação através do fabricante. Vai contido no produto uma etiqueta QR CODE ( Aponte a câmera do seu celular para o código da etiqueta para acessar seu manual ). Adquira agora o Fogão de Bancada Stelar Euro e desfrute de praticidade e segurança em seus preparos culinários!', 197.0, 197.0, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-7rdy2-lzp0kmsxgrze09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F998245378%2F23697741696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
