INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45650285185', 'Estojo Escolar Box Fun Gocase', 'Estojo Box Fun Gocase – Espaço, estilo e organização em um só lugar! O Estojo Box Fun chegou para deixar sua rotina mais prática e divertida! Com design estruturado e amplo espaço interno, ele é perfeito para organizar canetas, lápis, pincéis ou acessórios — ideal para escola, faculdade ou trabalho. Possui uma divisória interna com elásticos, que facilita manter tudo no lugar do jeitinho que você preferir. Detalhes do Produto: • Amplo espaço interno • Abertura total para facilitar o acesso • Divisória interna com elásticos para acomodar canetas e lápis Composição: • Tecido: 100% poliéster • Forro: 100% poliéster Dimensões: • Altura: 11 cm • Largura: 21 cm • Profundidade: 4,5 cm Como cuidar do seu Estojo Fun: Limpe com pano levemente umedecido e sabão neutro. Seque puxadores e etiqueta com pano seco após a limpeza. Deixe secar à sombra. Não deixar de molho, não usar máquina de lavar/secar e não expor ao sol. Garantia: Garantia de 90 dias contra defeitos de fabricação, costura e montagem. A imagem do produto é ilustrativa e pode haver variação de cor conforme a tela do seu dispositivo.', 169.9, 78.9, NULL, 'Stationery > School & Office Equipment > Pencil Cases', 'https://cf.shopee.com.br/file/sg-11134201-8257y-mgcdcmy4ipzccf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1338070754%2F45650285185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
