INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099382154', 'Kit 2 Pneus Aro 15 Chengshan 185/60 R15 84H CSC - 802', 'Kit 2 Pneus Aro 15 Chengshan 185/60 R15 84H CSC - 802 Sobre o Pneu: O modelo CSC 802 da Chengshan possui um design de alta densidade boa aderência em pistas molhadas, unindo-se a economia perfeita e amigável ao meio ambiente. Sobre a Marca: A Chengshan é uma respeitada fabricante de pneus sediada na China, com uma sólida presença no mercado global. A empresa é conhecida por sua vasta gama de produtos, que abrangem desde pneus para veículos de passeio até pneus industriais e agrícolas. Informações Adicionais: - Marca: Chengshan - Modelo: CSC-802 - Medida: 185/60 R15 - Largura: 185mm - Perfil: 60% - Aro: 15 - Índice de peso: 84 - 500 Kg - Índice de velocidade: H - 210 Km/h - Run Flat: Não - Extra Load: Não - Tipo de construção: Radial - Tipo de Terreno: HT - Garantia: 5 anos Contra Defeitos de Fábrica Aplicações: - CHEVROLET: AGILE, MERIVA, TIGRA - CHRYSLER: NEON - CITROEN: C3 - FIAT: ARGO, PALIO, PUNTO, UNO - FORD: FIESTA - HONDA: CITY, FIT - HYUNDAI: HB20 - JAC: J3, J3 S, J3 TURIN - NISSAN: MARCH - PEUGEOT: 206, 207 SW, 306 - RENAULT: MEGANE - TOYOTA: ETIOS, ETIOS CROSS, YARIS - VOLKSWAGEN: CROSS UP, UP POR FAVOR, VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU', 593.9, 593.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-m097t9w2bu9s2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F19099382154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16342273106', 'Par Mini Retrovisor Articulado Modelo Original Pro Tork Compatível com Motos Yamaha', 'A Pro Tork traz mais uma novidade para seu catálogo: os Retrovisores Modelo Articulado. São vários modelos para você escolher, todos baseados nos moldes dos modelos orignais das principais motos do mercado nacional. Produzidos com materiais de alta qualidade, estes retrovisores são excelentes, suas hastes articuladas permitem ao piloto posicioná-lo para alcançar um maior campo de visão. Especificações: - Cor: Preto; - Modelo articulado; - Injetado em Polipropileno; - Peça de reposição; - Valor referente ao Par; - Marca: Pro Tork. Aplicação: - Titan 1999; - Titan 150 2004; - Titan 150 2005; - Titan 150 2006; - Titan 150 2007; - Titan 150 2008. - Todas as motos da marca Yamaha. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada; - A Sportbay não se responsabiliza pela má instalação do produto. OBS: - Imagem Ilustrativa: Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. Sportbay - Seu Esporte, Nossa Paixão.', 84.11, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Side Mirrors', 'https://cf.shopee.com.br/file/1a4f5bf6928f7702bccf1a40e4f3815e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F16342273106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
