INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22996493118', 'Jogo Filmes e Series Perfil Express 4368 - Grow', 'DESCRIÇÃO DO PRODUTO Perfil Express Filmes e Séries é a novidade de um dos maiores clássicos da Grow. Ele traz uma nova forma de jogar através de categorias inspiradas no streaming e nas telas de cinema! Cada cartela possui 10 dicas que valem até 10 pontos. A primeira dica é menos reveladora, e as seguintes, de maneira progressiva, aumentam mais as chances de acerto. Esta versão foi especialmente desenvolvida para ser jogada por duas pessoas ou equipes, sem a necessidade de um tabuleiro. Com um novo sistema de pontuação, o vencedor será aquele que fizer mais pontos durante cinco rodadas. Desafie alguém ou reúna a galera para aproveitar ao máximo o novo Perfil Express Filmes e Séries! CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: 1 Jogo Perfil Express Filmes e series Dimensões Aproximadas da Embalagem: 6 cm x 13 cm x 18 cm (Altura x Largura x Comprimento/Profundidade)', 47.72, 42.49, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7qvdl-lk00rvuhzok2aa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F22996493118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197473694', 'A Arte da Guerra - Sun Tzu - Edição Luxo e acesso ao audiobook', 'Elaborada há mais de 2500 anos, A Arte da Guerra é uma obra-prima da ciência militar cujos conceitos e ensinamentos influenciaram guerreiros da Antiguidade e continuam úteis para todos os tipos de líderes e estrategistas modernos. Um eterno best-seller entre apreciadores de estratégia política, de negócios e na vida cotidiana.', 35.54, 35.54, NULL, 'Books & Magazines > Books > Psychology & Relationships', 'https://cf.shopee.com.br/file/sg-11134201-7r99x-ln7opxxtmxbp3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F20197473694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697456603', 'As vantagens de ser invisível', 'O LIVRO QUE INSPIROU O FILME NOVA EDIÇÃO COM TRECHO INÉDITO Manter-se à margem oferece uma única e passiva perspectiva. Mas, de uma hora para outra, sempre chega o momento de encarar a vida do centro dos holofotes. Mais íntimas do que um diário, as cartas de Charlie são estranhas e únicas, hilárias e devastadoras. Não se sabe onde ele mora. Não se sabe para quem ele escreve. Tudo o que se conhece é o mundo que ele compartilha com o leitor. Estar encurralado entre o desejo de viver sua vida e fugir dela o coloca num novo caminho através de um território inexplorado. Um mundo de primeiros encontros amorosos, dramas familiares e novos amigos. Um mundo de sexo, drogas e rock''''''''''''''''n''''''''''''''''roll, quando o que todo mundo quer é aquela música certa que provoca o impulso perfeito para se sentir infinito. A luta entre apatia e entusiasmo marca o fim da adolescência de Charlie nesta história divertida e ao mesmo tempo instigante.', 73.48, 73.48, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7r99s-ln7x98l4sid62b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F20697456603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
