INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499321874', 'A psicologia do sonho - Principis', 'Freud construiu um método completo de psicanálise em torno de suas teorias dos sonhos. Neste livro, ele explica os significados reprimidos nos sonhos por meio de vários exemplos reais, particularmente o impulso e a conexão entre o inconsciente e o consciente. Interpreta, também, as causas deles e suas relações com eventos passados e em andamento em nossas vidas, faz a análise dos elementos dos sonhos e explora tópicos específicos como: Pensamentos sexuais em sonhos e desejos humanos.', 25.65, 25.65, NULL, 'Books & Magazines > Books > Psychology & Relationships', 'https://cf.shopee.com.br/file/sg-11134201-7rd4c-lwt11vyspw8c51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F19499321874', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
