INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13979116246', 'Kit 3 em 1 esponjas multiúso limpa rodas e pneus sem riscar', 'Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há quase duas décadas, nosso estoque conta com uma variedade de 45000 itens. Todos os nossos produtos são novos, originais e com garantia. Este anúncio contém os seguintes produtos: Kit 3 em 1 Esponjas Multiúso Luxcar O Kit 3 em 1 Esponjas Multiúso Luxcar limpam sem riscar e fazem muita espuma. Podem ser utilizadas tanto no carro quanto no lar. Cada esponja tem uma cor diferente, para áreas diferentes. Por exemplo: amarela para lavar o carro, vermelha para aplicar silicone no painel e a cinza para aplicar pretinho nos pneus. Ideais para aplicar: • Lavar o carro • Aplicar Silicone no Painel • Limpar Rodas e Pneus Modo de usar: Anatômica pode ser utilizada tanto no interior quanto no exterior do carro e também no lar. Validade Indeterminada.', 20.0, 20.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/d53944cf653dfce1bc55f261cabecfee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549478150%2F13979116246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
