INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261883648', 'Kit Dermotivin Benzac Higienização e Hidratação (2 Produtos)', 'Kit com sabonete e hidratante facial para peles oleosas e acneicas. Dermotivin Benzac Higienização e Hidratação protege, matifica e hidrata a pele. O Kit Dermotivin Benzac Higienização e Hidratação limpa, acalma a pele, elimina o excesso de oleosidade, diminui a ocorrência de cravos e espinhas, mantém o brilho sob controle por um período de 12 horas e oferece ainda oferece uma proteção eficaz contra o ressecamento por 24 horas. Como usar: Distribua o sabonete sobre o rosto e pescoço previamente já umedecidos, realizando movimentos suaves e circulares. Em seguida, enxágue o rosto por completo. Use duas vezes ao dia (aplicar durante a manhã e durante a noite) ou conforme orientação do seu dermatologista. Depois, aplique o hidratante generosamente na pele limpa duas vezes ao dia, manhã e noite, ou conforme orientação do seu dermatologista. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 105.8, 105.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-823r5-mp0wdojpejnkbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58261883648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254380683', 'Maybelline Fit Me! Rosa - Blush em Pó 4g', 'Blush em pó compacto para todos os tipos de pele. Maybelline Fit Me! Blush proporciona um tom corado e saudável ao rosto com efeito natural. Extremamente pigmentado, a textura do Blush Fit Me! Maybelline não deixa a pele oleosa ou ressecada. O pó ultrafino se espalha facilmente sobre as maçãs do rosto e a formulação, apesar de leve, oferece boa cobertura e longa duração. Como usar: Aplique o blush sobre as maçãs do rosto com o auxílio de um pincel com as cerdas chanfradas com movimentos de vai-e-vem. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 80.9, 80.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-82606-mk47q2upu3ur38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58254380683', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
