INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17701908869', 'Gel Facial Equilibrante PhálleBeauty PH0561', 'Controla a oleosidade e ajuda a minimizar o brilho visível da pele; dando à pele um acabamento matte saudável. Reduz a aparência dos poros. Ajuda a resistir aos primeiros sinais de envelhecimento. A pele fica fresca, suave, macia e hidratada. Levissíma fórmula, 100%livre de óleos e gorduras, contém Niacinamida e Bisabolol. Múltiplos Benefícios: Hidratação Delicada e Efetiva Ação Tonificante e Revigorante Ação Antioxidante Efeito primer, Pré-Maquiagem e pré-filtros Modo de usar: Com a pele limpa, aplique uma pequena quantidade do produto no rosto, colo e pescoço espalhando uniformemente em movimento circulares até completa absorção. Uso diário. PH0561', 14.99, 14.99, NULL, 'Beauty > Skincare > Face Scrub & Peel', 'https://cf.shopee.com.br/file/ddf09b2c95e4aa23c4de18577f62893e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F17701908869', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
