INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202133596', 'Fonte Carregador Usina Bolt 70A Bivolt 12V', 'Fonte Carregador Usina Bolt 70A Bivolt 12V A Linha de fontes BOLT foi desenvolvida para quem busca um produto compacto, potente e robusto, com excelente custo-benefício. Conta com ajuste de tensão e corrente, e seu sistema de dissipação de calor robusto garante desempenho estável, mesmo em condições severas de uso. Utiliza o que há de melhor em componentes e tecnologia voltada para a área de eletrônica de potência. Conta com vários recursos que garantem a recarga e a manutenção de carga de suas baterias. Especificações: • Tensão de Entrada: Bivolt Automático • AC 127Vca: 100 @ 140Vca • AC 220Vca: 170 @ 250Vca • Consumo 127Vca: 15A (máximo) • Consumo 220Vca: 8A (máximo) • Tensão de Saída: 12,5V @ 14,4Vcc (+-1%) • Corrente de Saída: 70A @ 12,5Vcc (+-5%)* • Potência de Saída: 875 Watts (máxima)** • Rendimento: 85% • Potência de Entrada: 1075 Watts (máxima)** • Cabo de Entrada: 3x1,5mm² - 2P+T • Proteção de Entrada: Fusível Interno • Cabo de Saída: 16mm² • Extensão Recomendada: 2,5mm² (máx 30 metros) • Peso: 1,400 Kg • Dimensões Aproximadas (CxLxA): 145mmX200mmX65mm', 468.0, 395.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Battery Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-midkf1b1j01tb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411081274%2F58202133596', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
