INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45756300830', 'Inoar Baccarah Blue Condicionador 800ml', 'Inoar Baccarah Blue Condicionador 800ml Condicionador INOAR Baccarah Blue: nutrição intensa, fios alinhados e brilho radiante com Amêndoa Doce e Tâmara, em fragrância árabe sofisticada. A combinação de Amêndoa Doce e Tâmaras potencializa a reparação e a nutrição profunda dos fios. A Tâmara, rica em açúcares naturais, aminoácidos e antioxidantes, promove hidratação duradoura, fortalece os fios e protege contra danos oxidativos. Enquanto a Amêndoa Doce, carregada de ácidos graxos essenciais, atua diretamente na cutícula, preenchendo áreas ressecadas e reforçando a barreira nutritiva. pH 3,50 - 4,50 Contem: 1-Inoar Baccarah Blue Condicionador 800ml', 40.95, 36.86, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-82601-mkvfd80qns3q20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290896931%2F45756300830', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398132983', 'Macacão para Bebê Menina em Suedine Comfy Up Baby', 'Macacão para bebê menina confeccionado em suedine (algodão), garantindo maciez e conforto para a pele delicada do bebê. Possui gola dupla com franzido, bordado chenille, estampa, abertura entre as pernas por botões de pressão, facilitando a troca, além de punhos ajustados para melhor caimento. Ideal para manter sua bebê aquecida e estilosa nos dias frios.Tecido: SuedineComposição: 100% algodãoModelagem: JustaComprimento Mangas: LongaComprimento: LongoForro: NãoDecote/Gola: RedondoFechamento: Botões', 214.9, 128.94, NULL, 'Baby & Kids Fashion > Girl Clothes > Rompers, Jumpsuits & Overalls', 'https://cf.shopee.com.br/file/sg-11134201-7rfhp-m9ahcqrat8y9e2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F19398132983', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092983412', 'Barra De Proteína Protobar Kit Com 4 Barras De 70g Cada - Nutrata', 'COMPOSIÇÃO DO ANÚNCIO 04 Barras Protobar - 70g Cada - Nutrata A ProtoBar é uma barra de proteína composta por diferentes fontes proteicas. É rica em proteínas de alto valor biológico e prática, proporcionando uma opção nutritiva e saborosa para as refeições intermediárias ao longo do dia. Também é adicionado o Fiber 3, um mix de fibras prebióticas. Diferenciais Adicionado de vitaminas e minerais; Alto teor proteico por 70g de produto; Aporte de fibras prebióticas (Fiber 3); Adicionado de vitamina D3. CONTÉM LACTOSE. ALÉRGICOS: CONTÉM AMENDOIM, DERIVADOS DE LEITE E SOJA. PODE CONTER AVELÃ. NÃO CONTÉM GLÚTEN. SUGESTÃO E INDICAÇÃO DE USO Consumir uma unidade ao dia; Suporte balanceado de nutrientes ideal para refeições intermediárias. IMAGEM MERAMENTE ILUSTRATIVA TABELA PODE VARIAR CONFORME SABOR', 69.6, 51.5, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7nqs0u8842c30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F418949963%2F22092983412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50911856295', 'Emulsão de Manteiga Pipoca Essência 500ml Iceberg', 'A emulsão é uma mistura de componentes aromáticos artificiais. Possui aromas e sabores mais marcantes comparado aos extratos e essências. Utilização: A emulsão tem a função de conferir o cheiro e um sutil sabor nas preparações. É utilizada em pipoca, pão de queijo, pães e massas em geral. Ingredientes: Corante amarelo tartrazina, goma xantana, benzoato de sódio e componentes aromáticos. Alérgicos: Produto não apresenta potencial alergênico.', 29.7, 29.7, NULL, 'Food & Beverages > Cooking Essentials > Flavour Enhancers', 'https://cf.shopee.com.br/file/sg-11134201-823r8-mp82gqhvffnx72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F50911856295', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49155518347', '100% Whey Protein Concentrate Baunilha 900g', '100% Whey Protein Concentrate Baunilha 900g O 100% Whey Protein Concentrate Baunilha é um suplemento proteico desenvolvido para complementar a ingestão diária de proteínas de forma prática e eficiente. Produzido a partir da proteína concentrada do soro do leite, apresenta alto valor biológico e excelente perfil de aminoácidos essenciais, contribuindo para a manutenção e o desenvolvimento da massa muscular. Com sabor baunilha agradável e fácil preparo, é uma opção prática para incluir na rotina alimentar de praticantes de atividades físicas e pessoas que buscam aumentar o consumo de proteínas no dia a dia. Principais Características: Proteína de alto valor biológico, proveniente do soro do leite, que fornece aminoácidos essenciais importantes para o organismo. Rico em aminoácidos essenciais, incluindo BCAAs, que auxiliam na recuperação muscular após atividades físicas. Fácil preparo e boa solubilidade, podendo ser misturado com água, leite ou bebidas de sua preferência. Benefícios: Auxilia na construção e manutenção da massa muscular. Contribui para a recuperação muscular após exercícios. Complementa a ingestão diária de proteínas. Fornece aminoácidos essenciais para o organismo. Prático para incluir na rotina alimentar. Pode ser consumido antes ou após atividades físicas. Diferenciais do Produto: Produzido com proteína concentrada do soro do leite de alta qualidade. Sabor baunilha suave e agradável. Boa solubilidade, facilitando o preparo. Pode ser utilizado em shakes, vitaminas e diversas receitas. Indicado para praticantes de atividades físicas e pessoas que buscam complementar a ingestão de proteínas. Especificações Técnicas: Peso: 900g Instruções de Uso: Misture aproximadamente 30g do produto em cerca de 200ml de água, leite ou bebida de sua preferência. Agite bem em uma coqueteleira ou misture no liquidificador até completa dissolução. Consumir preferencialmente após o treino ou conforme orientação de nutricionista ou profissional de saúde. Avisos e Precauções: Este produto não é um medicamento. Não exceder a recomendação diária de consumo indicada na embalagem. Manter fora do alcance de crianças. Alérgicos: contém derivados de leite e soja. Contém lactose. O consumo deve estar associado a uma alimentação equilibrada e à prática de atividades físicas. O que está incluso? 1 Whey Protein Concentrate Baunilha 900g ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 199.99, 171.29, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820l4-mlhsb4euo4qu1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F49155518347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41365362764', '100% Pure Whey Baunilha Probiótica 900g Ganhe Coqueteleira 700ml de Brinde', '100% Pure Whey Baunilha Probiótica 900g + Coqueteleira 700ml de Brinde 🏋️ Principais Características: • Alta concentração proteica: Formulado com proteínas de alta qualidade, o 100% Pure Whey Probiótica é ideal para quem busca ganho de massa magra e recuperação muscular eficiente. • Sabor Baunilha irresistível: Textura cremosa e sabor agradável que facilitam o consumo diário, tornando o pós-treino mais prazeroso. • Rápida absorção: Contém proteínas de rápida digestão, proporcionando uma entrega eficiente de aminoácidos aos músculos após o treino. 💪 Benefícios: Favorece o crescimento e manutenção da massa muscular. Auxilia na recuperação pós-exercício. Contribui para o aporte proteico diário de forma prática e saborosa. Ideal para atletas e praticantes de atividades físicas que buscam melhor desempenho. ⭐ Diferenciais do Produto: Produzido por Probiótica, marca reconhecida pela qualidade e segurança nutricional. Contém Whey Protein Concentrado (WPC) de alta pureza. Sem adição de açúcares e com baixo teor de gorduras. Acompanha coqueteleira de 700ml exclusiva, perfeita para preparar suas bebidas de forma prática e homogênea. ⚙️ Especificações Técnicas: Peso: 900g Sabor: Baunilha Tipo de proteína: Whey Protein Concentrado 🥤 Instruções de Uso: Dissolva 2 medidas (aproximadamente 30g) do produto em 200ml de água ou leite desnatado. Misture bem na coqueteleira até completa homogeneização. Consuma após o treino ou conforme orientação de nutricionista ou médico. ⚠️ Avisos e Precauções: Este produto não substitui uma alimentação equilibrada e seu consumo deve ser orientado por nutricionista ou médico. Não exceder a recomendação diária de consumo indicada na embalagem. Manter em local fresco, seco e ao abrigo da luz solar. Alérgicos: contém derivados de leite e soja. 📦 O que está incluso? 01 unidade de 100% Pure Whey Baunilha Probiótica 900g 01 unidade de Coqueteleira 700ml (brinde) ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 279.09, 262.09, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg2ajcsjhqmf24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F41365362764', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893099836', 'Piscina Retangular Estrutural Premium PVC 3700 Litros - Mor', 'Piscina Retangular Estrutural Premium PVC 3700 Litros - Mor Com a Piscina Premium Retangular da Mor ficará fácil driblar o calor! Se brincar já é bom, imagine só com muita água no meio da diversão? Ela possui capacidade para 3.700 litros e foi desenvolvida com detalhes exclusivos para garantir diversão com segurança para toda a família. É a escolha perfeita para quem deseja aproveitar ao máximo os momentos de lazer na água! Com estrutura super-resistente, ela conta com uma tripla camada: duas lâminas de PVC e uma trama de poliéster no meio, oferecendo mais durabilidade e proteção contra impactos. Seus esquineiros azuis, além de conferirem um acabamento refinado, garantem maior estabilidade e facilitam o processo de montagem. Já as escoras de segurança são super firmes e evitam que a piscina deslize no solo. Pintadas em epóxi a pó na cor branca, garantem ainda mais durabilidade, além do design moderno e inovador que proporciona mais praticidade, deixando a hora do lazer muito mais tranquila e divertida. Além disso, a piscina conta com válvula para filtro e deságue, tornando a manutenção muito mais simples. Uma ótima opção para reunir a família e aproveitar os melhores momentos do verão! Atenção: Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto! Principais Características: - Indicado para Crianças e Adultos - Capacidade: 3,700L - Formato: Retangular - Cor Predominante: Azul - Estrutura Super Resistente - Maior Estabilidade - Possui Tripla Camada: 2 Lâminas de PVC e 1 Trama de Poliéster - Maior Durabilidade e Proteção Contra Impactos - Medida da Piscina com Escora (AxLxP): 70,0cm x 2,42m x 3,70m - Esquineiros Azuis para um Acabamento Refinado - Montagem Super Prática - Escoras Pi