INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297425697', 'Cano Motor GOLF 2001/2016 - 57161 - VC125', 'Cano Motor GOLF 2001/2016 1.6 8v Gasolina/Flex EA111 - Plástico O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 27.21, 27.21, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7ravb-maj8i45ze3ww5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21297425697', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493099889', 'Penteadeira Camarim de Canto Glitter com 1 Gaveta com LED', 'Apresentamos a nossa elegante Penteadeira Camarim Glitter, perfeita para criar um espaço de beleza luxuoso. Com espelho amplo e iluminado, você terá a melhor visão para aplicar sua maquiagem. Desfrute de um ambiente sofisticado e organize seus produtos de forma pratica e elegante com a Penteadeira Camarim Glitter. Modelo: Penteadeira Camarim Glitter; Largura: 114 cm; Profundidade: 54 cm; Altura: 140 cm Material da estrutura: MDP, com acabamento ripado e espelho 53 cm x 51 cm x 0,3 cm; Acompanha Lâmpada: Sim, 02; Lâmpada: LED e acompanha o interruptor; Quantidade de gavetas: 01, com divisória internas removíveis; Tipo de corrediça: telescópicas; Com puxador: Sim, plástico com material sintético; Quantidade prateleiras: 01; Quantidade de Nichos: não se aplica; Com rodízios: Não; Peso suportado: até 8 kg distribuídos; Tonalidade das Cores: Branco: Fosco; Cinamomo: Fosco; Off White: Brilho; Requer montagem: Sim (kit montagem incluso); Condição do item: Novo; Embalagem do envio: Papelão, plástico, isopor e isomanta; Informações adicionais: - Os objetos que ambientam as fotos não acompanham o produto; - É de inteira responsabilidade do cliente a montagem do produto e/ou instalação, assim como possíveis irregularidades provenientes de manuseio inadequado; - Embora o produto acompanhe o manual de montagem, verifique a complexidade antes de decidir montá-lo sozinho, recomendamos que contrate um profissional de sua confiança; - Fique atento, nossas cores podem sofrer alterações dependendo do seu monitor; - ANTES DE MONTAR O SEU PRODUTO, verifique se há alguma peça danificada, caso esteja, prestaremos a devida assistência dentro do prazo da garantia.', 659.99, 659.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rd4u-lwppksfpmd288f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401986069%2F22493099889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998090558', 'Pré Filtro Combustível Fiat Uno 2012 a 2016 - 1354463 - T040206', 'Pré Filtro Combustível Fiat Uno 2012 a 2016 1354463 T040206 Vivace 1.0 8v Flex - sistema Bosch - Copo, filtro externo e internoO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 58.76, 58.76, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822x6-mo9uwaiu9ssp44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19998090558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999033589', 'Capa Correia ONIX 2013/2015 - 42064 - 106117', 'Capa Correia ONIX 2013/2015 1.4 8v - (Superior Externo) O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 26.45, 26.45, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbm1-lmyrpyds3satef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18999033589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42505913087', 'Tênis Democrata Jake Preto - Masculino', 'Robustez e estilo para quem vive intensamente! Tênis Democrata Jake Preto - Masculino Ficha Técnica: Marca: Democrata Gênero: Masculino Cor: Preto Material: Couro Solado: Micro Expandido Fechamento: Cadarço Estilo: Casual Altura do Salto: 4cm Indicado: Eventos sociais e trabalho Detalhes: Bico arredondado, cabedal com recortes em couro, colarinho e língua acolchoados, logo da marca na lateral e na língua; sola blaqueada para maior durabilidade Versátil, elegante e durável: o Tênis Democrata Jake é feito para o homem moderno que não abre mão de conforto e presença. Porque investir: Com cabedal em couro legítimo e solado em micro expandido, ele oferece resistência e amortecimento para o dia a dia. Seu design urbano com recortes marcantes, cadarço ajustável e detalhes acolchoados elevam o conforto e o estilo em qualquer ocasião. Seja para o trabalho ou para sair, ele entrega tudo o que você precisa em um só calçado. Conteúdo da embalagem: 1 par de Tênis Democrata Jake Preto - Masculino', 339.99, 258.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7ra1i-mbebrhdaoqc16a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F42505913087', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
