INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998539434', 'CD Black Sabbath - Technical Ecstasy (Digipak) - Importado', 'CD Black Sabbath - Technical Ecstasy (Digipak) - Importado Lançado em setembro de 1976 no Reino Unido e outubro de 1976 nos Estados Unidos, Technical Ecstasy é o sétimo álbum de estúdio da banda inglesa de heavy metal Black Sabbath. O Black Sabbath foi formado em Birmingham em 1968 pelo guitarrista e compositor principal Tony Lommi, o baixista e letrista principal Geezer Butler, o vocalista Ozzy Osbourne e o baterista Bill Ward. O Black Sabbath é frequentemente citado como pioneiro do heavy metal. A banda ajudou a definir o gênero com uma série de álbuns inovadores nos anos 70. Repertório do CD: 1. Back Street Kids 2. You Won''t Change Me 3. It''s Alright 4. Gypsy 5. All Moving Parts (Stand Still) 6. Rock ''n'' Roll Doctor 7. She''s Gone 8. Dirty Women Content owned and licensed by BMG (Conteúdo de propriedade e licenciado pela BMG).', 99.9, 84.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-825ar-mq6ymcyk3cwd74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F22998539434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52101734826', 'Decoração Roda Gigante de Ferro Dourado Giratória 21X9,5X23,5cm', 'A Decoração Roda Gigante de Ferro Dourado Giratória é uma peça exclusiva que une elegância, sofisticação e movimento em um único item decorativo. Seu design moderno e acabamento metálico trazem um toque refinado que transforma qualquer ambiente, tornando-o mais acolhedor e visualmente atrativo. Com 23,5 cm de altura e 22 cm de largura, esta roda gigante decorativa é feita inteiramente em ferro, garantindo resistência, durabilidade e acabamento de alta qualidade. O dourado metálico confere brilho e requinte, enquanto o sistema giratório funcional adiciona um charme extra à peça — um detalhe que desperta curiosidade e admiração. Ideal para compor salas de estar, escritórios, quartos, aparadores, estantes ou recepções, a peça combina facilmente com diferentes estilos de decoração, como moderno, clássico, contemporâneo e industrial. Sua aparência delicada, porém robusta, permite que seja usada como destaque central ou em conjunto com outros objetos decorativos. A Roda Gigante de Ferro Dourado é também uma ótima opção para presentear em datas especiais, simbolizando elegância, equilíbrio e movimento. Sua presença no ambiente transmite bom gosto e sofisticação, elevando o nível estético do espaço com um toque artístico e criativo. Seja para decorar a sua casa, escritório ou presentear alguém especial, esta peça é sinônimo de beleza, originalidade e qualidade. Informações do Produto Nome do produto: Decoração Roda Gigante de Ferro Dourado Giratória Material: Ferro Cor: Dourado metálico Altura: 23,5 cm Largura: 22 cm Função: Giratória Acabamento: Pintura metálica dourada Estilo: Moderno e sofisticado Indicação de uso: Sala, escritório, estante, aparador, quarto, hall de entrada Categoria: Decoração / Objetos Decorativos / Metálicos Diferenciais: Design exclusivo, estrutura resistente, movimento giratório funcional, acabamento premium', 64.99, 64.99, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh98seg5rqivb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341754426%2F52101734826', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
