INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201839615', 'Fichário Universitário com Elástico Hello - DAC', 'Fichário Universitário com Elástico Hello – DAC Doce, moderno e encantador! O Fichário DAC Hello é perfeito para quem ama papelaria delicada e funcional. Com capa dura plastificada em tons pastel e detalhes em hot stamp dourado, ele traz um visual leve e feminino, ideal para estudantes e amantes de organização. O sistema de argolas metálicas internas garante praticidade ao trocar ou adicionar folhas, e o fechamento com elástico rosa mantém tudo seguro e bem guardado. Acompanha 10 divisórias plásticas coloridas e 48 folhas brancas pautadas em papel offset, oferecendo conforto e qualidade na escrita. Um fichário cheio de estilo, resistência e personalidade — o acessório que transforma qualquer momento de estudo em um prazer visual! Ficha Técnica: Quantidade: 1 unidade Modelo: Hello Tamanho: Universitário – 24,5 cm x 30 cm x 4 cm Folhas: 48 folhas Coloridas pautadas Divisórias: 10 divisórias plásticas coloridas Furação: 4 furos Material das folhas: Papel offset Cor da folha: Decoradas nas pontinhas Cor da linha (pauta): Rosa Capa: Cartonado offset plastificado com Hot stamp Rosê Fechamento: Elástico rosa Argolas: Metálicas Tipo: Fichário com folhas removíveis Marca: DAC Palavras-chave: fichário hello dac, fichário feminino, fichário universitário pastel, caderno fichário dac, fichário com elástico, fichário decorado, papelaria criativa, caderno argolado dac', 143.9, 143.9, NULL, 'Stationery > School & Office Equipment > Folders, Paper Organizers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-822z5-mi5b191n1kau16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1042749449%2F58201839615', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44123020769', 'Almofada de Cabeceira Encosto Apoio para Lombar com Bolso Lateral 160x50x20cm BF Colchões', 'Conforto, ergonomia e versatilidade. A almofada de cabeceira da BF Colchões proporciona apoio ergonômico para a lombar. Feita com flocos de espuma, ela não afunda e ajuda a manter a postura correta enquanto você descansa. É perfeita para quem busca mais apoio e praticidade no dia a dia, ideal para ler, assistir TV, trabalhar no notebook ou simplesmente relaxar. Além da funcionalidade, tem alta durabilidade e traz um toque de charme e elegância para a sua cama, transformando o ambiente em um espaço mais aconchegante e sofisticado. Por que escolher a almofada de cabeceira BF Colchões? Conforto e qualidade: feita com flocos de espuma, que garantem estabilidade e suporte. Ideal para apoiar as costas e relaxar com bem-estar. Tecido de alta durabilidade: fabricado com tecido Jacquard, que oferece um toque macio e resistência. Bolsos laterais funcionais: espaço para guardar celular ou controle remoto, com saída para carregador que facilita seu uso no dia a dia. Design com capitonê: acabamento com botão revestido, que deixa a peça ainda mais elegante. Versatilidade: pode ser usada na cama, sofá ou poltrona, como encosto de leitura ou apoio para a lombar. Chega na sua casa enrolado, facilitando na entrega e transporte. Especificações do produto Tamanho: 160x50x20 Tecido: Jacquard Enchimento: Flocos de espuma Marca: BF Colchões Observações Pode ocorrer pequena variação de tonalidade na cor do produto devido às diferenças de iluminação e ambiente.', 344.37, 256.0, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfsreyuvx98l8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F44123020769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
