INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13033433580', 'Kit com 2 CIF Cremoso Original 250ml', 'O Kit contém: 2 CIF Cremoso Limpeza Milagrosa remove 100% da sujeira 250 ml cada. • Cif Cremoso Original é o produto de limpeza milagrosa que limpa fácil e dá brilho em mais de 100 superfícies*, removendo 100% da sujeira difícil, sem esforço • O Cif Cremoso Original possui um perfume suave, é mais concentrado e rende 7 garrafas do limpador comum • Fórmula com tecnologia poderosa que limpa sem riscar, removendo toda a sujeira desde a mais pesada até a limpeza de casa do dia a dia, deixando um brilho imbatível • Com o Cif, a limpeza nunca foi tão fácil e versátil. Cif Cremoso possui três variantes: Original, Limão e Laranja • Cif Cremoso Original é o produto de limpeza milagrosa para todo tipo de objeto como: eletrodomésticos, pias, couro sintético, borracha, plástico, porcelana e serve até como limpador de pisos • Cif promove uma limpeza milagrosa completa, com produtos versáteis que atendem a todas as suas necessidades. Cif. Sinta a limpeza acontecer!', 36.6, 36.6, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/0c52ccc7a1c2f930d05767f6d97a330f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F13033433580', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
