INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8561911896', 'Fita Isolante Líquida Quimatic 200ml Tapmatic Isola Impermeabiliza', 'Fita Isolante Líquida Preta Quimatic - 200 ml Descrição: - Fita Isolante Líquida Quimatic é uma composição de materiais isolantes elétricos, em solventes adequados, apresentado na forma líquida, para facilitar a aplicação e permitir a melhor cobertura e isolamento das conexões elétricas a serem protegidas. Informações Gerais: - Aplicável a pincel ou por imersão, numa espessura de 1 mm isola até 6.500 volts; - Adere a metais, borracha, plásticos, vidro e outros materiais; - Para todas as ligações elétricas de alta segurança; - Impede corrosão de fios e conectores. Fácil aplicação em fios de pequeno diâmetro; - Filme com alta elasticidade; - Não propaga a chama em estado seco; - Produto testado por laboratórios independentes; - Não propaga a chama em estado seco; - Facilmente aplicado em componentes elétricos com formatos irregulares; - Além de isolar também impermeabiliza, protegendo de umidade, água e corrosão, inclusive debaixo d’água ou sob intemperismo. Aplicações Sugeridas: - Para todo tipo de isolamento e impermeabilização de conexões elétricas; - Quando aplicado em conectores com parafuso impede o seu afrouxamento; - Pode ser usado como lacre de inviolabilidade. Especificações Técnicas: - Cor: Preto; - Tipo: Líquido viscoso; - Conteúdo: 200 ml; - Odor: Característico; - Densidade a 25ºC: 0,83 - 1,05 g/ml; - Solubilidade em água: Insolúvel; - Propagação de chama: Não propaga; - Isolamento: Até 6500 volts na espessura de 1 mm; - Ponto de fusão (Filme seco): 60ºC. Itens Inclusos: - 1 Fita isolante líquida preta Quimatic - 200 ml.', 165.0, 115.5, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6il0h91onyf1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F8561911896', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
