INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209077283', 'ESCOVA MASSAGEADORA COM DISCO PROTETOR', 'Escova massageadora elefante Ollie Marcus & Marcus A escova massageadora 360° é perfeita para ajudar os pequenos que estão no início da dentição, pois é feita em silicone alimentar e ajuda a aliviar o incômodo desta fase. A escova também ajuda a condicionar os bebês e crianças a terem uma rotina de saúde bucal, na companhia do Elefante Ollie! A cabeça 360° graus é feita em silicone e possui cerdas largas e super macias para proteção da gengiva. A escova massageadora vem com um escudo protetor, removível, que ajuda a evitar que a criança insira a escova no fundo da garganta. O cabo é anatômico pensado para pequenas mãos. A base tem sucção para armazenar a escova em pé. Livre de BPA e ftalato. Tem selo de destaque por inovação em design. INDICAÇÃO DE IDADE: a partir de 12 meses. COMPOSIÇÃO: 100% silicone, livre de BPA e ftalato. GARANTIA: 3 meses. LIMPEZA E CUIDADOS COM A PEÇA: lave bem antes do primeiro e após cada uso com água e sabão. Não utilize produtos de limpeza abrasivos que contenham clareadores. Pode ser esterilizado a vapor/UV. Este produto não é um brinquedo, deve ser usado sob a supervisão de um adulto. Inspecione o produto antes do uso e descarte-o e substitua ao menor indício de dano. Temperatura suportada: de -20°C a 120°C. CONTEÚDO DA EMBALAGEM: 1 escova com 1 disco de segurança do elefante Ollie. QTDE DE PEÇAS: 2.', 78.9, 78.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/br-11134207-820l9-mn5rlxmum41tcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1748002758%2F58209077283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
