INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22396903166', 'RELOGIO CASIO MASCULINO G-SHOCK GA700CA2ADR', 'ESPECIFICAÇÕES:- Hora mundial31 fusos horários mundiais (48 cidades + tempo universal coordenado), horário de verão (liga/desliga), troca de cidade de referência/hora mundial - CronômetroCronômetro de 1/100 de segundo Capacidade de medição: 23:59''59,99 Modos de medição: Tempo decorrido, tempo parcial, tempos do 1º e 2º lugares Outros: alarme de hora-meta, início direto da cronometragem a partir do modo de indicação das horas - contagem regressivaTemporizador Unidade de medição: 1/10 de segundo Faixa de contagem: 60 minutos Configuração inicial da faixa de contagem: 1 a 60 minutos (incrementos de 1 minuto) - Alarme/sinalização a cada hora5 alarmes diários (com 1 alarme soneca)Sinalização a cada hora - LuzIluminação de LED (Superiluminador) Duração da iluminação selecionável (1,5 segundo ou 3 segundos), fosforescência - Cor da luzLED: Branco - CalendárioCalendário automático completo (até o ano de 2099) - Recurso MudoAtivação e desativação do Som de operação dos botões - PrecisãoPrecisão: ±15 segundos por mês - Outros recursosFormatos de 12/24 horasRecurso de mudança do ponteiro (os ponteiros se afastam para fornecer uma visão desobstruída do conteúdo digital exibido.)Horário regular: Analógico: 2 ponteiros (hora, minutos (o ponteiro se move a cada 20 segundos)) Digital: hora, minuto, segundo, pm, mês, data, dia - VidroVidro mineral - Tamanho da caixa (C × L × A) 57.5 × 53.4 × 18.4 mm - Peso 69 g -Material da moldura/caixa: Resina -Pulseira em resina -Resistente a choques -Resistente à água a até 200 metros - Fonte de alimentação e autonomia da bateriaDuração aproximada da pilha: 5 anos em CR2016', 729.0, 729.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-7rblk-lltaf7hd126j41', 'https:/