INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26893527457', 'Conjunto de Panelas Antiaderente Safira Cristal 4 Peças Grafite MTA - 5663', 'Conjunto de Panelas Antiaderente Safira Cristal 4 Peças Grafite MTA - 5663 O Conjunto de Panelas MTA Safira Cristal 4 Peças na cor grafite é a escolha perfeita para quem busca qualidade, praticidade e elegância na cozinha. Fabricado em alumínio de alta durabilidade com revestimento antiaderente Superflon, oferece preparo uniforme dos alimentos e facilita a limpeza após o uso. As tampas de vidro temperado permitem acompanhar o cozimento sem perder o calor, enquanto os cabos e alças em baquelite antitérmico asseguram mais segurança e conforto no manuseio. Com design moderno e acabamento sofisticado, o conjunto Safira Cristal traz eficiência e estilo para o dia a dia, tornando o preparo das refeições ainda mais prazeroso. Especificações técnicas Marca: MTA Linha: Safira Cristal Quantidade de peças: 4 Cor: Grafite Material: Alumínio com revestimento antiaderente Superflon Tampas: Vidro temperado Cabos e alças: Baquelite antitérmico O conjunto acompanha: Panela com alças dupla No 18 - 18 L com tampa de vidro Panela No 16 - 1,4 L com tampa de vidro Frigideira Francesa No 18 - 0,7 L Fervedor No 12 - 1,0 L Imagens de caráter ilustrativo. Informações divulgadas de acordo com o manual do fabricante. Produto novo na caixa, lacrado com garantia do fabricante de 3 meses. Em caso de dúvidas sobre informações técnicas, utilização, limitações e manuseio do produto, verifique o manual do fabricante. EAN: 7897186656632 NAC013558', 180.84, 99.9, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-821d0-mgpcz724z6kr6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683223635%2F26893527457', NULL, NULL, '2026-07-28T02:11:31.708458+00:00')