INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698142607', 'KIT C/2 DESODORANTE DOVE CREME SÉRUM NIACINAMIDA PREVINE ESCURECIMENTO 50G', 'O Desodorante Creme Dove Sérum Previne Escurecimento Niacinamida oferece uma proteção eficaz contra o suor e odores por até 48 horas, enquanto cuida delicadamente da pele das suas axilas. Sua fórmula é enriquecida com ¼ de creme hidratante, vitamina B3 e niacinamida. Seus ativos exclusivos ajudam a manter a pele suave, hidratada e protegida contra o escurecimento. Ideal para quem busca um desodorante que não apenas protege, mas também cuida da saúde e beleza das axilas. Benefícios: - Previne escurecimento - Proteção de até 48 horas - Nutre e protege a pele - Protege contra a transpiração e o mau odor Modo de usar: Aplique uma pequena quantidade do desodorante creme Dove nas axilas limpas e secas. Espalhe uniformemente e deixe secar antes de se vestir.', 51.9, 51.9, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7ra40-m50gdsfis6z271', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F22698142607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3747448103', 'KIT Creme Facial Sensação Não Oleosa Antissinais + Noturno 100g Nivea - 2 Itens', 'Creme Facial Sensação Não Oleosa Antissinais + Noturno 100g Nivea - Kit C/2 Itens Creme Facial Antissinais Sensação Não Oleosa Nivea 100g - 1 Unidade O Creme Facial Nivea Antissinais foi desenvolvido para todos os tipos de pele, proporciona uma pele firme além de reduzir as linhas de expressões. Sua fórmula leve e de rápida absorção, contém Vitamina E que ajuda na prevenção de rugas, melhora a cicatrização, além de agir como um potente lubrificante e hidratante. Além disso protege contra os raios Uva e Uvb. Benefícios: - Hidratação intensa; - Livre de oleosidade; - Protege dos raios Uva/Uvb; - Rápida absorção; - Firma e reduz linhas de expressão. Creme Facial Cuidado Noturno Sensação Não Oleosa Nivea 100g - 1 Unidade O Creme Facial Nivea Cuidado Noturno foi desenvolvido para todos os tipos de pele, proporciona uma hidratação intensa, sem deixar a pele com aspecto oleoso. Sua fórmula leve de rápida absorção, contém Vitamina B5 que aumenta significativamente os níveis de glutationa nas células, atuando como um potente antioxidante na pele auxiliando a renovação cellular. Benefícios: - Hidratação profunda; - Livre de oleosidade; - Auxilia a renovação cellular; - Dermatologicamente testada; Modo de usar: Com a pele limpa e seca, aplique o Creme Facial Nivea Antissinais sobre todo o rosto, massageando suavemente em movimentos circulares até a completa absorção do produto.', 99.0, 99.0, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/a9c6da3229b4bba393bf21b0a7436201', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F3747448103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14436903183', 'Kit 2 Pares De Falantes 6x9 Pol 400w Rms Auto Orion', 'Kit 4 Alto Falantes 6x9 Polegadas Quadriaxial Leson Ls69 200w 4 Ohms Kit de alto falantes desenvolvido pela LESON, totalizando 200W de potencia RMS. Melhor custo beneficio do mercado, com excelente desempenho sonoro e qualidade, esse kit conta com 2 alto falantes de 6x9 polegadas . Com seu design moderno e diferenciado, esse kit vai acrescentar muito mais emocao a qualquer passeio de carro com suas musicas prediletas e completando perfeitamente o seu projeto de som. Especificacoes Tecnicas do Alto Falantes 6x9: Potencia RMS: 100W RMS (cada) Modelo Quadraxial Impedancia Nominal: 4 ohms Woofer de 6x9 Polegadas Material: Cone Polipropileno BB sensibilidade: 87 Db Resposta de frequencia: 37 a 20000Hz Bobina Simples Tweeter Piezzo Borda Emborrachada Cone com acabamento na cor cinza / preto Peso: 1,570 kg Dimensoes do falante: - Altura:17 Centimetros - Largura: 26,5 - Comprimento: 10,5 Centimetros Dimensoes da embalagem: -Altura: 13 cm -Largura: 27 cm -Comprimento: 33 cm Conteudo da Embalagem: 2 Pares Alto Falantes de 6x9 Polegadas LeSon', 259.99, 259.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/1f05e2dcf5a144fd5f652ce21031a948', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F625420381%2F14436903183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
