INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43211049175', 'Suporte de Guidão Ahead Set 31,8mm para Bike Rosa VEGA', 'O Suporte de Guidão Head Set Vega 31,8mm é ideal para quem busca controle, leveza e um visual diferenciado na bicicleta. Compatível com guidões de 31,8mm e garfos com sistema head set, oferece fixação segura e desempenho confiável, seja em uso urbano ou trilhas leves. Fabricado em alumínio de alta resistência, combina durabilidade com baixo peso. O acabamento em rosa anodizado proporciona um visual moderno e elegante, além de proteção contra oxidação e desgaste. Fácil de instalar, é uma ótima opção para personalização ou upgrade. Especificações técnicas: Comprimento: 90mm Compatível com guidão de 31,8mm Para garfos com sistema head set Cor: Rosa anodizado Material: Alumínio Marca: Vega', 89.0, 32.89, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdwd-mcuosb8uwrpc0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F43211049175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897733688', 'Limpeza dos Ouvidos Pet Propcalm Otológico Soft Care - 100mL', 'Propcalm Soft Care Otológico - 100mL Enriquecido com extrato de própolis que protege a pele do ouvido sensível. Higieniza e neutraliza odores indesejáveis, remove excesso de cerúmen e possui PH balanceado. Indicação: Indicado para higienização do conduto auditivo de cães e gatos. Modo de Usar: Uso tópico. Instilar o produto dentro do conduto e massagear bem. Retirar o excesso da parte externa da orelha com ajuda de algodão ou gaze. Utilizar de 2 a 3 vezes por semana ou conforme indicação do médico veterinário. Precauções: Evitar a ingestão ou contato com os olhos. Conservar em local seco, fresco e arejado, ao abrigo da luz solar direta e fora do alcance de crianças. Armazenar longe de alimentos e bebidas. No caso de contato com os olhos enxaguar abundantemente. Ingredientes: Água, Extrato de Própolis, Ácido Glicirrízico, Oléo Essencial de Menta, , Oléo Essencial de Própolis.', 68.9, 62.01, NULL, 'Pets > Pet Grooming > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyf-lzhph2cd83p3ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F23897733688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
