INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56503240260', 'Kit 6 Refletor Led 150w Luz Externa Comercio Branco Frio 6500k Bivolt 127v 220v Avant', 'Você está comprando: 06 Refletores Led 150w Slim Avant Refletor LED 150W Slim Avant 6500K Bivolt – Alta Potência e Máxima Eficiência Ilumine seus ambientes com muito mais potência, economia e durabilidade com o Refletor LED 150W Slim Avant. Desenvolvido para oferecer alto desempenho luminoso, ele é ideal para aplicações comerciais, corporativas e residenciais, garantindo iluminação intensa e uniforme com luz branca fria 6500K, perfeita para valorizar espaços e aumentar a visibilidade. Seu design slim, aliado ao corpo em alumínio com difusor em vidro, proporciona excelente dissipação de calor e maior vida útil. Com driver incorporado e fluxo luminoso constante, o refletor mantém a performance mesmo com variações de tensão. Além disso, é um produto ecologicamente correto, livre de mercúrio e sem emissão de raios UV, não desbotando objetos ou superfícies. Com 11.250 lúmens, baixo consumo de energia e vida útil aproximada de 25.000 horas, o Refletor Avant é a escolha certa para quem busca eficiência, segurança e ótimo custo-benefício. Ideal para quem precisa de iluminação potente, confiável e econômica, o Refletor LED 150W Avant entrega desempenho profissional com a qualidade de uma marca reconhecida no mercado. Especificações Técnicas potência: 150W Luz branca fria 6500K, clara e eficiente Bivolt automático (127V / 220V) IP65 – resistente à poeira e respingos de água Não emite ultravioleta (não desbota objetos) Baixo consumo de energia Não dimerizável Marca: Avant Modelo: SLIM150 Código: 259651378 Potência Nominal: 111,5 ~ 150W Fluxo Luminoso: 11.250 lúmens Eficiência Luminosa: 75 lm/W Ângulo de Abertura: 120° Índice de Reprodução de Cor (IRC): >80 Índice de Proteção: IP65 Material: Corpo em alumínio e difusor em vidro Tipo de Instalação: Sobrepor Vida Útil: 25.000 horas Temperatura de Operação: -5°C a 40°C Garantia de 1 ano pelo fabricante Dimensões Aproximadas por Refletor: A: 178mm C: 206mm L: 24,5mm Peso: 550g ATENÇÃO: (as medidas podem variar 5% para mais ou menos de acordo com o próprio fabricante)', 329.99, 299.99, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-8259w-mqlusvvjy4240c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F56503240260', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
