INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254785864', 'Espaçador Nivelador Slim 1mm 1000 Peças Cortag', '- 1000 NIVELADORES SLIM CORTAG - Facilita a instalação de revestimentos cerâmicos, sevem para igualar as peças diminuindo imperfeições no assentamento, garantindo que sua obra tenha um acabamento de alta qualidade. INFORMAÇÕES TÉCNICAS NIVELADOR: - Marca: Cortag; - Cor: Verde, Vermelho e Azul; - Material: Produzido em polipropileno (PP). DIMENSÕES NIVELADOR: - Altura: 35mm; - Largura: 24mm; - Espessura: 1mm; - Diâmetro interno: 13mm. SOBRE O PRODUTO: - Não arranha o piso; - Produzido em polipropileno (PP); - Nivela e espaça ao mesmo tempo; - Fabricado com matéria prima 100% virgem; - Compatível com diversos tipos de pisos e espessuras; - Fácil de utilizar não precisa de mão de obra especializada; - Reduz em até 50% o tempo de colocação de revestimentos cerâmicos. CONSUMO MÉDIO POR M²: - Pisos de 60x60 será utilizado 12 espaçadores; - Pisos de 40x60 será utilizado 17 espaçadores. MODO DE INSTALAÇÃO: 1º Passo: Inserir o espaçador/nivelador de revestimento; 2º Passo: Assentar o revestimento; 3º Passo: Inserir cunha; 4º Passo: Retirar as peças após a cura total da argamassa; 5º Passo: Bater Lateralmente na cunha com martelo de borracha para remoção espaçador.', 162.56, 94.21, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-825zl-mke338t7nk0837', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328278916%2F58254785864', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
