INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205048899', 'Rack De Teto Bagageiro Ford Fusion 2006 07 08 09 2010 - Pret', 'Rack de Teto Bagageiro Suporte Fixação Porta para Ford Fusion - VHIP Compatibilidade: ANOS: 2006, 2007, 2008, 2009, 2010 Quer mais espaço para VIAJAR, TRABALHAR ou levar seus equipamentos com SEGURANÇA? O Rack Teto Bagageiro Porta - VHIP é a escolha PERFEITA para quem busca praticidade, resistência, SEGURANÇA e visual moderno. Com capacidade para até 50 kg de carga, ele permite transportar malas, bicicletas, pranchas, caixas de ferramentas ou materiais de trabalho com total segurança e estabilidade, sem ocupar o espaço interno do veículo. Além disso a VHIP oferece a QUALIDADE atestada pela CERTIFICAÇÃO de Processo ISO 9001, FIQUE ATENTO antes de compra! POR QUE O RACK VHIP SEM DÚVIDAS É O MELHOR VENDIDO NO BRASIL: - Com Sistema antifurto exclusivo, que dificulta a remoção indevida e protege seu investimento. - Certificação ISO 9001 – segue padrões internacionais de qualidade e rastreabilidade. - Design esportivo com acabamento perfeito – visual moderno e elegante. - Parafusos em aço liga 12.9 – material de alta resistência e durabilidade. - Estrutura reforçada – suporta até 50 kg com segurança. - Pintura em poliéster – resistente à ferrugem e à corrosão, prolonga a vida útil. - Encaixe perfeito – instalação precisa, sem folgas (Seguir orientações do Manual de Instalação) - Não risca o carro – protege a pintura original (Seguir orientações do Manual de Instalação). - Não fura o teto – fixação inteligente sem necessidade de perfurações. - Altura ideal – evita contato e acidentes com o teto do veículo. - Haste de ajuste de pressão fixa – não solta, não trepida, garante estabilidade. - Produto novo e com garantia – segurança total na compra. VANTAGENS: - Mais segurança contra furtos graças ao sistema antifurto patenteado que dificulta a remoção. - Proteção contra ferrugem e intempéries com pintura automotiva de qualidade premium. - Instalação simples e sem danos ao veículo. - Durabilidade MUITO SUPERIOR aos racks comuns, por usar materiais de padrão industrial e seguindo normas ISO9001 no processo de produção - Estabilidade e silêncio durante o uso, sem trepidações. Ficha técnica: Peso suportado: até 50 kg Material Suporte: Aço Certificado com acabamento em pintura Poliéster Material Tubo : Aço Certificado Galvanizado Fixação: Na porta Cor: Preto fosco Instalação: Sistema de aperto rápido com proteção anti risco. Itens inclusos: 1 - Par de racks completos (2 barras) 1 - Kit de fixação com parafusos, arruelas e porcas 1 - Manual ilustrado para instalação Compre direto da nossa LOJA OFICIAL VHIP ACESSÓRIOS, atendemos todo Brasil com RAPIDEZ, QUALIDADE E TODO SUPORTE QUE VOCÊ MERECE! DUVIDAS SOBRE INSTALAÇÃO ? TEMOS EXCLUSIVO CANAL - CENTRO de APOIO TÉCNICO AGORA CLIQUE EM COMPRAR ou se tiver ALGUMA DÚVIDA FAÇA SUA PERGUNTA E RESPONDEREMOS RAPIDAMENTE : ) ver ALGUMA DÚVIDA FAÇA SUA PERGUNTA E RESPONDEREMOS RAPIDAMENTE : )', 294.88, 294.88, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Racks and Cargo Carrier', 'https://cf.shopee.com.br/file/sg-11134201-825aa-mqxs4ogespvk17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1665097804%2F58205048899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292943033', 'MOTOR DO LIMPADOR FORD FOCUS - 12V', 'MOTOR DO LIMPADOR SE QUISER CONFIRMAR A APLICAÇÃO ANTES DA COMPRA, PODE CONTAR COM A GENTE. VOCÊ PODE: CONFERIR O CÓDIGO ORIGINAL DA PEÇA OU, SE PREFERIR, ENVIAR UMA FOTO AQUI NO CAMPO DE PERGUNTAS RESPONDEMOS COM ATENÇÃO E RAPIDEZ PRA TE AJUDAR A ACERTAR NA ESCOLHA. ESPECIFICAÇÕES TÉCNICAS · VOLTAGEM: 12V CÓDIGOS ORIGINAIS · FORD FOCUS/ 17508 / TRICO CÓDIGOS SIMILARES APLICAÇÃO FORD FOCUS | ANO DE 2007 Á 2009 - 12V REFERÊNCIA · CEMAK: CK-6.074 GARANTIA 3 MESES INFORMAÇÕES IMPORTANTES PRODUTO NOVO ACABAMENTO DE ALTA QUALIDADE BOA DURABILIDADE PARA USO NO DIA A DIA DA OFICINA ANTES DA COMPRA PARA GARANTIR A APLICAÇÃO CORRETA, RECOMENDAMOS: CONFERIR O CÓDIGO ORIGINAL DA PEÇA COMPARAR COM AS IMAGENS E ESPECIFICAÇÕES DO ANÚNCIO SE PREFERIR, PODE NOS CHAMAR NO CAMPO DE PERGUNTAS FICAMOS À DISPOSIÇÃO PRA TE AJUDAR A CONFIRMAR ANTES DA COMPRA. INSTALAÇÃO A INSTALAÇÃO DEVE SER REALIZADA POR PROFISSIONAL QUALIFICADO. ISSO GARANTE O MELHOR DESEMPENHO DA PEÇA E EVITA QUALQUER TIPO DE PROBLEMA NO SISTEMA. SOBRE ATENDIMENTO E SUPORTE SE HOUVER QUALQUER DÚVIDA OU NECESSIDADE APÓS A COMPRA, PODE CONTAR COM A GENTE. EM CASO DE DIVERGÊNCIA EVITE UTILIZAR-SE DO CAMPO RECLAMAÇÃO, NESTE CASO, NOS CHAME PELO CHAT QUE NOSSA EQUIPE ESTÁ PRONTA PRA TE AJUDAR DA FORMA MAIS RÁPIDA E SIMPLES POSSÍVEL. INFORMAÇÕES DO PRODUTO TODAS AS INFORMAÇÕES TÉCNICAS SÃO FORNECIDAS PELO FABRICANTE. SOBRE A PEÇA DO MECÂNICO A PEÇA DO MECÂNICO TRABALHA COM FOCO EM QUEM VIVE DA MECÂNICA E PRECISA DE AGILIDADE, CLAREZA E CONFIANÇA NO DIA A DIA. SE SURGIR QUALQUER DÚVIDA ANTES OU DEPOIS DA COMPRA, PODE CHAMAR. A IDEIA É FACILITAR SEU TRABALHO.', 240.0, 240.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rceq-ltk6kl41hkd74e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1213682031%2F22292943033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597570025', 'Alimento Quatree Life Ração Cão Adulto Médio e Grande Frango e Arroz 15Kg Premium Especial Cachorro', 'Para aqueles que dedicam todo o amor e cuidado aos seus cães, oferecer a melhor alimentação é fundamental. Quatree Life Cão Adulto Médio e Grande Frango e Arroz proporciona uma nutrição completa e balanceada, ideal para garantir a saúde e o bem-estar dos cães de porte médio e grande. Com uma combinação saborosa de frango e arroz, este alimento premium oferece proteínas de alta qualidade e carboidratos de fácil digestão. Ingredientes selecionados, enriquecidos com vitaminas e minerais, promovem uma pele saudável, um pelo brilhante e um sistema imunológico fortalecido. A digestibilidade superior de Quatree Life assegura que seu cão aproveite ao máximo cada refeição, absorvendo todos os nutrientes necessários para uma vida ativa e saudável. Cada refeição se torna um momento de prazer, contribuindo para a energia e vitalidade que seu cão precisa para brincar e explorar. Cuidar da alimentação do seu cão é uma forma de demonstrar amor e carinho. Escolher Quatree Life Cão Adulto Médio e Grande Frango e Arroz é optar por uma dieta rica e equilibrada, que apoia a saúde, a longevidade e a felicidade do seu companheiro de quatro patas. PERGUNTAS E RESPOSTAS Quais são os principais benefícios de Quatree Life Cão Adulto Médio e Grande Frango e Arroz? Quatree Life oferece uma nutrição completa e balanceada, promovendo uma pele saudável, pelo brilhante e um sistema imunológico fortalecido. Como Quatree Life Cão Adulto Médio e Grande Frango e Arroz contribui para a saúde do meu cão? Os ingredientes de alta qualidade, como frango e arroz, garantem a absorção de nutrientes essenciais, proporcionando energia e vitalidade para uma vida ativa e saudável. Quatree Life Cão Adulto Médio e Grande Frango e Arroz é indicado para todas as raças de cães médios e grandes? Sim, Quatree Life é formulado para atender às necessidades nutricionais de cães adultos de porte médio e grande, oferecendo uma dieta balanceada e saborosa. Como a combinação de frango e arroz em Quatree Life beneficia meu cão? A mistura de frango e arroz oferece proteínas de alta qualidade e carboidratos de fácil digestão, essenciais para a manutenção da saúde e da energia do seu cão. Quais são os ingredientes principais de Quatree Life Cão Adulto Médio e Grande Frango e Arroz? Quatree Life é feito com frango, arroz, vitaminas e minerais essenciais, todos cuidadosamente balanceados para promover a saúde e o bem-estar do seu cão.', 235.18, 185.33, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-7rd4p-lvsz6m8z8ewef4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1194006916%2F22597570025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398259729', 'KIT BODY SPLASH FEMININO SUCCES VERT + INFALIVEL 200ML - PRIMACIAL PERFUME CITRICO FLORAL', 'Kit Body Splash Succès Vert + Infalível Perfume Feminino Duplo | Frescor e Presença na Medida Certa Um kit com duas fragrâncias que se complementam perfeitamente: uma mais leve e refrescante para o dia, e outra mais intensa e marcante para momentos especiais. Ideal para quem quer estar sempre perfumada, variando entre leveza e presença ao longo do dia. Sobre as Fragrâncias: Succès Vert – Fresco, leve e sofisticado Uma fragrância com abertura cítrica e sensação revigorante. Perfeita para o dia a dia, trabalho e momentos em que você quer leveza e energia. Pirâmide Olfativa: Topo: Limão Siciliano, Bergamota, Cedro Coração: Jacinto, Pimenta Rosa, Jasmim Fundo: Patchouli, Almíscar, Vetiver, Âmbar Infalível – Marcante, feminino e sedutor Uma fragrância intensa e envolvente, com perfil floral frutado e fundo quente. Ideal para quem quer chamar atenção e deixar um rastro elegante e memorável. Pirâmide Olfativa: Topo: Jasmim, Maçã Vermelha e Pêssego Coração: Magnólia, Framboesa, Rosa e Muguet Fundo: Fava Tonka, Baunilha, Âmbar e Musk Quando Usar: 🌤️ Dia: Excelente (Succès Vert) 🌙 Noite: Excelente (Infalível) 📦 Detalhes do Produto: ✔ Contém 2 body splashes de 200ml cada ✔ Fragrâncias femininas versáteis ✔ Perfis complementares (fresco + marcante) ✔ Ideais para reaplicação ao longo do dia ✔ Excelente custo-benefício em kit 💡 Dica de uso: Use o Succès Vert durante o dia para frescor e leveza, e o Infalível à noite ou em momentos especiais para mais presença. Você também pode alternar conforme o seu estilo ou ocasião.', 120.0, 79.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb5n1765prllfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F21398259729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53802611224', 'Kit de Modelagem de Carimbo para Sobrancelhas com Um Passo, Maquiagem em Pó para Sobrancelhas com Carimbo e 10', 'Marca: ibcccndc Pessoas aplicáveis: todos os tons de pele Prazo de validade: 3 anos Cor: marrom claro, marrom natural, marrom escuro Característica: 1. Mini conveniência, textura fina, cor natural 2. Cabeça de cogumelo macia, aderência firme do pó, iniciantes podem colorir rapidamente 3. Pegue o pó rapidamente (pegue o pó na tampa) Como usar: 1. Gire e abra a tampa. Mergulhe a cabeça de cogumelo na maquiagem em pó dentro da tampa e misture naturalmente ao longo da linha do cabelo, ponte do nariz e mandíbula, de dentro para fora. 2. Ou use um cartão de sobrancelha para preencher o cartão de sobrancelha e desenhar uma forma de sobrancelha natural.', 26.0, 20.0, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-822xr-mhzr34p2uio852', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F53802611224', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57064643917', 'Fones de ouvido Bluetooth 5.0 TWS à prova d''água, indicador de bateria LED, som HiFi, microfone ENC, chamadas HD', 'Oi! Bem-vindo(a) à Loja Oficial da SPRISE! Leia a descrição do produto com atenção, escolha o que você precisa. Todos os itens estão em estoque! Aproveite~. ❥Passos para conexão Bluetooth: 1. Pressione longamente o botão Reproduzir/Pausar até que a luz LED comece a piscar. 2. Abra as configurações Bluetooth no seu telefone e procure por "DR58", clique em "DR58" para emparelhar. 3. Após o emparelhamento bem-sucedido, o telefone exibirá a mensagem "emparelhamento bem-sucedido" e o fone de ouvido exibirá "conectado". Nota: A redação exata pode variar ligeiramente dependendo do seu dispositivo e sistema operacional. ❥Especificações: 1. Nome: SPRISE DR58 2. Cor: Branco Dolomita/Preto Atenas/Rosa Suave 3. Peso: 279g 4. Versão Bluetooth: 5.0 5. Distância de comunicação: 10m 6. Tempo de conversação: 12 horas 7. Tempo de carregamento: 3-4 horas 8. Compatível com: Android, iOS, macOS e Windows ❥Características: 1. Qualidade de som avançada HIFI proporciona uma experiência musical ao vivo como pessoalmente; com protetores auriculares respiráveis e agradáveis à pele, confortáveis de usar sem pressão nos ouvidos. 2. Design dobrável, fácil de transportar; material metálico preferido, resistente à pressão e à violência. 3. O fone de ouvido Bluetooth para jogos com ultra baixa latência, à prova d''água e à prova de suor, com um cabo de áudio para proporcionar a melhor experiência de vida boa. ❥Lista de produtos: 1* Fone de ouvido Bluetooth 1* Cabo de carregamento Tipo-C 1* Cabo de áudio 1* Manual do usuário', 115.7, 89.0, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134253-8258o-mqxrt9e3slqca3', 'https://shope.ee/an_redir