INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26868050672', 'Kemei Recarregável Elétrico Orelha E Nariz Aparador De Pêlos Profissional Indolor Sobrancelha Trimmer Para Homens Mulher', 'Ferramenta de aparar preciso: o aparador de cabelo do nariz usa um sistema giratório de 360 graus de lâminas de dupla borda com proteção de aço inoxidável para uma remoção de cabelo suave, precisa e segura sem puxar dolorosa ou desagradável. Porta de carregamento tipo c: você pode usar o aparador não importa em que país você esteja, usado com um adaptador de 5V (adaptador não incluído). Facil de limpar: A cabeça é removível e lavável, com escova de limpeza, fácil de remover resíduos de cabelo. O aparador de pelos do nariz do nariz do aparador de cabelo pode enxaguar diretamente sob água corrente. Nota: Por favor, seque antes da instalação para evitar ferrugem. Família e Amigos: Uma escolha melhor. Equipe profissional de pós-venda, caso tenha algum problema, entre em contato conosco por e-mail para resolver o problema o mais rápido possível. ​Marca kemei ​ ​Tipo de alimentação: Recarregável ​ ​Uso: cabelo de orelha de nariz ​ ​Tensão de tensão: 100-240V ​ ​Tempo de carregamento: 1,5 horas ​ ​Tempo de trabalho: 120 minutos ​ ​Potência: 2w ​ ​Número do modelo KM-323 ​ ​Motor muito poderoso, Motor: muito poderoso, ​ ​Cor da imagem no show da página do produto: como a imagem na página do produto ​ ​Conteúdo da Embalagem ​ ​1 x máquina ​ ​1 x Pincel ​​ ​1 x cabo de carga ​ ​1 x manual ​', 124.0, 61.0, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m2rtwcttka1z09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450997010%2F26868050672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
