INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797737622', 'Kit Dumont Feminino Lady Dourado - DU2036MFS/K4C', 'Kit Dumont Feminino Lady Dourado - DU2036MFS/K4C Desde 1987, os relógios Dumont são vistos pelas pessoas não mais como máquinas que marcam as horas, mas como acessórios de moda que permitem que seus usuários, através do design e beleza de cada peça, componham seus próprios estilos. • Tamanho da Caixa: 36mm • Cor do Mostrador: Prata • Material da Pulseira: Aço 304 • Cor da Pulseira: Dourado • Movimento: Analógico • Resistência à Água: 5 ATM • Autenticidade: Produto 100% original com garantia de fábrica • Conteúdo da Embalagem: Relógio, manual e certificado de garantia • Garantia: 12 meses Compre este lindo Relógio na Loja Oficial da Technos no Mercado Livre com a segurança que só uma Loja de Fábrica pode oferecer. LOJA DE FÁBRICA – PRONTA ENTREGA COM ENVIO IMEDIATO. ATENÇÃO: A caixa e as semijoias que acompanham o relógio serão enviadas conforme a disponibilidade em estoque. Podem ser iguais às imagens apresentadas neste anúncio ou podem variar. Agradecemos a compreensão! Garantia de fábrica: 12 meses', 299.0, 199.0, NULL, 'Watches > Women Watches', 'https://cf.shopee.com.br/file/sg-11134201-8262y-mjr9jle2qbr7ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1332527814%2F22797737622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
