INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893535383', 'Laços Natalino Decoração de Natal Arvore Enfeite Lacinhos Vermelho Dourado Natal Laço VMP', 'O Laço Natalino é uma peça charmosa e elegante, que traz todo o espírito de natal para a decoração. Feito com fitas de tecidos especiais, como cetim, organza ou veludo, é ideal para enfeitar árvores de Natal, presentes, guirlandas ou até mesmo para complementar arranjos de mesa. Com seu formato volumoso e cores vibrantes — como o vermelho, dourado— o laço adiciona um toque sofisticado e acolhedor, simbolizando a alegria e a união dessa época tão especial. Seja simples ou elaborado, o Laço Natalino é um item essencial para quem deseja criar um ambiente festivo, repleto de beleza e harmonia durante as comemorações KIT 12 Laços Dourado: 5x5cm KIT 12 Laços Vermelho Camurçado: 5cm KIT 18 Laços Vermelho Camurçado: 6cm KIT 6 Laços Camurçado: 7,5cm', 16.9, 9.9, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2qqe8vcudc546', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F22893535383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
