INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998324722', 'Chá Pêssego Drinks Leão 10 Sachês', 'Não perca mais tempo preparando drinks. A Leão mais uma vez inova no mercado nacional oferecendo sachês para preparo de drinks nos sabores pêssego e morango e hortelã para preparo em água quente, fria ou direto para finalizar a sua bebida alcóolica. Uma bebida versátil que pode ser preparada tanto em água quente, fria ou até mesmo direto na bebida alcóolica. Testado em Vokda, Gin, Whisky, Espumante e água com e sem gás. O Match entre o Chá e o Drink Em um recipiente você mistura uma dose de animação, dois ramos de aventura e uma colher de gargalhadas. Acrescente os seus melhores amigos e uma porção de bons momentos Uma bebida versátil de Leão que pode ser preparada tanto em água quente, fria ou até mesmo direto na bebida alcóolica para animar o seu esquenta!. Ingredientes: Flores de hibisco (Hibiscus sabdariffa L.), frutos da maçã (Pyrus malus L.), casca dos frutos da laranja amarga (Citrus aurantium L.), folhas de estévia (Stevia rebaudiana Bert), raíz de chicória (Cichorium intybus L.), frutos do pêssego (Prunus persica (L.) Batsch.) e aromatizantes.', 13.94, 13.25, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/sg-11134201-7rd3p-m7co5863j0dld4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F22998324722', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
