INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399714698', 'Sapateira Giratoria Esthela Com Espelho Amendoa Clean Lopas', 'A Sapateira Esthela é uma peça elegante e funcional, ideal para organizar seus calçados com estilo. Com um design moderno e sofisticado, esta sapateira conta com um espelho integrado, proporcionando praticidade e adicionando um toque de beleza ao ambiente. Características Principais: Capacidade: Armazena até 20 pares de calçados. Espaço de Armazenamento: 6 nichos amplos para uma organização eficiente. Materiais de Alta Qualidade: Estrutura em MDF/MDP, com acabamento em pintura UV fosca. Estabilidade: Possui sapatas niveladoras para garantir firmeza e estabilidade. Detalhes Adicionais: Estilo: Moderno Garantia: 3 meses Acabamento: Pintura UV fosca na estrutura e brilhante na porta. Dimensões: Altura: 187 cm Largura: 65 cm Profundidade: 65 cm Peso: 37,34 kg Capacidade de Peso: Suporta até 60 kg, com peso máximo por prateleira de 10 kg. Informações Complementares: Fabricante: Móveis Lopas Marca: Móveis Lopas Cor: Amêndoa Clean Ambiente Principal: Quarto Itens Inclusos: 1 Sapateira Esthela, manual de montagem e kit de ferragens. Origem do Produto: Nacional Pés: Não possui Tipo de Porta: Correr com dobradiças/corrediças metálicas. Possui Espelhos: Sim, na porta frontal. Esta sapateira é a adição perfeita para qualquer espaço de entrada ou quarto, combinando funcionalidade e estética de forma harmoniosa. Garanta a organização dos seus calçados com a Sapateira Esthela, um produto que une qualidade e design moderno para valorizar ainda mais o seu ambiente.', 633.4, 579.9, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rfi2-m98yvp0q1xspc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1372644554%2F21399714698', NULL,