INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4483101812', 'Cabo Rca Prime Dupla Blindagem Modulo 5 Metros 5mm Vermelho', 'CABO RCA 5 METROS 5 MM DUPLA BLINDAGEM TECH ONE Turbine e explore todo o potencial de som do seu veículo. O cabo RCA Prime, disponível nas cores vermelho e azul, é revestido em borracha, possui alta capacidade de condução, proteção interna contra ruídos, um ótimo isolamento elétrico e seu condutor de cobre é livre de oxigênio. Eficiente e de alta duração, o cabo tem todos os elementos necessários para um projeto de alta definição. Acompanha cabo com injeção de plástico interno, que proporciona maior reforço ao produto. ESPECIFICAÇÕES: • Diâmetro: 5mm• Comprimento: 5 Metros • Cores: Vermelho / Azul • Conectores duplos de alta pressão banhados a ouro químico • Conectores de plástico injetado para uma melhor qualidade na transmissão do som • Fio de cobre (AAC) livre de oxigênio (OFHC: oxygen free hign thermal conductivity) • Isolamento dieléctrico • Protecção interna contra ruídos • Cortes polidos no encaixe do plug que evitam ruídos por trepidação • Malha interna trançada com dupla blindagem e contra interferência externa IMPORTANTE: - 3 meses de garantia - Valor Unitário - Imagem Ilustrativa', 63.0, 63.0, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/63577813d2a38a123b7478df42ee097e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320239269%2F4483101812', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
