INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209225477', 'Máquina De Solda Inversora 120a Eletrodo Ip21s Com Máscara', 'MÁQUINA INVERSORA DE SOLDA 120A 220V MMA ELETRODO 2,5MM CICLO IP21S PORTÁTIL TOPARC 2.5 - Galzer DESCRIÇÃO: Inversora de solda compacta e portátil, indicada para soldagem MMA com eletrodo revestido, oferecendo regulagem intuitiva de corrente para melhor ajuste conforme o eletrodo e o trabalho. Possui ventilação forçada, painel simples de operar e engates rápidos para conexão do porta eletrodo e grampo terra, ideal para manutenção, serralheria e trabalhos gerais com praticidade e desempenho. VANTAGENS: - Tensão em vazio de 65V para melhor abertura e estabilidade do arco - Classe de proteção IP21S para maior segurança em uso adequado - Sistema de refrigeração a ar (fan) para auxiliar na durabilidade - Leve e fácil de transportar, ideal para uso em diferentes locais - Faixa de corrente 20A a 120A para versatilidade de aplicação - Ciclo de trabalho eficiente: 120A@80% e 100A@100% ESPECIFICAÇÕES TÉCNICAS: - Eletrodo revestido: 2,5 mm (AWS E6013 e AWS E7018) - Ciclo de trabalho: 120A@80% / 100A@100% - Dimensões: 253 x 140 x 335 mm - Faixa de corrente: 20 - 120 A - Classe de proteção: IP21S - Corrente de entrada: 20 A - Tensão de entrada: 220 V - Tensão em vazio: 65 V - Peso: 3,25 kg CONTEÚDO DA EMBALAGEM: - 01 Inversora de solda TOPARC 2.5 - 01 Porta eletrodo - 01 Grampo terra - 01 Manual MARCA & MODELO: - Marca: Galzer - Modelo: TOPARC 2.5 + MASCARA DE SOLDA FOTOSSENSIVEL WH1000 Leve e com design equilibrado, esta máscara de solda protege o usuário de partículas volantes frontais, radiação ultravioleta, infravermelho e luminosidade intensa. Possui apoio para cabeça completamente ajustável, proporcionando maior conforto e menor fadiga. Possui escurecimento automático e protege o usuário de partículas volantes frontais, radiação ultravioleta, infravermelho e luminosidade interna. Dados Técnicos: - Estágio claro : DIN 3 - Estágio escuro : DIN 11 - Bateria Ions de Lítio - UV: DIN 16 - Sem regulagem SKU: KIT25291_23422', 499.9, 299.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lu-mna4otfgrfnl56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F58209225477', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22816294190', 'Mop Spray Com Reservatório Esfregão Vassoura Mágica', '🧼 Spray Mop com Reservatório – Limpeza Rápida e Sem Complicação! 🧽✨ Diga adeus aos baldes, vassouras e panos! O Spray Mop com reservatório é perfeito para quem quer praticidade, agilidade e eficiência na hora da limpeza. 💪🏽 ✅ Spray com acionamento no cabo – borrife seu produto de limpeza favorito com um simples clique! ✅ 4 em 1 – substitui vassoura, balde, pano e pá 🧹 ✅ Reservatório de 300ml – mais autonomia na limpeza 💧 ✅ Pano de microfibra lavável – reutilizável e fácil de trocar 🔁 ✅ Leve, compacto e fácil de guardar – pronto pra usar a qualquer momento! 🚀 Ideal para pisos frios, porcelanatos, laminados e outros tipos de superfície. 🏠 📦 Especificações: Contém: 1 Spray Mop Materiais: Metal, Plástico, Fibras Capacidade do reservatório: 300 ml Tamanho aproximado: 125cm (CABO) x 39cm x 13,5cm (A MEDIDA DO PANO DE MICROFIBRA) Cores sortidas (enviadas aleatoriamente) 🎨 ⚠️ Cuidados: Estrutura: pano úmido + pano seco Refil: lavável na máquina (até 40°C) 🧺 ❌ Não alvejar | Não passar | Não secar em tambor | Não limpar a seco 💡 Dica: tenha sempre um refil reserva e facilite ainda mais sua rotina!', 69.84, 37.99, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/br-11134207-820m2-mool78g30vsz1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F22816294190', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
