INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21359970832', 'Filtro Ar Audi A3 1.8 2002 2003 2004 2005 2006 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação A3 1.8 TURBO 180CV 3P AUT./ TIP. 2002 até 2003 A3 1.8 TURBO 180CV 3P MEC. 2002 até 2004 A3 1.8 TURBO 180CV 5P AUT./ TIP. 2002 até 2006 A3 1.8 TURBO 180CV 5P MEC. 2002 até 2006 Conteúdo Da Embalagem 1 Filtro de Ar Tipo de Veículo para Carros Marca Fundada em 1969, a Wega Motors Brasil possui sede própria em Itajaí/SC, com uma moderna instalação que produz uma ampla gama de produtos para o mercado de reparação automotiva na linha leve e pesada. A Wega Motors é certificada em Sistema de Gestão da Qualidade ISO9001 – Versão 2000 (pelo BVQI – Bureau Veritas Certification), certificação essa que abrange a fabricação e comercialização de filtros de óleo, ar e combustível, velas e acessórios. O Produto O Filtro de ar tem a importante função de proteger o motor de contaminantes, tais como poeira, fuligem, areia e outras impurezas. O filtro de ar separa e elimina essa impureza deixando o ar isento de partículas nocivas, esse ar que alimenta a câmara de combustão para efetuar a queima do combustível. Por isso o Filtro de Ar é importante para manter uma boa vida útil do seu veículo. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7798001698915 Código do Fabricante FAP4045_WEG >', 40.05, 40.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbm8-lly389u151sp39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F21359970832', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
