INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15368163915', 'Cubo Mágico 2x2 - Rubiks Mini', 'Descrição: O Cubo de Rubik 2x2 (também conhecido como mini cubo) consiste em 8 cubos de canto e funciona da mesma maneira que seu irmão maior - o Cubo de Rubik. Possui um novo mecanismo que resulta em um Cubo de Rubik mais suave, rápido e confiável. Pode parecer fácil, mas não se engane – ainda é um desafio. Como é menor que o cubo de Rubik tradicional, pode ser colocado mais facilmente em um bolso ou bolsa, tornando-o o item perfeito para levar em um ônibus, trem ou avião. Também é um ótimo presente para os entusiastas de quebra-cabeça mais jovens que podem não estar prontos para um Cubo de Rubik 3x3 completo. Características: Marca: Sunny Brinquedos Referência: Série: - Idade recomendada: A partir de 8 anos Usa Pilhas/Baterias ?: 0 Possui Luzes: Não Possui Sons: Não Dimensões aproximadas do produto: 14 x 5 x 8cm (A x L x C) Dimensões aproximadas da embalagem: 14 x 5 x 8cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Cubo Mágico Certificado Inmetro:REGISTRO 007585/2021 OCP 0006 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 79.99, 57.59, NULL, 'Hobbies & Collections > Toys & Games > Rubik''s Cubes', 'https://cf.shopee.com.br/file/0628e37391ca74d81fd590b51dafd0ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F15368163915', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
