INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393608998', 'Kit 2 Magic Retouch L''oréal Castanho Claro Spray Instantâneo para Retoque de Raiz 75ml', 'MAGIC RETOUCH L''ORÉAL CASTANHO CLARO SPRAY INSTANTÂNEO PARA RETOQUE DE RAIZ Cobre raízes brancas em segundos. Sai com shampoo. Seca rapidamente. Rende várias aplicações. Adapta-se à cor do cabelo: resultado homogêneo do aparente crescimento da raiz. Teste em um papel a força do spray antes de aplicar. Modo de usar: Agite bem antes de usar. Aplicar sobre o cabelo seco e penteado com o frasco na posição vertical a uma distância de 10 a 15cm do cabelo. Vaporizar ligeiramente sobre a raiz e os fios para que a cor fique uniforme. Em caso de aplicar quantidade em excesso, passe pente para remover.', 123.98, 123.98, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-823om-mojprfi38a2z81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22393608998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
