INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394053216', 'Mocassim Feminino Dakota G9221', 'Leve, confortável e versátil, o Mocassim Feminino Dakota G9221 é o calçado perfeito para mulheres modernas e elegantes. Com design clássico, ele é confeccionado em materiais de alta qualidade, garantindo durabilidade e estilo para o seu dia a dia. Ideal para compor looks casuais, o mocassim é uma opção prática e cheia de personalidade. Aproveite o melhor da moda com o Mocassim Feminino Dakota G9221.. MODELO: A0649221 REFERENCIA: G9221 MARCA: Dakota MATERIAL DA PALMILHA: PU MATERIAL DA SOLA: Borracha MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado GÊNERO: Female GRUPO DE IDADE: Adult TIPO DE SALTO: Grosso MEDIDA DO SALTO FRONTAL: 2,5 cm aproximadamente MATERIAL DO SAPATO: Sintético MEDIDA DO SALTO: 5 cm aproximadamente TIPO: MOCASSIM CLASSICO', 239.99, 239.99, NULL, 'Women Shoes > Flats > Loafers & Boat Shoes', 'https://cf.shopee.com.br/file/sg-11134201-7rat5-mabo6e0fsdbbaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F23394053216', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20861306203', 'Sandália Feminina Salto Alto Via Marte - 2217105', 'Desenvolvida para mulheres poderosas, a nova Sandália Feminina Salto Via Marte é uma ótima opção para completar um look cheio de glamour. É confeccionada em Nobuck com aplicações de glitter, fechamento por fivela, palmilha em PU, salto geométrico de dez centímetros e solado em borracha antiderrapante. A Sandália Via Marte é perfeita para produções de verão e está super em alta no mundo da moda. Gostou? Garanta a sua!. MODELO: 5837105 REFERENCIA: 2217105 MARCA: Via Marte MATERIAL DA PALMILHA: PU MATERIAL DA SOLA: Borracha GÊNERO: Female GRUPO DE IDADE: Adult MEDIDA DO SALTO: 10 cm aproximadamente MATERIAL DO SAPATO: Nobuck/Gliter ACABAMENTO: Colado/Costurado TIPO DE SALTO: Grosso', 143.99, 143.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-22110-8f6jywb6xojv1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F20861306203', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23507628718', 'Kit 2 Tenys Pé Baruel Talco Sport Edition 100g', 'TENYS PÉ BARUEL SPORT EDITION TALCO Tenys Pé Baruel talco é ideal para combater odores desagradáveis ocasionados por uso continuo de tênis ou sapatos que impedem que o seu pé respire normalmente. A formula exclusiva do Desodorante Para os Pés Tenys Pé Baruel talco é absorvida imediatamente pela pele o que mantém o seu pé seco, livre de resíduos e dos odores provocados pela transpiração. Não conviva mais com o desagradável “chulé”. Use o Desodorante Para os Pés Tenys Pé Baruel talco e não sinta mais vergonha de tirar o seu calçado em público. Modo de Usar: Aplique diariamente o produto nos pés. Pode ser aplicado também dentro do tênis ou calçado como proteção auxiliar.', 27.98, 27.98, NULL, 'Beauty > Hand, Foot & Nail Care > Foot Care', 'https://cf.shopee.com.br/file/sg-11134201-82580-mqmhs3jdn66a76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23507628718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
