INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14981238802', 'Panela Cozi Vapore Vapor Inox Allegra 20cm Tramontina', 'Panela Cozi Vapore Vapor Inox Allegra 20cm Tramontina Com o Cozi-vapore Tramontina Allegra em Aço Inox 20 cm de diâmetro 2,2 L os alimentos no vapor vão ficar muito mais gostosos! Produzido totalmente em aço inox, é altamente durável e mantém os alimentos saudáveis, pois o material não solta resíduos. É uma peça moderna com um estiloso acabamento em alto brilho, fácil de limpar e que pode ser lavada diariamente na máquina de lavar louças. Garanta o seu e cozinhe alimentos de forma muito mais fácil para sua família! Descrição do produto Marca: Tramontina Tipo: Filtro Material: Aço Inox Cor: Inox Linha Comercial: Allegra Diâmetro: Ø 20 cm Revestimento Interno: Sem revestimento Máquina de Lavar Louça: Sim Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 193.16, 129.65, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/feed93cb8757aec4a8d38279212987dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F14981238802', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
