INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792780741', 'Shampoo Tresemmé Tresplex 650ml', 'O Shampoo TRESemmé Tresplex é o segredo para cabelos saudáveis e fortalecidos. Sua fórmula profissional, enriquecida com queratina líquida e gluconolactona, restaura e condiciona os fios, devolvendo sua elasticidade e suavidade. Benefícios: - Proteção eficaz contra danos de processos químicos e aparelhos térmicos; - Fios 100 vezes mais fortes; - Restauração intra-capilar; - Regeneração TRESPLEX, que recupera a elasticidade e suavidade dos cabelos. Instruções de uso: Aplique o shampoo nos cabelos molhados, massageie suavemente e enxágue. Para resultados incríveis, repita o processo. Evite o contato com os olhos. Em caso de irritação, interrompa o uso e consulte um médico. Sobre a marca: TRESemmé tem uma tradição de 60 anos em beleza capilar, inicialmente disponível apenas em salões de beleza e agora acessível a todos. Oferecemos produtos de qualidade profissional para atender às necessidades das mulheres modernas no cuidado com seus cabelos.', 41.84, 40.31, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8257w-mqlyzewy23gh48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23792780741', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
