INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099007679', 'Filtro Gasolina KOMBI 1997/2005 - 43546 - FCI1620', 'Filtro Gasolina KOMBI 1997/2005 (Escolar / Furgão / Pick Up) - Motor 1.6 8v Álcool - / (Escolar / Lotação) - Motor 1.6 8v Gasolina - (Mecânico) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 27.91, 27.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822x5-mofripwtijgt98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18099007679', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697597234', 'MOTUL EZ LUBE SPRAY 300ML', 'Loja Ofical MOTUL A Motul é uma empresa francesa com mais de 165 anos de experiência na produção e distribuição de lubrificantes e fluidos de qualidade para motores. Ela é pioneira em inovação, tendo desenvolvido o primeiro lubrificante automotivo 100% sintético do mundo. Presente em mais de 160 países, a Motul chegou ao Brasil em 1992 e é conhecida por sua participação em competições automobilísticas de renome mundial. As pistas de corrida são o laboratório principal da empresa, onde seus produtos são testados em condições extremas antes de serem lançados no mercado. Representante OFICIAL MOTUL: BROOKLIN RACE uma das principais lojas de São Paulo referência no segmento automotivo em vendas de lubrificantes, pneus e acessórios para o segmento, com forte presença no shopee. Nosso compromisso é proporcionar uma experiência de compra excepcional, oferecendo produtos de alta qualidade a preços competitivos. Valorizamos o suporte ao cliente, estando disponíveis para auxiliar tanto na pré-venda quanto no pós-venda, garantindo que todas as dúvidas sejam esclarecidas e quaisquer problemas sejam prontamente resolvidos. Estamos empenhados em superar suas expectativas e tornar sua jornada conosco memorável. COMPRANDO ATÉ ÀS 16:00+ DESPACHAMOS NO MESMO DIA. DESENGRIPANTE ÓLEO MULTIUSO MOTUL - EZ LUBE 300 ML Características: Fabricante: MOTUL Formato de venda: Unidade Marca: Motul MPN: 112418 Unidades por kit: 1 O EZ LUBE é um desengripante com poder penetrante para soltar porcas, parafusos, cabos e sistemas oxidados. Também é um óleo multiuso que lubrifica todo tipo de mecanismo, alavancas, cabos, eixos, dobradiças, ...etc. Protege contra a corrosão por meio de película protetora. Repele água. Evita a umidade em circuitos elétricos, plugues, silenciadores, sistemas de partida ...etc.', 34.2, 30.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rdwn-lz0jjzr8596f7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F23697597234', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29842271107', 'Tênis Democrata Denim Beat Pulse Camurça Preto 623101-001 - Masculino', 'Sofisticação com conforto premium para todas as horas! Tênis Democrata Denim Beat Pulse Camurça Preto - Masculino Ficha Técnica: Marca: Democrata Gênero: Masculino Cor: Preto Cabedal: Couro com detalhes perfurados, pespontos e recortes em camurça Bico: Arredondado Palmilha: Macia em PU Forro: Têxtil Solado: TPU leve e confortável Altura: 4,5 cm Fechamento: Cadarço de amarrar Indicação: Dia a dia, trabalho e eventos casuais Detalhes específicos: Tecnologia Pulse para maior conforto e retorno de energia, detalhe do 1983 na lateral simbolizando o início da marca, logo da marca no calcanhar, design contemporâneo e versátil da linha Denim Estilo versátil com toque refinado e conforto que surpreende! O Tênis Democrata Beat Pulse une elegância e praticidade com um design moderno e leve. Por que investir? Feito em couro com detalhes perfurados e pespontos que valorizam o visual, o modelo conta com palmilha em PU e solado em TPU, garantindo conforto e leveza a cada passo. A tecnologia Pulse oferece um caminhar mais suave e estável, ideal para quem busca bem-estar o dia todo. Um tênis versátil que transita com facilidade entre o trabalho e o lazer. Conteúdo da embalagem: 1 par de Tênis Democrata Denim Beat Pulse Camurça Preto - Masculino', 399.99, 289.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824j1-mf4btof5zuvf85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F29842271107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494063709', 'Kit Pantene Restauração Shampoo 350ml + Condicionador 175ml + Creme Para Pentear 240g', 'O Kit Pantene Restauração Shampoo 350ml + Condicionador 175ml + Creme Para Pentear 240g é ideal para cabelos danificados e sem vida, oferecendo um tratamento completo que repara, fortalece e devolve o brilho natural aos fios. Enriquecido com o exclusivo blend de Pro-Vitaminas Pantene, essa linha combate os sinais de dano desde o primeiro uso, restaurando a estrutura capilar e prevenindo a quebra. Benefícios:Restauração profunda da fibra capilar.Reduz a quebra e repara os danos visíveis.Deixa os fios mais fortes, macios e brilhosos.Creme para pentear com ação antifrizz e proteção térmica.Fórmula leve, ideal para uso diário.Cabelos mais saudáveis e resistentes desde o primeiro uso. Modo de usar:Shampoo: Aplique nos cabelos molhados e massageie suavemente o couro cabeludo. Enxágue.Condicionador: Aplique no comprimento e pontas, deixe agir por alguns minutos e enxágue.Máscara Capilar: Aplique a máscara nos fios úmidos, deixe agir por 3 a 5 minutos e enxágue. Sobre a marca: Presente no mercado global há mais de 40 anos, Elseve, marca da L''Oréal Paris, é sinônimo de inovação em tratamento capilar. Seus produtos são desenvolvidos com tecnologia de ponta e ingredientes poderosos para oferecer soluções eficazes para todos os tipos de cabelo. Com linhas icônicas e resultados comprovados, Elseve combina ciência e beleza para revelar o melhor dos seus fios em cada aplicação.', 64.77, 53.74, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260u-mlqcmcpghudd68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23494063709', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21698028433', 'KIT MOTUL 8100 X-CLEAN FE 5W-30 7 LITROS', 'Loja Oficial MOTUL A Motul é uma empresa francesa com mais de 165 anos de experiência na produção e distribuição de lubrificantes e fluidos de qualidade para motores. Ela é pioneira em inovação, tendo desenvolvido o primeiro lubrificante automotivo 100% sintético do mundo. Presente em mais de 160 países, a Motul chegou ao Brasil em 1992 e é conhecida por sua participação em competições automobilísticas de renome mundial. As pistas de corrida são o laboratório principal da empresa, onde seus produtos são testados em condições extremas antes de serem lançados no mercado. MOTUL 8100 X-CLEAN FE 5W-30 Características: Código OEM: 112771 Código universal de produto: 3374650408187 Condição do item: Novo Formato de venda: Unidade Grau de viscosidade: 5W-30 Linha: 8100 Marca: Motul Modelo detalhado: Óleo para motor de carro MOTUL 8100 X-CLEAN FE 5W-30 1L MPN: 112771 Origem: UNIÃO EUROPEIA Tempo de garantia: 3 meses Tipo de garantia: Garantia de fábrica Tipo de óleo de motor: Sintético Tipo de recipiente: Garrafa Tipo de veículo: Carro/Caminhonete USO Lubrificante 100% sintético que oferece ao mesmo tempo alta proteção e economia de combustível. Aprovado pela Mercedes Benz, PSA (Peugeot Citroën) e VAG (Volkswagen, Audi, Skoda e Seat). Especialmente projetado para as mais recentes gerações de veículos com motores a gasolina e diesel, aspirados ou com turbo, injeção direta ou indireta. Para veículos emissionados EURO 4, EURO 5 ou EURO 6 que requeiram óleo ACEA C3, quer dizer, com alta viscosidade HTHS (> 3.5 mPa.s) e do tipo "Mid SAPS" com reduzido teor de cinza sulfatada (≤ 0.8%), fósforo (0.07 ≤ x ≤ 0.09%) e enxofre (≤ 0.3%), ou um óleo motor ACEA C2, quer dizer, de baixo atrito, baixa viscosidade HTHS (≥ 2.9 mPa.s) e do tipo "Mid SAPS" com reduzido teor de cinza sulfatada (≤ 0.8%), fósforo (≤ 0.09%) e enxofre (≤ 0.3%). Se for requerida a característica "Fuel Economy": norma ACEA C2. Este lubrificante é aprovado pela PSA B71 2290 da PEUGEOT CITROËN AUTOMOBILE. Compatível com catalisadores (CAT) e filtro de particulados diesel (DPF). Pode não ser adequado para uso em determinados motores. Consulte o manual em caso de dúvida. Representante OFICIAL MOTUL: BROOKLIN RACE uma das principais lojas de São Paulo referência no segmento automotivo em vendas de lubrificantes, pneus e acessórios para o segmento, com forte presença no mercado. Nosso compromisso é proporcionar uma experiência de compra excepcional, oferecendo produtos de alta qualidade a preços competitivos. Valorizamos o suporte ao cliente, estando disponíveis para auxiliar tanto na pré-venda quanto no pós-venda, garantindo que todas as dúvidas sejam esclarecidas e quaisquer problemas sejam prontamente resolvidos. Estamos empenhados em superar suas expectativas e tornar sua jornada conosco memorável. COMPRANDO ATÉ ÀS 16:00+ DESPACHAMOS NO MESMO DIA.', 969.39, 872.46, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rcdl-m66ve3mr8rr4e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F21698028433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
