INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57400944380', 'Meu Plano Perfeito | Planner Permanente | Capa Creme', 'Já pensou em ter todas as esferas da sua vida organizadas ao alcance da mão? Com Meu plano perfeito, você pode. Neste planner anual, você vai encontrar dicas e sugestões práticas para o seu dia a dia; com intenção de inspirá-la e encorajá-la, na expectativa de que você analise as suas necessidades e crie você mesma o seu planejamento. Além dos calendários mensais e semanais, são cinco abas para ajudá-la a refletir e planejar melhor sua rotina, seja em casa, nos relacionamentos, na fé, na vida pessoal ou no trabalho. Em cada uma delas, você terá espaços para personalizar suas metas e tarefas, e também encontrará textos extras para motivá-la e guiá-la nessas áreas. o planner não tem datas definidas, você pode começar a usá-lo a qualquer hora! Prepare-se para montar o seu plano perfeito, com organização e estilo! 16x23cm 254 Páginas', 56.9, 55.9, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-821dw-mgra8vwew0ena8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F57400944380', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
