INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598036703', 'Kit 5 Chiclete Trident Hortelã 8g com 5 Unidades', 'Trident Sem Açúcar Hortelã - 8g Garanta um hálito sempre fresco e revigorante com Trident Sem Açúcar sabor Hortelã! Com sua nova fórmula, esse chiclete traz ainda mais frescor e sabor intenso de hortelã, sem a adição de açúcar e com um toque duradouro que você vai adorar. A embalagem prática com 5 unidades e 8g é perfeita para levar no bolso ou na bolsa, garantindo que você tenha uma sensação de refrescância por onde passar. Experimente o poder refrescante de Trident Hortelã e mantenha-se sempre com o hálito fresco sem comprometer a sua saúde bucal!', 17.45, 17.45, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-825ak-mqmb3vkkxn9o5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F20598036703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
