INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197503300', 'Jogo 4 Pneus Itaro Aro 17 IT006 265/65R17 112S', 'Marca: ITARO Modelo: IT006 Medida: 265/65R17 Largura: 265 Perfil: 65 Tamanho de Aro: 17 Índice de peso: 112 - 1120 kg, 112 Índice de velocidade: S - 180 km/h, S Tipo de Veiculo: CARRO Tipo de terreno: AT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Simétrico UTGQ: 500AB Adesão à àgua: C Eficiência energética: E Ruído externo: 74 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Itaro A Itaro nasceu para motoristas viverem novas histórias - em duas ou quatro rodas. Desenvolvida nas grandes fábricas asiáticas, a marca é homologada nos principais mercados da Europa e América, como o Brasil. Seus pneus foram pensados em centros de pesquisa e desenvolvimento de países como China, Paquistão e Tailândia, que estão entre os maiores do mundo. Com presença exclusiva na PneuStore, a Itaro oferece soluções para carros de passeio, SUVs, caminhonetes, motos e caminhões, com excelente qualidade e custo que ajudam motoristas a viverem novos capítulos todos os dias.', 3092.26, 2875.81, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdy4-lxlpvytprv4826', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23197503300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
