INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897980804', 'Caixa Direção Esfera Riffel Ybr Factor 125 Factor 125i Factor 150 Fazer 150', 'Descrição Qualidade e Durabilidade Desenvolvida especialmente aos motociclistas que priorizam o uso urbano, as caixas de direção esféricas geralmente são utilizadas nas linhas de montagem da maioria das motocicletas de baixa e média cilindrada. SUPERIOR = Diâmetro externo 48 / Diâmetro interno 30 / Altura 12 – INFERIOR = Diâmetro externo 48 / Diâmetro interno 25 / Altura 12 (mm) Yamaha YBR 125 K - E - ED / FACTOR 125 K - E - ED / FACTOR 125 EDITION / FACTOR 125 PRO K - E 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024 Yamaha YBR 150 FACTOR E - ED / UBS / E 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024 Yamaha YF 150 FAZER UBS-ED-SED 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024', 38.79, 38.79, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2qpcgw7775x0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1284014014%2F20897980804', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
