INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694225542', 'Carga Gillette Fusion Proshield com 2 unidades', 'Deseja o barbear mais avançado da Gillette? Gillette Fusion Proshield oferece lubrificação antes e depois das lâminas para o proteger enquanto se barbeia. Além disso, a tecnologia Flexball se adapta aos contornos dos rostos para um barbear mais completo. * Lubrificação antes e depois das lâminas. * Flexball adapta-se aos contornos do rosto para um barbear mais completo. * Lâmina de precisão na parte posterior para obter linhas bem definidas. * Todas as recargas Fusion podem ser utilizadas com qualquer máquina de barbear Fusion. * Sensação refrescante durante o barbear. *Imagens Meramente Ilustrativas.', 79.0, 72.03, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-7rdvi-mc83pbksotqp8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1558108641%2F22694225542', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
