INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12101983521', 'Papel De Parede Adesivo Lavável Quarto Mangá Naruto Anime e One Piece', '🎌 Papel de Parede Anime, • Decore seu ambiente com estilo e personalidade utilizando o papel de parede com tema Anime. Ideal para quartos, salas, estúdios e espaços gamers. 📏 Cálculo de Compra: • Para calcular a quantidade necessária para cobrir uma área específica, basta multiplicar a altura pela largura da parede (em metros). Exemplo: Se a área a ser decorada possui 1 m x 1 m, você precisará de 4 unidades no tamanho 50 x 50 cm para cobrir totalmente o espaço. 🧩 Características do Produto: ✔ Fácil aplicação: não é necessário usar cola. O papel é autoadesivo, garantindo uma aplicação rápida e limpa. ✔ Sobreposição: cada folha possui 3 milímetros de sobreposição, garantindo que as emendas se encaixem perfeitamente. ✔ Fácil manutenção: basta realizar limpeza leve com água, sabão neutro e pano macio para manter o produto sempre com boa aparência. ℹ️ Observações Importantes: 📐 Emendas precisas: todos os modelos são produzidos com gabaritos e conferidos, garantindo que as emendas encaixem 100% lado a lado, desde que seja respeitada a sobreposição de 3 mm. 🎨 Variação de tonalidade: a cor do produto pode variar levemente de acordo com a calibração de cores de cada monitor ou dispositivo móvel. 📦 Planeje sua compra: recomendamos adquirir a quantidade suficiente ou com uma pequena sobra para cobrir a parede desejada. Caso falte material e seja necessário comprar unidades avulsas posteriormente, pode ocorrer diferença de tonalidade, pois cada pedido é produzido em lote único. 💬 Em caso de dúvidas, entre em contato conosco pelo campo de perguntas. Estamos à disposição para ajudar!', 16.0, 16.0, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/br-11134201-7qukw-lhq8yvdowimm2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303439692%2F12101983521', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53151738823', 'Kit Basquete Infantil Completo Cesta De Basquete Com Bola Bomba De Ar Tabela De Basquete', 'Kit Completo de Basquete Infantil – Pais & Filhos Diversão e esporte garantidos para a garotada! O Kit Completo de Basquete Infantil Pais & Filhos é perfeito para incentivar a prática esportiva e desenvolver a coordenação motora das crianças. O conjunto vem com tudo o que elas precisam para começar a jogar: bola, bomba para encher, tabela com aro e rede, proporcionando uma experiência completa de jogo e muita diversão em família! Fabricado com materiais resistentes e de fácil montagem, este brinquedo é ideal para uso em ambientes internos ou externos, como quintal, garagem ou área de lazer. Com ele, os pequenos aprendem sobre trabalho em equipe, foco e equilíbrio enquanto se divertem. Características do produto: Marca: Pais & Filhos Kit completo com bola, bomba, tabela e rede Fácil de montar e transportar Ideal para crianças que amam esportes e movimento Estimula a coordenação motora, concentração e trabalho em equipe Pode ser usado em casa, na escola ou ao ar livre Por que escolher o Kit Basquete Pais & Filhos? Porque une diversão, aprendizado e atividade física em um só brinquedo! Um presente perfeito para meninos e meninas que adoram desafios e muita energia!', 129.9, 129.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-821fa-mh9aapdxw3rdfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404144117%2F53151738823', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210633027', 'Smart TV 43" Philco QLED HDR10 Roku TV P43KRB', 'A Smart TV 43" Philco QLED HDR10 Roku TV P43KRB preenche sua sala com cores intensas e brilho marcante graças à tecnologia QLED, criando imagens vibrantes que envolvem toda a família. Cada detalhe ganha mais vida com o HDR10 aliado à inteligência artificial, que aprimora contrastes e profundidade para tornar filmes, séries e jogos ainda mais realistas e emocionantes. A experiência sonora acompanha esse nível de qualidade com 20W RMS, distribuídos em dois alto-falantes de 10Wrms, somados ao Dolby Áudio, que ajusta o som de forma inteligente conforme o conteúdo exibido. Navegar entre aplicativos se torna simples e agradável com o Sistema Operacional Roku, que oferece acesso rápido à Roku Store e organiza seus streamings favoritos de maneira intuitiva. A conectividade completa, com Wi-Fi Dual Band, 3 entradas HDMI, 2 portas USB e controle pelo Roku App, garante praticidade e liberdade no uso diário. Tudo isso com frame na cor Space Gray, que complementa o visual do ambiente com elegância. Valorize seus momentos em casa e transforme sua rotina de entretenimento com a Smart TV 43" Philco QLED HDR10 Roku TV P43KRB.', 2209.9, 1499.9, NULL, 'Home Appliances > TVs & Accessories > TVs', 'https://cf.shopee.com.br/file/sg-11134201-825ai-mqz4tiptd7gkec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F58210633027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
