INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099360582', 'Boneco Bebê Mamãe Reborn Enxoval Completo Bolsa + Pelúcia - 43cm!', 'Conheça nosso encantador boneco reborn, feito com detalhes realistas e carinho. Ele vem com um enxoval completo, incluindo roupinhas adoráveis e uma naninha macia para acompanhar todas as aventuras. Perfeito para momentos de ternura e cuidado, esse boneco é ideal para estimular a imaginação e o afeto. Itens que compõem o anúncio: - 1 boneco reborn com corpo de vinil - 1 chupeta magnética decorada - 1 jardineira de shorts - 1 blusinha - 1 bolsa bordada príncipe - 3 fraldas - 1 naninha - 1 mamadeira de leite falso (PODENDO SER AZUL OU BRANCA DE ACORDO COM NOSSO ESTOQUE) - 1 prendedor de chupeta - 1 pente decorado - 1 escova decorada - 1 RG - 1 certidão de nascimento - 1 manual de cuidados Totalizando 16 itens que compõe seu lindo enxoval!', 297.9, 236.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdvk-lz7lzzheoeqyb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389279924%2F19099360582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22230470344', 'Cacheador Philco Duo Shine Rosa', 'Seu Cacheador Philco Duo Shine Rosa é compacto, leve e ergonômico. Além disso, proporciona efeito e qualidade de salão em casa! Possui 2 opções de tamanhos – pequeno e grande -, deixando seus cachos mais naturais e saudáveis. O tubo em cerâmica distribui melhor o calor, garantindo um penteado perfeito e protegendo os fios. Já sua presilha não amassa o cabelo na hora de enrolar. É bivolt, ideal para levar a qualquer lugar inclusive em viagens. Conta com cordão elétrico giratório 360° permite liberdade de movimento durante o uso. Em poucos minutos seus cachos estão perfeitos e saudáveis, por isso o Cacheador Philco Duo Shine Rosa é a melhor opção para te ajudar a ficar cada vez mais linda! • Tubo modelador em cerâmica • Modelador em espiral integrado que facilita a modelagem e protege os dedos de queimaduras • Cordão rotativo • Compacta, leve e ergonômica • Bivolt • Cordão de 2mt • Botão liga/desliga • Luz indicadora de funcionamento • Cacheia todo o cabelo em poucos minutos.', 129.9, 109.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-820nb-mnofmr60fg8xa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F22230470344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
