INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20067410433', 'Escova Para Lavar Copos com Cabo de Bambu - Oikos', 'Essa é a escova para lavar copos com cabo de bambu da OIKOS. Prática: ótima para lavar copos, jarras ou garrafas e desgrudar o que ficou difícil de limpar. Com cerdas flexíveis: não danifica os objetos. Furo passante: na hora de guardar, é só pendurar. Design ergonômico: a alça é confortável de segurar, protege suas mãos e dá suporte para esfregar. Feita de bambu: material leve, resistente e ecologicamente correto. Durável e higiênico: o bambu é resistente e tem propriedades que evitam a proliferação de bactérias. só precisa lavar e secar de acordo com as recomendações, combinado? Dimensões do produto: Altura:28cm Largura:9cm', 37.9, 32.9, NULL, 'Home Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261h-mlfangb34npk5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F20067410433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
