INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23033141488', 'Fita Adesiva Para Mega Hair 3 Metros X 1.2cm Protese Capilar', 'Fita Adesiva Capilar Lace Front Indicada para Apliques Sistemas Capilares Prótese Capilar Mega Hair Peruca. Própria para próteses, perucas e apliques, a fita rolo adesivo capilar Lace Front apresenta alta qualidade de colagem, excelente aderência, resistência a água e pouco brilho, o que permite uma fixação prolongada de até 3 a 4 semanas; Contando com um acabamento fosco ou transparente, inodoro e resistente a bactérias, o rolo fita adesivo capilar Lace Front também pode ser facilmente removível. Apenas o forro é azul, a fita real é transparente. Fita adesiva Lace Front - Para apliques - 3 Jardas ou 2,7 metros X 1,27cm - Comprimento: 3 Jardas ou 2,7 metros - Largura da fita: 12,7mm ou 1,27cm Fabricação americana - Alta qualidade na colagem de apliques. Pode ser usado em: Próteses Capilar base MICRO-PELE (Silicone); Prótese Capilar base de tela (Full lace, Silk top, Seda, Mono fine); Mega Hair de fita adesiva, perucas. Resistente a água, alto poder de fixação. Cor Transparente. OBS: todas as imagens são ilustrativas, podendo ser novas embalagens, de acordo com as modificações do fabricante. Não aceitamos devolução após violar a embalagem.', 33.98, 28.89, NULL, 'Fashion Accessories > Hair Accessories > Others', 'https://cf.shopee.com.br/file/br-11134207-81ztp-mkjo7ljs1n9fce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F375741503%2F23033141488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
