INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255208133', 'Elseve L''Oréal Paris Reparação Total 5 - Máscara 300g', 'Máscara capilar de tratamento para cabelos danificados. Elseve L''Oréal ParisReparação Total 5 reconstrói os fios de dentro para fora garantindo brilho intenso. A Máscara Capilar de Tratamento Elseve L''Oréal Paris Reparação Total 5 é um produto de cicatrização do couro. O produto é enriquecido com Cicatri-Ceramida, em uma formulação totalmente nova e potente, que identifica e trata os 5 sinais de danos do dia a dia - quebra, rigidez, opacidade, ressecamento e pontas duplas - para um resultado de plástica capilar. Possui tripla ação: Repõe dia após dia os nutrientes perdidos pela fibra, repara a estrutura da fibra deixando os fios uniformes, selados e protegidos cicatrizando a extensão capilar, especialmente os fios danificados. Os resultados? Desde a 1ª aplicação transforma as fibras, que ficam macias e brilhantes, e, progressivamente, confere efeito de plástica capilar. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 39.9, 39.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825zu-mko6lla3moebf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58255208133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
