INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19178291802', 'Ana Hickmann Duo Eyeshadow Duo 1 (Marrom Claro e Escuro)', 'Sinta-se poderosa e confiante com a linha de maquiagens de Ana Hickmann. Produtos para rosto, olhos, boca e acessórios como esponjas, curvex, pincéis profissionais e kits. Produtos de alta performance. Seja a protagonista do seu próprio beauty show! Duo de sombras compactadas opacas e cintilantes. Cores pigmentadas e textura macia. Disponível em 4 duos. Modo de uso: Aplique na pálpebra com a ajuda de um pincel. Ingredientes: Ingredientes: Mica, Silica, Synthetic Fluorphlogopite, Polyethylene, Kaolin, Tridecyl Trimellitate, Caprylic/Capric Triglyceride, Magnesium Stearate, Simmondsia Chinensis Seed Wax (Jojoba), Tocopherol, Phenoxyethanol, Octyldodecanol, Ethylhexylglycerin, 1,2-Hexanediol. May Contain (+/-): CI 77491 (Iron Oxide Red), CI 15850 (Pigment Red 57), CI 77499 (Iron Oxide Black), CI 17200 (Acid Red 33). * Produto Vegano *', 23.9, 23.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/br-11134207-820lq-mosq498g7e9s22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984347359%2F19178291802', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40918399387', 'Esmalte Top Coat Coleção Pov Cor To Pronta Glitter Impala', 'O Top Coat Impala POV: To Pronta Glitter é ideal para quem deseja unhas cheias de brilho, estilo e personalidade. Perfeito para quem gosta de destacar a manicure com um toque moderno e divertido! Sobre o produto:-Marca: Impala.-Contém 1 Top Coat Impala POV: To Pronta Glitter.-Coleção POV.-Alta cobertura.-Brilho intenso com efeito glitter.-Longa duração.-Secagem rápida.-Não testado em animais.-Dermatologicamente testado.- Proporciona acabamento profissional, valoriza o visual com um toque de brilho moderno e realça seu estilo com personalidade única. Indicado para:-Profissionais de manicure e pedicure.-Cuidados pessoais em casa. Modo de uso:-Agite bem antes de usar.-Aplique o esmalte sobre as unhas após o uso de uma base da sua preferência.-Comece a esmaltação pelo centro e, em seguida, preencha as laterais.-Se desejar, aplique uma segunda camada de esmalte.-Use um palito com algodão umedecido em removedor para limpar o excesso do esmalte.-Finalize com um secante da sua preferência. Precauções de uso:-Não expor ao calor/luz solar, não ingerir.-Manter fora do alcance das crianças.-Usar somente em adultos, não usar sobre a pele irritada ou lesionada.-Em caso de irritação, suspender o uso e procurar orientação médica. Com brilho intenso e efeito glitter único, o Top Coat POV: To Pronta Glitter é a escolha certa para quem quer unhas modernas e cheias de personalidade. Garanta já o seu e destaque sua manicure com um toque fashion! Surgiu alguma dúvida? Entre em contato com a gente!Boas Compras :)', 21.6, 17.49, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-824iy-meh8vq3fefbbcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F40918399387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
