INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397419857', 'Linha Platinum XT Cartelado - Safari Max', 'Caracterizada como uma Linha Monofilamento, essa é categoria preferida dos pescadores sabe por quê? Simples, por causa de seu custo benefício e baixo custo! Esse tipo de linha, pode proporcionar diversas possibilidades de uso ao pescador. Vantagens da utilização da Linha Monofilamento: - Custo baixo; - Pode ser utilizada em grande maioria das modalidades de pesca; - Praticidade para dar nós. Vantagens da Platinum XT: - Extra resistente e forte - Alta resistência - Quase invisível na água - Alta resistência ao choque - Máxima flexibilidade e suavidade As Linhas Monofilamento são compostas por um único fio como seu próprio nome já diz, feito em Nylon. São indicadas para pescadores que procuram uma pesca mais barata, de paciência e sem uma alta resistência a fisgadas. Essa linha é comercializada nos seguintes diâmetros e tamanhos: - Diâmetro: 0.30 mm | Resistência: 12,20 kg equivalentes a 26.80 Libras | 300m; - Diâmetro: 0.35 mm | Resistência: 15,60 kg equivalentes a 34.30 Libras | 270m; - Diâmetro: 0.40 mm | Resistência: 19,60 kg equivalentes a 43.10 Libras | 250m; - Diâmetro: 0.45 mm | Resistência: 25,10 kg equivalentes a 55.20 Libras | 200m; - Diâmetro: 0.50 mm | Resistência: 32,00 kg equivalentes a 70.40 Libras | 150m; - Diâmetro: 0.60 mm | Resistência: 43,50 kg equivalentes a 96.00 Libras | 100m; ATENÇÃO: ESCOLHA O DIÂMETRO DA LINHA DESEJADA ANTES DE FINALIZAR A COMPRA, SEGUINDO OS PADRÕES DE RESISTÊNCIA DESEJADA! Especificações Técnicas: - Marca: Safari Max - Origem: China - Cor: Transparente - Material: Nylon - 1 Fio - Modelo: Linha Monofilamento Platinum XT Cartelado - Safari Max - Compatibilidade: Molinetes e Carretilhas - Validade indeterminada - Peso: 90g - Dimensões embalagem ( A x L x C ): 4cm x 8,5cm x 11,3cm. Itens Inclusos: - 01 Linha Monofilamento Platinum XT Cartelado - Safari Max', 40.74, 40.74, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rbmw-lmdw0f5m1g404c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F20397419857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
