INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794615987', 'Kit Haskell Infusão de Óleos com 5 Itens 300gr– Nutrição Ultraprofunda para Cabelos Ultrarressecados', 'Dê adeus aos fios secos e opacos com o Kit Haskell Infusão de Óleos! Especialmente desenvolvido para cabelos ultrarressecados, esse combo poderoso com 5 produtos essenciais garante nutrição completa, brilho intenso e proteção total. Este kit completo contém: • Shampoo 300ml – Limpa suavemente, iniciando o tratamento e preparando os fios para receber os nutrientes. • Condicionador 300ml – Hidrata profundamente, sela as cutículas e mantém a maciez por mais tempo. • Máscara de Tratamento 300g – Reposição intensa de óleos e nutrientes. Repara os danos profundos e devolve vitalidade. • Leave-in 150g – Finalizador com proteção térmica e solar. Ideal para proteger os fios contra altas temperaturas. • Óleo Nutritivo 100ml – Ação umectante que proporciona brilho imediato e forma uma película protetora contra agressões externas. Com uma combinação rica e eficaz de óleo de marula, óleo de argan e óleo de monoi, a linha Infusão de Óleos Haskell repõe lipídios essenciais e restaura profundamente a estrutura da fibra capilar. Direção olfativa: oriental, floral, frutal Resultados visíveis:  Nutrição máxima da raiz às pontas  Maciez prolongada e brilho intenso  Cabelos protegidos e restaurados Perfeito para quem busca um tratamento profissional em casa, com o toque de qualidade Haskell.', 356.5, 356.5, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8259x-mge3y0yccxe196', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562135680%2F23794615987', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
