INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54850610196', 'Caneca Magnética Com Mistura Automática 380ml', 'A caneca mixer elétrica é a escolha perfeita para quem busca praticidade e inovação no dia a dia! Com um design moderno e funcional, ela mistura suas bebidas favoritas com apenas um toque, sem a necessidade de colheres ou outros utensílios. Ideal para preparar café com leite, achocolatado, shakes, pré-treinos, suplementos e muito mais, de forma rápida e sem sujeira. Com funcionamento a pilhas 2 pilhas AAA, essa caneca é portátil e pode te acompanhar no trabalho, em casa, na academia ou em viagens. Basta apertar o botão e o mixer integrado faz todo o trabalho, deixando sua bebida homogênea em segundos. Além disso, sua tampa com vedação ajuda a evitar derramamentos, garantindo segurança e conforto no uso diário. É também uma excelente opção de presente criativo e útil para amigos, familiares e colegas. Unindo praticidade, estilo e tecnologia, a caneca mixer vai transformar sua rotina. Especificações: •Capacidade: Aproximadamente 380ml •Alimentação: 2 pilhas AAA não inclusas •Material: Aço inoxidável e plástico resistente •Fácil de limpar não submergir na água Medidas aproximadas: Altura: 13,5cm Diâmetro: 9,5cm Altura da alça: 9cm', 122.0, 39.98, NULL, 'Home Appliances > Kitchen Appliances > Coffee Machines & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820l7-mlffathukzr9f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1232299933%2F54850610196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
