INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298525497', 'Valvula Termostatica Original Chevrolet Spin 2013 a 2024', 'Valvula Termostatica Original Chevrolet Spin 2013 a 2024 LOJA DPC DISTRIBUIDORA DE PEÇAS CAPIVARI LTDA Somos uma empresa qualificada operando a mais de 35 anos no ramo de autopeças linha leve. Trabalhamos com grande variedade de peças automotivas, utilize o campo de perguntas para cotação! Valvula Termostatica Original. Codigo: 93275736 Marca: Chevrolet Gm Temperatura de abertura: 92 º C Anuncio referente a 01 Unidade. Produto novo e original, com garantia e nota fiscal. Aplicacao: Agile 2010 a 2014 Celta 2001 a 2016 Cobalt 2012 a 2020 Corsa Hatch 1994 a 2017 Corsa Pickup 1994 a 2017 Corsa Sedan 1994 a 2017 Corsa Wagon 1994 a 2017 Meriva 2003 a 2012 Montana 2004 a 2021 Onix/Joy 2013 a 2021 Prisma 2007 a 2012 Prisma/Joy Plus 2013 a 2021 Spin 2013 a 2024 RECOMENDAÇÕES: - Prazo de Garantia é de 90 dias para defeitos de fabricação do produto. - A garantia expira caso seja feito um mau uso do produto ou pela má instalação, por isso recomendamos sempre que a instalação seja feita por um profissional especializado. - As fotos de nossos produtos são reais, para maior segurança para o consumidor. - Antes de efetuar a compra tire todas suas dúvidas no campo perguntas. - Mantenha seus dados e endereços atualizados - Temos carrinho de compras, adicione varios produtos e economize no Frete. - Consulte condicoes especiais para compra de mais unidades, kits ou combos. - Aceitamos devoluções apenas com a embalagem Original e Nota Fiscal. - Atendimento de segunda a sexta das 8h00 as 18h00', 65.0, 62.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-825ba-mqz97q31s8p8cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1506493263%2F23298525497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493575110', 'Par Palheta Limpador Parabrisa p/ Carro Honda Fit 2009 A 2014 Cinoy Original', 'Par Palheta Limpador Parabrisa Cinoy Específica Honda Fit 2009 a 2014 Palheta Limpador Para-Brisa para Honda Fit 2009 a 2014 Acessório frequentemente procurado para reposição, a palheta do limpador do para brisa está presente na maioria dos carros. Sua função é limpar a água da chuva, respingos de água e outros detritos, para que o motorista possa enxergar bem a via. Por isso, é muito importante que esteja em bom estado, para manter o para brisa livre, sem bloquear a visão. Aplicação: • Honda Fit 2009 a 2014 Especificação Técnica: • Fabricada em Plástico e Borracha • Maior Durabilidade e Resistência • Encaixe Sob Medida • Haste Maleável que se Ajusta ao Vidro • Melhor Aderência e Limpeza • Design Diferenciado • Evita Riscos • Fácil Instalação Através de Encaixe com Trava Conteúdo da Embalagem: • 01 Palheta de 26 Polegadas • 01 Palheta de 14 Polegadas Importante: Garantia de 3 Meses. Valor referente ao Par de Palhetas.', 34.99, 34.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/ad97168f376080d83c3906379672c216', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800059202%2F22493575110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21835122139', 'Pets Alive - Booty Shakin’ Pups - Dachshund', 'Conheça os novos filhotes dançarinos Booty Shakin'' Pups da Pets Alive! São mini pets colecionáveis que balançam o bumbum enquanto andam. Com Booty Shakin’ Pups Pets Alive, a brincadeira ficará muito mais divertida! São 4 raças para colecionar: Corgi, Pug, Buldog e Dachshund. Cada filhote vem com a sua própria coleira removível, e sua embalagem também serve de casinha. Dimensões da Embalagem C:10,5cm /L:11cm/ A:11cm', 109.99, 59.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/9ecbe4237fb100ca3e4ea265dd8b2861', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F21835122139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298088939', 'Kit Lápis Labial Nude + Batom Nude Océane Edition (2 Produtos)', 'Com o Kit Lápis Labial Nude + Batom Nude Océane Edtion Você Tem 2 Produtos para Deixar Seus Lábios com o Tom Nude Perfeito. O Kit Lápis Labial Nude + Batom Nude Océane Edtion Contém: - 1 Lápis de Contorno Labial Nude - Lip Liner Beige Brown Océane Edition 1,2g; - 1 Batom Nude Cremoso – The Lipstick Bellini Océane Edition 3,2g. Lápis de Contorno Labial Nude - Lip Liner Beige Brown: Ele Tem Uma Fórmula Incrível, com Ingredientes de Qualidade, Textura Macia e Uma Pigmentação Surpreendente. Ele Desliza Confortavelmente Nos Lábios, Deixando a Cor Bem Marcada Logo Na Primeira Passada. e Por Falar em Cor, Beige Brown É Um Nude com Fundo Rosado Que Expressa Toda a Sua Elegância Por Meio da Maquiagem. Ele Tem Uma Durabilidade Impressionante e Ainda Ajuda a Manter Seu Batom Intacto Por Mais Tempo. Bom Demais, Né? Transforme Seu Visual em Instantes com Este Lápis de Boca da Océane e Apaixone-Se Pelo Resultado! Ele Faz Maravilhas: Dá Pra Aumentar o Volume Dos Lábios, Afiná-Los ou Ainda, Alongar o Sorriso. Existem Muitas Técnicas de Contorno Labial e Uma Delas É Perfeita para o Seu Estilo. Batom Nude Cremoso – The Lipstick Bellini Océane Edition 3,2g: Na Cor Bellini, Você Encontra Um Nude Rosado Super Delicado. Ideal para Pessoas Que Gostam de Levar a Vida de Uma Forma Smart, Descomplicada e Positiva. Ele É Enriquecido com Vitamina e e Ácido Hialurônico, Ativos Que Deixam o Seu Lip Care Mais Completo. Porque Beleza e Autoestima Precisam Estar Na Vida de Todas As Pessoas. A Gente Tem Também a Embalagem Exclusiva do Produto. Ela É Rosqueável, o Que Evita Que Ela Se Abra Dentro da Bolsa ou Nécessaire. Chega Na Cor Rosa, com Detalhes em Dourado, Dando Um Ar Todo Diferente e Festivo para o Produto, o Que Faz com Que Ele Seja o Presente Perfeito para Quem Nasceu para Brilhar. Presenteie com The Lipstick Edition, Mostrando Seu Bom Gosto e Amor Por Alguém!', 79.9, 79.9, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-8258l-mr0bmqn7c9vmee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F21298088939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
