INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26928678641', 'Kit Livros de colorir - Comfy', 'Kit Livros de colorir - Comfy_x000D_ _x000D_ Inspirado no fenômeno dos livros de colorir para relaxamento do TikTok, é perfeito para quem ama transformar momentos simples em uma verdadeira experiência calmante. Impressas em papel de alta gramatura, para garantir a melhor qualidade de pintura, as 48 páginas com 24 ilustrações exclusivas retratam momentos cotidianos e aconchegantes, permitindo que você explore sua criatividade ao máximo, seja colorindo com lápis de cor ou marcadores. Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia._x000D_ _x000D_ _x000D_ ISBN: 9786526122914 Cozy Space - Livro de Colorir_x000D_ ISBN: 9788557584822 Cute World - Para Colorir_x000D_ ISBN: 9786526122204 Cozy Vibes_x000D_ ISBN: 9786526122198 Comfy Vibes_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.50', 99.6, 49.8, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-m711gnw2unbu3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F26928678641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097608027', 'Dedoches Turma Do Mundo Bita Miniaturas', 'Os Dedoches Mundo Bita são 5 miniaturas dos personagens para colocar nos dedos e contar divertidas histórias, além de serem usados no lápis ou para brincar no banho. Eles possuem aproximadamente 7 cms de altura e são fabricados em vinil atóxico! CARACTERÍSTICAS: Categoria: Primeira Infância Personagem: Mundo Bita Idade Recomendada: + 3 anos Material: Vinil atóxico Dimensões (embalagem): 23 x 4 x 7 cm (CxLxA) Peso: 120 g Produto Certificado: CE-BRI/IQB 00275552668', 42.99, 41.99, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lx0k6zwjmb923b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F23097608027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
