INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599137976', 'Pneu Levorin 100/80-17 M/C 58S Matrix Sport II TL Sem Câmara + Válvula CBX 250 TWISTER', 'Pneu Levorin 100/80-17 M/C 58S Matrix Sport II TL Dianteiro + Válvula Sobre o Pneu: O pneu ideal para quem procura uma pilotagem esportiva com mais segurança, aderência e durabilidade. Possui um design arrojado, esportivo e inovador. Freia mais rápido e mais curto do que os concorrentes, no seco e no molhado. Sobre a Marca: Com mais de 75 anos de história, a Levorin oferece uma ampla gama de pneus e câmaras para motos e bicicletas, proporcionando desempenho e qualidade aos amantes de duas rodas. Criada por Hercules Levorin em 1943, a marca brasileira é especializada no segmento utilitário onde, além de abastecer o mercado de reposição, fornece pneus originais a grandes montadoras de moto e de bike. Informações Adicionais: - Marca: Levorin - Modelo: Reinf Matrix Sport II - Medida: 100/80-17 - Largura: 100mm - Perfil: 80% - Aro: 17 - Índice de Peso: 58 (236 Kg) - Índice Velocidade: S (180 Km/h) - Tipo De Construção: Diagonal - Tipo de Montagem: Sem Câmara - Garantia: 5 Anos Defeitos de Fabrica Aplicação: - HONDA: CBX 250 TWISTER Válvula Para Pneus Sem Câmara 49,1mm FVA Ideal para ser utilizada em Pneus sem Câmara Informações Adicionais: - Marca: FVA - Fabricado em material resistente e flexível', 416.0, 416.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-8257t-mqw7t1bpkzyba2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F23599137976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
