INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213219084', 'Cera Líquida Brilho Proteção Triple Wax 500ml Autoamerica', 'Cera Líquida Triple Wax 500ml - Autoamerica A Cera Líquida Triple Wax da Autoamerica é o produto ideal para quem busca o balanço perfeito entre brilho espetacular, proteção duradoura e extrema facilidade de aplicação. Desenvolvida com uma combinação exclusiva de três componentes essenciais para a estética automotiva, ela limpa suavemente a superfície, remove pequenas imperfeições e cria uma camada protetora com alto poder hidrofóbico (repelência à água). Diferente das ceras em pasta tradicionais que exigem muito esforço físico, a versão líquida da Triple Wax oferece um rendimento altíssimo e um processo de aplicação e remoção incrivelmente rápido, sendo perfeita tanto para o uso profissional em oficinas e estúdios de detalhamento quanto para o hobbista no fim de semana. Por que a Triple Wax Líquida é um sucesso de vendas? Ação 3 em 1 Premium: Limpa impurezas leves da pintura, mascara micro-riscos e protege contra agentes externos ao mesmo tempo Brilho de Showroom: Deixa a pintura com aquele aspecto de "carro molhado", destacando intensamente a cor e o reflexo da lataria Excelente Repelência à Água: Cria uma película protetora que faz a água deslizar facilmente, reduzindo o acúmulo de sujeira e facilitando as próximas lavagens Toque Extremamente Aveludado: Sinta a suavidade na lataria logo após a remoção do excesso de produto Rendimento Superior: A consistência líquida permite uma espalhabilidade uniforme, garantindo dezenas de aplicações com um único frasco de 500ml Especificações Técnicas: Marca: Autoamerica Volume: 500ml Textura: Líquida Indicação: Todos os tipos de pintura automotiva (vernizes nacionais e importados) Modo de Uso Simples: Certifique-se de que o veículo esteja limpo, completamente seco e à sombra Agite bem o produto antes de usar Aplique uma pequena quantidade da cera em um aplicador de espuma ou microfibra Espalhe na superfície em movimentos circulares ou orientados, trabalhando em áreas pequenas por vez (ex: um para-lama, meia porta) Deixe secar por alguns minutos até formar uma leve névoa fosca Remova o excesso e dê o acabamento final utilizando uma toalha de microfibra limpa e macia, revelando o brilho máximo Conteúdo da Embalagem: 01 Cera Líquida Triple Wax Autoamerica 500ml. Produto novo, original, bem embalado e protegido. Acompanha nota fiscal. Ceriolli Shop Oficial Atendimento 100% personalizado', 43.9, 43.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-824hr-mpwnhkvu2j9r0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F58213219084', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
