INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292412445', 'Kit 20 Pote Descartável 150ml Freezer Microondas Marmita', '🥣 Kit 20 Potes Descartáveis 150ml com Tampa – Compactos, Resistentes e Muito Versáteis! Leve mais praticidade para o seu dia a dia! O Kit com 20 Potes de 150ml com Tampa é ideal para armazenar doces, porções, sobremesas, molhos, pastas, bolos e muito mais — com total segurança e organização. ✅ Benefícios que fazem a diferença: 🍰 Versátil: Perfeito para uso doméstico, delivery, marmitas, doces, confeitaria e porções individuais. ❄️🔥 Vai ao freezer e micro-ondas: Suporta baixas e altas temperaturas com segurança (PP atóxico). 💧 Tampa com vedação segura: Evita vazamentos e preserva a qualidade dos alimentos. 🧊 Empilhável e compacto: Design retangular que economiza espaço na geladeira, freezer ou despensa. 🛡️ Durável e reutilizável: Feito em polipropileno (PP), resistente e seguro para alimentos. 📐 Especificações Técnicas: Capacidade: 150ml Material: Polipropileno (PP) – Grau alimentício Dimensões aprox: 11 cm (C) x 8 cm (L) x 3,6 cm (A) Formato: Retangular Uso recomendado: Freezer e micro-ondas Quantidade total: 20 unidades com tampa 📦 Conteúdo da Embalagem: 1 pacote com 20 potes de 150ml com tampa 💡 Dica: Ideal para confeitarias, marmitas fit, porções para festas, amostras, e muito mais! Garanta agora seu Kit de 20 Potes 150ml e traga praticidade e organização para sua cozinha ou negócio!', 20.83, 20.83, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rbnd-lltl1m11csudd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F23292412445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206692727', 'Kers Iluminacao Colmeia Color Balance 11 Celulas Bivolt Modelo Policarbonato 6500k/4000k/3000k - 320', 'Bem-vindo à AT4U - Loja Oficial KERS ILUMINAÇÃO COLMEIA COLOR BALANCE 11 CÉLULAS 368W BIVOLT – ESTRUTURA EM POLICARBONATO A Iluminação Colmeia Kers Color Balance foi desenvolvida para oferecer máxima performance, durabilidade e versatilidade. Com estrutura 100% em policarbonato, ela é mais leve, resistente e fácil de instalar, mantendo o mesmo padrão profissional de iluminação que destaca cada detalhe com fidelidade de cores. Com o exclusivo sistema Color Balance, é possível ajustar a tonalidade da luz entre branco quente (3000K), neutro (4000K) e frio (6500K), adaptando-se a diferentes tipos de trabalho e ambientes. Ideal para oficinas, estúdios, showrooms e áreas de inspeção, proporciona uma iluminação uniforme, sem sombras e com alta reprodução de cores (CRI 90). - Estrutura em Policarbonato: leve, resistente e de fácil instalação - Sistema Color Balance: ajuste de tom de luz entre 3000K / 4000K / 6500K - Iluminação uniforme e sem sombras com formato colmeia de 11 células - Alta fidelidade de cores (CRI 90) – ideal para inspeção de pintura - Painel amplo (3,2 m × 2,3 m), cobrindo áreas maiores com menos unidades. - Alta eficiência luminosa (120 lm/W) com baixo consumo - Instalação simples, sem gabarito ou necessidade de técnico especializado - Design moderno e profissional, valorizando o ambiente ESPECIFICAÇÕES TÉCNICAS Marca: Kers Modelo: Colmeia LED 11 Células Color Balance – Policarbonato Material: Policarbonato (estrutura e base) Dimensões: 3205 × 2347 mm Potência: 368 W Fluxo luminoso: 33.120 lm Temperatura de cor: 3000K / 4000K / 6500K Índice de reprodução de cor (CRI): 90 Eficiência luminosa: 120 lm/W Voltagem: Bivolt automático Instalação: Direta, sem necessidade de suporte adicional Consumo: Baixo, com alto desempenho IDEAL PARA: Oficinas de polimento e detalhamento automotivo Showrooms e áreas de inspeção de pintura Estúdios e lojas que exigem iluminação técnica e estética Ambientes profissionais que buscam conforto visual e design CONTEÚDO DA EMBALAGEM 01 Sistema de Iluminação Colmeia LED 11 Células Kers Color Balance (Bivolt) Policarbonato IMPORTANTE: Postagem em até 24h Entrega Garantida Produtos Originais e Certificados COMPRE COM SEGURANÇA Tire suas dúvidas via chat com nossos especialistas', 1614.0, 1614.0, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-8262l-mlo8jdld5e68e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349249646%2F58206692727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
