INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399564329', 'Refresco em Pó Promix Abacaxi 250g - Embalagem 10 Unidades', 'Características do produto: Departamento: Suco Marca:Promix Sessão: Refresco em Pó Número Anvisa: Não se aplica Número Mapa:SP000480-4.000265 Sabor: Abacaxi Informações Adicionais do produto: Excelente rendimento apresentado em 10 sabores para compartilhar com os amigos e família, porque sempre tem um bom motivo para comemorar. Promix traz praticidade, rendimento, refrescância e sabor para matar a sede de todos. Excelente custo-benefício. Melhor balanço sensorial com polpa de fruta e adoçado na medida certa. Melhor rendimento e fácil dissolução. Baixo teor de sódio Fonte de vitamina C Apenas 19Kcal por copo Ingredientes Açúcar, vitamina C (ácido ascórbico), polpa de abacaxi desidratada, acidulante ácido cítrico, edulcorantes: ciclamato de sódio (24mg/100ml), aspartame (8,5mg/100ml), acessulfame de potássio (6mg/100ml) e sacarina sódica (1,6mg/100ml), aromatizante, regulador de acidez citrato de sódio, antiumectantes: fosfato tricálcico e dióxido de silício, corante inorgânico dióxido de titânio, espessantes: goma xantana e carboximetilcelulose sódica, corantes artificiais: tartrazina e amarelo crepúsculo FCF. Modo de Preparo Misture o conteúdo desta embalagem em 10 litros de água fria ou gelada. Bebida para consumo imediato. Para melhor resultado em porções fracionadas, recomenda-se misturar o pó no pacote antes de cada uso. Marca: Promix', 87.19, 87.19, NULL, 'Food & Beverages > Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gz-mpibgngcqcy726', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F21399564329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208571285', 'Pote Porta Café 1,6 L Despensa Cozinha Plasútil', 'Pote Porta Café 1,6 L Despensa Cozinha Plasútil Dimensao: (Diâmetro x Alt): 11,6x22,1 cm Capacidade: 1,6 l - Comporta 500 gramas de pó de café (com pouca sobra de espaço). - Ter produtos decorativos e funcionais ao mesmo é uma excelente opção para você que gosta de beleza e praticidade juntos. - Nosso pote porta café possui tampa rosqueável em tom bege - que é uma super tendência já que faz parte da paleta do marrom. - Com decoração minimalista e direcionada, deixa sua cozinha ou despensa esteticamente harmônica, já que cria uma unidade visual de associação pois o mantimento em questão é escuro como o pote. - Fabricado em polipropileno (PP) e PET*. Ambos atóxicos e livres de bisfenol-A (BPA FREE). - Capacidade: 1,6 L. - A tampa Plug é encaixável e possibilita que outro pote da mesma linha seja colocado em cima, otimizando espaço e aproveitando áreas úteis. *PET: não pode ser levado ao micro-ondas e lava-louças. Não podem ser armazenados líquidos mornos ou quentes. Não esterilizar com água quente. Não deixar exposto ao sol..', 21.9, 17.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-81zvn-mmvz1qwn7aiwcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F58208571285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
