INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292503648', 'Cera Depilatória Natu Depill Negra 600g', 'Cera natural removível com água e é 100% Natural. Ela é indicada para minimizar a dor, pois o calor facilita a abertura dos poros e a remoção dos pêlos. Modo de uso: Aqueça a cera em banho-maria. Verifique se a temperatura está adequada para uso, colocando uma pequena quantidade na palma da mão. Espalhe a cera numa camada espessa e uniforme, na região a ser depilada, no sentido do crescimento dos pelos. Puxe na direção contrária ao crescimento dos pelos. Caso a cera quebre, aplique outra camada em cima e puxe. #html-body [data-pb-style="646BA64CC23F5"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64CC2409"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 41.54, 41.54, NULL, 'Beauty > Bath & Body Care > Hair Removal Cream & Wax', 'https://cf.shopee.com.br/file/sg-11134201-7rbnf-lmgedm58fnps2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22292503648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
