INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993189819', 'Motocultivador À Gasolina 51,6CC TT75R-Xp Toyama Preto', 'O Motocultivador Toyama TT75R-XP foi projetado para uso profissional, destacando-se pela sua funcionalidade impressionante e imbatível combinação de facilidade de utilização e segurança. Equipado com motor a gasolina de 7,0 HP de potência máxima, é leve e fácil de manusear. O Toyamito TT75R-XP permite ao operador trabalhar confortavelmente mesmo em espaços apertados. Este modelo possui guidão reversível, o que facilita a sua operação reversa. Seu filtro de ar banhado a óleo permite que este equipamento seja utilizado em ambientes com severos níveis de poeiras. Sua caixa de transmissão é manual de duas velocidades para frente e uma para trás. Peso (kg): 70 Garantia: 06 Meses Altura (cm): 40 Ergonômico: Sim Largura (cm): 38 Cilindradas (cc): 51.6 Comprimento (cm): 82 Tempo do Motor: 2 Tipo de Enxada: Enxada Larga Potência Máxima: 1.9 Acompanha Lâmina: Sim Medida da Enxada: 750 Origem do Produto: Importado Acompanha Carretel: Sim Necessita Montagem: Sim Tipo de Combustível: Gasolina Localização do Motor: Atrás Possui Punho Auxiliar: Sim Possui Gancho de Emergência: Sim Tipo de Ferramenta de Jardim: Roçadeira Material Principal Ferramentas: Alumínio Capacidade do Tanque de Combustível (l): 1.1 Marca: Toyama Modelo: TT75R-XP Composição: Ferro Itens Inclusos: Kit Ferramentas e Manual de Instruções Cor Predominante: Preto Linha ou Coleção: Linha XP Alça de Sustentação: Duplo Materiais indicados: Solo Litros de 2T/ Litro Gasolina: 40ml de óleo 2T para 1 litro de gasolina comum', 4107.03, 4107.03, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-820lr-mo3ix84gor9d9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F239931898