INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899242239', 'Ativador Cachos Apse Modelador Anti-Frizz 500gr', '#html-body [data-pb-style=KYMHEH3]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O próprio nome já diz tudo: Ativador e Modelador de Cachos - Ação Condicionante. Cachos definidos climatizados, controlados sem frizz e ação condicionante. Hidrata e desenvolve o movimento natural dos cabelos. Uso diário – Sem enxágue – Não deixa resíduo! Para cabelos ondulados, cacheados, crespos e em transição! PH 3,0 a 4,0 proximadamente. Liberado para No Poo e Low Poo Modo de Uso: Hora da finalização! Após a higienização com a linha cachos, ainda com os fios bem úmidos, reparta o cabelo em mechas e aplique o ativador e modelador cachos enluvando e aplicando a técnica de fitagem de sua preferência. Quanto mais repartições do cabelo, mais definição e menos volume. Para potencializar a sua finalização utilize também a gelatina ativadora e modelador da linha cachos! Preucauções: Manter fora do alcance de crianças. Não ingerir. Em caso de contato com os olhos, enxágue abundantemente com água corrente. Suspenda o uso em caso de irritação e procure orientação médica. Manter em local fresco e ao abrigo da luz do sol. USO EXTERNO.', 67.6, 67.6, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rd6k-luhwf6ai5u3jd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18899242239', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598550543', 'Cilindro Mestre Freio Saveiro Bola 1995 A 2000 S/abs 4 Saida', 'CARACTERISTICAS: • PRODUTO NOVO DE ÓTIMA QUALIDADE. ESPECIFICAÇÕES TÉCNICAS: • SISTEMA COM SERVO FREIO • DUPLO 22,22MM; • SEM RESERVATORIO; • FABRICADO EM FERRO FUNDIDO. COMPATÍVEL COM OS MODELOS: • Gol 1980 a 1983 • Gol 1984 a 1986 • Gol 1988 a 1990 • Gol 1991 a 1994 • Gol Bola 1995 a 2000 • Gol G3 2000 a 2005 • Gol G4 2006 a 2014 • Saveiro 1982 a 1984 • Saveiro 1982 a 1984 • Saveiro 1985 a 1987 • Saveiro 1988 a 1990 • Saveiro 1991 a 1994 • Saveiro Bola 1995 a 2000 • Saveiro G3 2001 a 2005 • Saveiro G4 2006 a 2012 • Parati 1982 a 1983 • Parati 1984 a 1986 • Parati 1987 a 1990 • Parati 1991 a 1996 • Parati Bola 1995 a 2000 • Parati G3 2000 a 2005 • Parati G4 2006 a 2012 • Voyage 1981 a 1983 • Voyage 1984 a 1986 • Voyage 1987 a 1990 • Voyage 1991 a 1996 IMPORTANTE: • VALOR UNITÁRIO; • NÃO NOS RESPONSABILIZAMOS POR INSTALAÇÃO MAL REALIZADA; • A INSTALAÇÃO DEVE SER FEITA POR UM PROFISSIONAL ESPECIALIZADO. ATENÇÃO: AS COMPRAS REALIZADAS EM NOME DE PESSOA JURÍDICA ESTÃO SUJEITAS À COBRANÇA DE ICMS, CONFORME PROTOCOLO ICMS 41, DE 4 DE ABRIL DE 2008. CASO VOCÊ TENHA DÚVIDAS SOBRE O PERCENTUAL A SER APLICADO, CONSULTE A CLÁUSULA SEGUNDA, §1° DO REFERIDO PROTOCOLO.', 174.88, 174.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rat4-mac6vquc88kn2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F538200526%2F23598550543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697752654', 'Esmalte Colorama Cremoso Divertidamente 2 Verde de Inveja 8ml', '#html-body [data-pb-style=QJUYMR3]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}A coleção nova Divertidamente 2 da Colorama traz em seu conceito os sentimentos e emoções inspirados no novo lançamento da Disney. A linha conta com nove cores incríveis com acabamentos cremosos e cintilantes para você expressar suas emoções usando o esmalte ideal para o seu mood do dia. Com secagem rápida e de longa duração, seu uso proporciona cobertura com uma cor intensa, que garante unhas uniformemente coloridas e brilhosas por muito mais tempo. Ainda, possui um pincel que facilita a aplicação e é hipoalergênico, testado dermatologicamente e 6 free (livre dos 6 principais componentes mais alergênicos), além de ser aprovado 100% das manicures. Benefícios e diferenciais de Colorama Divertidamente Linha: Divertidamente 2. Disponível em 9 cores diferentes. Com secagem rápida e de longa duração. Proporciona cobertura com uma cor intensa. Garante unhas uniformemente coloridas e brilhosas por muito mais tempo. Possui pincel de fácil aplicação. Aprovado por manicures. Testado dermatologicamente. Como usar Esmalte Colorama Cremoso Divertidamente? Utilizando o pincel do vidrinho, passe uma camada sobre toda unha, começando pelas laterais e preenchendo o meio. Aguarde secar e passe uma segunda camada. Para finalizar, limpe as bordas externas com o auxílio de um palito, algodão e acetona. Advertências Uso externo. Não ingerir. Produto sensível ao calor. Caso haja contato com os olhos, lave-os abundantemente. Se houver irritação, suspenda o uso imediatamente e procure orientação médica. Conservar em local fresco e arejado. Mantenha fora do alcance das crianças.', 18.0, 18.0, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdvz-lxqxulj4kdze88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20697752654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
