INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399238884', 'Timer Digital de Tomada Bivolt 56 Programações Semanais - DNI 6610', 'Timer Digital de Tomada Bivolt 56 Programações Semanais - DNI 6610Automatize a sua residência com total praticidade utilizando o Timer Digital de Tomada Bivolt DNI 6610. Ele é um temporizador programável, com 56 programações semanais, que liga e desliga os mais diversos aparelhos de acordo com os dias e horários que você determinar. Use-o para automatizar piscinas, eletrodomésticos, iluminação residencial e comercial, entre outros equipamentos. Com a função horário de verão, o Timer Digital DNI 6610 se adapta facilmente à variação de horário durante o período, para que a automatização dos seus aparelhos seja 100% eficaz. Em caso de falta de energia, não se preocupe: o produto possui bateria interna recarregável que mantém a programação e o relógio em perfeito funcionamento. Use um contator caso precise acionar cargas maiores. AtributosMarca: DNI Modelo: DNI6610 Quantidade de Programações: 56 (8 por dia) Tensão de Trabalho (127V): Carga máxima - Resistiva: 2000W (10A); Indutiva: 400W (3A) Tensão de Trabalho (220V): Carga máxima - Resistiva: 2000W (10A); Indutiva: 600W (3A) Frequência: 50/60Hz Medidas: 10 x 7,2 x 2,8 cm Adquira o Timer Digital de Tomada Bivolt DNI 6610 e Simplifique Sua RotinaCom a capacidade de programar até 56 ações semanais, o Timer Digital DNI 6610 oferece a praticidade e conveniência que você precisa para automatizar seus aparelhos de forma eficaz.', 140.38, 140.38, NULL, 'Home Appliances > Electrical Circuitry & Parts > Switches', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-ltzm3nco2us805', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F21399238884', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
