INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8059523148', 'Registradora AZ ofício LL Azul Royal Economic Chies', 'Ache suas informações à primeira vista, arquivando em pastas A-Z de cores diferentes e codificadas na etiqueta, evitando assim o arquivamento incorreto. Altamente resistente e durável. com o mais alto padrão de qualidade e beleza. Possuem ferragens importadas de alta precisão e revestimento de fácil limpeza. Detalhes: - Tamanho: 28,5 x 34,5 x 8 cm - Revestida interna e externamente com (plástico) Polipropileno da mesma COR. - Altamente resistente e durável. com o mais alto padrão de qualidade e beleza. - Possui etiqueta dupla-face na lombada, facilitando sua organização e identificação visual dos assuntos. - Ferragens importadas de alta precisão e revestimento de fácil limpeza. - Padronize seu ambiente de trabalho com Pastas Chies. - Ache suas informações à primeira vista. arquivando em pastas A-Z de cores diferentes e codificadas na etiqueta, evitando assim o arquivamento incorreto. - Registrador LL (Lombada Larga): Possui uma estrutura mais robusta, com cerca de 7 a 8 cm de largura. É projetado para volumes maiores de documentos (aproximadamente 600 a 700 folhas).', 28.32, 22.66, NULL, 'Stationery > School & Office Equipment > Folders, Paper Organizers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-823ow-moo1givje51o6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F8059523148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298933047', 'Filtro de Óleo Wega para Yamaha XJ6 R1 R6 VMAX Super Tenere Fazer 600', 'FILTRO DE ÓLEO BLINDADO WEGA JFO0411P - YAMAHA XJ6 R1 R6 VMAX SUPER TENERE XJ600 PRODUTO NOVO - FOTOS REAIS - GARANTIA E NOTA FISCAL Produto: Filtro de Óleo Blindado Marca: Wega Referência: JFO0411P REF. OEM: 5GH1344020 / BT1150105391 Válvula de Alívio: Sim Válvula Anti-Retorno: Sim Quantidade: Valor referente a UMA (1) unidade. Condição: Produto Novo Rosca: M20 x 1,5 Dimensões: Altura: 75mm x Diâmetro Externo: 68mm APLICAÇÃO COMPLETA YAMAHA FAZER / FZS / FZR 1000 (TODOS OS MODELOS) - 1991 A 2005 FAZER 600 GENESIS - 1989 A 1996 FAZER 750 RT GENESIS - 1987 A 1988 GTS 1000 - 1991 A 1999 ROYAL STAR XVZ 1300 (TODAS AS VERSÕES) - 1996 A 2001 TDM 900 - 2003 A 2009 VMAX VMX-12 1200 - 1986 A 2004 XJ 600 / N / S DIVERSION - 1989 A 2003 XJ 900 S DIVERSION - 1995 A 2003 XJ6 600 (TODOS OS MODELOS) - 2010 A 2022 XS 1000 S - 1981 A 1982 XTZ 750 SUPER TENERE - 1993 A 1998 XV 1600 WILDSTAR - 1999 A 2003 XV 1700 ROAD STAR WARRIOR - 2003 A 2010 YZF 1000 R THUNDER ACE - 1996 A 2002 YZF 750 / SP - 1993 A 1999 YZF R1 1000 - 1998 A 2009 YZF R6 600 - 1999 A 2025 YZF R7 - 1999 A 2000 Proteção Máxima para Motores Lendários Yamaha Motores de alta performance como os da linha XJ6, R1 e R6 exigem uma lubrificação impecável. Este filtro Wega possui um sistema duplo de válvulas: a anti-retorno mantém o óleo nas galerias do motor após o desligamento, garantindo lubrificação imediata na partida, enquanto a válvula de alívio assegura o fluxo contínuo de óleo em qualquer rotação. É a segurança que seu motor Yamaha precisa para performar no seu máximo. A Escolha Certa para Clássicas e Modernas A qualidade deste filtro é comprovada por sua vasta compatibilidade com as mais icônicas motocicletas da Yamaha. Ele atende desde as lendárias VMAX e Super Tenere até as amadas XJ6 e as superesportivas da série YZF. Ao seguir as especificações originais da montadora (OEM), ele garante um encaixe perfeito e uma filtragem eficiente, sendo a escolha ideal para a manutenção da sua moto. PERGUNTAS FREQUENTES (FAQ) 1. Este filtro serve em todos os modelos de XJ6 (N, F, SP)? Sim, com certeza. Este filtro é o modelo correto para toda a linha Yamaha XJ6 600, incluindo as versões N (Naked), F (Carenada) e SP, para todos os anos de 2010 a 2022. 2. Confirma a aplicação na YZF R6 ano 2023? Sim, confirmo. Nossa lista de aplicação mostra que o JFO0411P é compatível com a YZF R6 para o ano de 2023 e se aplica a todos os modelos de 1999 até 2025. 3. Este filtro é o blindado (externo) ou o refil (interno)? Este é o modelo blindado, também conhecido como externo. É uma peça única e selada que é rosqueada na parte de fora do motor. A troca é feita removendo a peça inteira e instalando a nova. Dúvidas? Fale com a equipe da Bonanza Auto Peças. Estamos prontos para fornecer a melhor solução para sua moto!', 27.57, 27.57, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-824go-mf5strixw1e2bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1077953334%2F23298933047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
