INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49909335908', 'Camiseta Grêmio Masculina Retrô 1993 Licenciada', 'Camiseta Grêmio Retrô 1993 Masculina A Camiseta Masculina Betel Grêmio Retrô 1993 é a escolha perfeita para torcedores que valorizam história, tradição e estilo. Inspirada em uma das fases mais marcantes do clube, a peça resgata o visual clássico com um design retrô cheio de personalidade. Produzida em malha de poliéster, oferece caimento leve e confortável, ideal tanto para o dia a dia quanto para momentos esportivos. A gola polo reforça o toque elegante, enquanto as cores tradicionais destacam o orgulho de ser gremista. Características: Contém: 1 Camiseta Retro Masculina Grêmio Betel Time: Grêmio Composição: 100% Poliéster Gola: Polo Diferencial: Estilo retrô e detalhes tradicionais do Grêmio Escudo: Bordado Medidas Aproximadas: (Altura x Largura) P: 64 x 52 cm M: 67 x 55 cm G: 68 x 58 cm GG: 72 x 61 cm Ao adquirir produtos na Sloth, você está garantindo qualidade, durabilidade e originalidade. Todos os itens são comercializados com autorização da marca e acompanhados de nota fiscal. Seu pedido será processado e enviado em até 24 horas após a aprovação, com comunicação imediata em caso de imprevistos. O prazo de garantia para produtos que venham a apresentar problemas de fabricação é de 90 dias após o recebimento.', 299.9, 229.9, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-820n8-mo410a2n0xdw8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322737721%2F49909335908', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8602544346', 'Mesa De Cabeceira Suspensa Várias Cores Mesinha Com gaveta e Prateleira Criado Mudo MVD Móveis', 'A MVD MÓVEIS oferece para você a melhor opção para compra de mobiliários modulares e decorativos para deixar o seu ambiente ainda mais bonito e exclusivo! Com design próprio, os produtos da MVD MÓVEIS se inspiram na praticidade cotidiana do consumidor brasileiro com a modernidade das linhas retas projetadas pelos nossos Designers. Isso faz dos móveis da MVD MÓVEIS o mobiliário mais vendido na internet do Brasil! MVD MÓVEIS, só para você! DADOS DO PRODUTO * Tipo: Mesa De Cabeceira * Material: MDF/MDP * Dimensão: 33cm Profundidade x 30cm largura x 20cm altura ATENÇÃO * Os objetos que ambientam as fotos não acompanham o produto; * O produto será entregue DESMONTADO; * Embora o produto acompanhe o manual de montagem e seja bem simples, verifique a complexidade antes de decidir montá-lo sozinho, se tiver dificuldade recomendamos que contrate um profissional de sua confiança. A TONALIDADE DAS CORES DO MÓVEL NAS IMAGENS DO ANÚNCIO PODEM VARIAR DE ACORDO COM AS CONFIGURAÇÕES DE COR DA SUA TELA. CASO TENHA ALGUMA DÚVIDA QUANTO A COR DO MÓVEL, VOCÊ PODE VER A INFORMAÇÃO EXATA DA COR NOS "DADOS DO PRODUTO" OU CHAMAR NAS PERGUNTAS PARA SANAR A SUA DÚVIDA.', 78.0, 78.0, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/br-11134207-7qukw-livro5phnv00c9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F311163565%2F8602544346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
