INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999478283', 'ANA1108 Unhas Postiça Infantil com Diversos Modelos Sortidos para Crianças', 'Destaques do Produto 🎨 As unhas postiça infantil são perfeitas para deixar as crianças ainda mais divertidas e estilosas! Com diversos modelos e cores sortidos, cada unha traz desenhos fofos e divertidos, garantindo variedade e alegria para o dia a dia. O material é à base de água, super fácil de remover com água morna, tornando o uso seguro e prático para as pequenas. Opções de Compra 📦 - Você pode escolher uma caixa com 12 unhas postiças, um conjunto com 6 caixas (72 unhas no total) ou um conjunto com 12 caixas (144 unhas no total). - Modelos variados e sortidos em cada embalagem, proporcionando sempre novas combinações e estilos. Como Usar 👐 Para aplicar, basta selecionar o tamanho ideal, limpar as unhas naturais e pressionar firmemente. O uso de cola não é obrigatório, mas pode ser recomendado para maior durabilidade. Informações Importantes 📝 - Indicado para crianças que desejam se divertir e se arrumar com segurança. - Produto fácil de aplicar e remover, pensado especialmente para o público infantil. - Disponível em diferentes tamanhos para melhor ajuste. Garanta já a diversão e a praticidade para as crianças com este kit incrível de unhas postiça!', 15.0, 10.01, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/br-11134207-820lz-motnmygutvr91d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1430626556%2F23999478283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
