INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497271771', 'Caixa Organizadora Plástica Rosé 30L My Closet Ordene', 'Caixa Organizadora Plástica 30L Cristal com Tampa Concreto My Closet Ordene – Organização Moderna e Funcional A Caixa Organizadora Plástica 30L Cristal com Tampa Concreto My Closet Ordene é a escolha ideal para quem deseja manter a casa organizada com praticidade e um toque de sofisticação. Desenvolvida em parceria com personal organizers, a linha My Closet oferece soluções inteligentes para otimizar espaços, aliando design minimalista, funcionalidade e cores modernas. Com capacidade de 30 litros, a caixa é perfeita para armazenar roupas, roupas de cama, calçados, brinquedos, documentos, acessórios e diversos objetos do dia a dia. Seu corpo transparente (cristal) permite visualizar facilmente o conteúdo sem a necessidade de abrir a caixa, enquanto a tampa na cor concreto proporciona um visual elegante e contemporâneo que combina com diferentes estilos de decoração. Fabricada em plástico resistente e de alta qualidade, conta com um design funcional que facilita a abertura, o manuseio e a organização de armários, closets, lavanderias, escritórios e outros ambientes. Benefícios da Caixa Organizadora My Closet Ordene: Capacidade de 30 litros Corpo transparente para fácil visualização do conteúdo Tampa na moderna cor concreto Design minimalista desenvolvido com personal organizers Grande capacidade para organização Fácil de abrir e manusear Material resistente e durável Fácil de limpar Ideal para otimizar espaços em closets, armários e prateleiras Ideal para Organizar: Roupas e roupas de cama Calçados Toalhas Brinquedos Produtos de higiene Documentos Materiais de escritório Objetos diversos Especificações do Produto: Marca: Ordene Linha: My Closet Capacidade: 30 litros Material: Plástico resistente Cor do corpo: Cristal (transparente) Cor da tampa: Concreto Dimensões: 23,5 x 53 x 37,8 cm (A x L x C) Transforme a organização da sua casa com a qualidade, a resistência e o design exclusivo da Caixa Organizadora My Closet Ordene.', 75.9, 75.9, NULL, 'Home & Living > Home Organizers > Others', 'https://cf.shopee.com.br/file/sg-11134201-825a9-mqnsrtqddjb54d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F23497271771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498326269', 'Kit Valvula De Admissao e Escape Celta Prisma Onix Classic Corsa 1.0 8v VHC-E SPE4 2008 A 2016 6mm', '!! ATENÇÃO, ESSE MODELO É PARA CABEÇOTES QUE USAM VÁLVULAS DE 6mm !! KIT VÁLVULAS DE ADMISSAO E ESCAPE - ALTO DESEMPENHO E DURABILIDADE PRODUTO ORIGINAL TAKAO - QUALIDADE GARANTIDA MARCA: TAKAO COMPATÍVEL COM: Motores GM 1.0 8V VHC-E / SPE4 / NLEV QUANTIDADE: 4x VALVULAS DE ADMISSÃO 33.00 x 5.96 x 104.70mm 4x VALVULAS DE ESCAPE 29.00 x 5.95 x 104.70mm REFERÊNCIA OEM: 93361392 / 24579670 PRODUTO NOVO, COM NOTA FISCAL E PRONTO PARA ENVIO APLICAÇÕES COMPATÍVEIS GM CELTA 1.0 8V VHC-E 2013 A 2016 CLASSIC 1.0 8V VHC-E 2008 A 2016 CORSA 1.0 8V 2010 ONIX 1.0 8V SPE/4 2012 A 2022 PRISMA 1.0 8V SPE/4 2009 A 2016 POR QUE ESCOLHER ESTE PRODUTO Fabricado com materiais de alta resistência, garantindo maior vida útil. Desenvolvido para proporcionar ótima vedação e desempenho no motor. Produto original Takao, referência no mercado de componentes automotivos. ANTES DE FINALIZAR A COMPRA, CONFIRA A COMPATIBILIDADE COM O SEU VEÍCULO. PARA QUALQUER DÚVIDA, CONSULTE NOSSA EQUIPE ESPECIALIZADA.', 222.96, 222.96, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd50-m7gkwvkrbmy880', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1077953334%2F22498326269', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
