INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52561481651', 'Cookie Recheado Sabor Red Velvet 75g - 1 unidade', 'Delicie-se com o Cookie Recheado Red Velvet, uma combinação irresistível de sabor e textura. Produzido com chocolate nobre, uma experiência intensa e sofisticada a cada mordida, com massa macia e levemente crocante por fora. O grande destaque está no recheio cremoso, que ganha ainda mais protagonismo quando aquecido: basta 30 segundos no micro-ondas para o chocolate derreter e transformar o cookie em uma sobremesa ainda mais indulgente e envolvente. Perfeito para um momento de prazer no dia a dia ou para acompanhar um bom café, esse cookie une praticidade e um sabor marcante que conquista desde a primeira mordida.', 15.9, 15.9, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/br-11134207-820l8-moxxe1wjnvuu90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1321479779%2F52561481651', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
