INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53510372396', 'Vara De Pesca Telescópica 3,00m P/ Molinete Ryumar Summer Fibra De Vidro Leve E Resistente Pesca Iniciante Promoção', 'Vara de Pesca Telescópica Ryumar 3,00m p/ Molinete Summer Fibra Vidro Leve e Resistente Pesca Iniciante Promoção A vara telescópica para molinete Ryumar Summer é uma opção acessível pensada para quem quer começar na pesca ou ter um equipamento reserva sem investir alto. Entrega um bom desempenho dentro da sua proposta, sendo ideal para pescarias leves com ótimo custo-benefício. Sua ponta fina proporciona boa sensibilidade, ajudando a perceber fisgadas com mais facilidade, enquanto a cor vibrante auxilia na visualização durante o uso, trazendo mais praticidade na pescaria. Fabricada em fibra de vidro, atende bem a usos ocasionais e pescarias em lagos, rios, pesqueiros e represas. É uma vara leve, fácil de transportar e simples de utilizar, perfeita para quem busca funcionalidade sem complicação e sempre pronta para uso. ESPECIFICAÇÕES: Marca: Summer Modelo: Ryumar 300 Tamanho aberto: 3,00 m Tamanho fechado: 57 cm Peso da isca: 40-80 g Material: Fibra de vidro Peso: 220 g Passadores: 5 + 1 ponteira Cor: Sortida, conforme disponibilidade em estoque. Fotos ilustrativas para destacar os detalhes do produto.', 59.9, 59.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-820lg-mo5j3lcvm5fl39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F53510372396', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998263259', 'Jaqueta Masculina John Sailor Bomber Marinho', 'Versátil e cheia de estilo, esta Jaqueta Masculina John Sailor Bomber Marinho é ideal para compor looks urbanos e modernos. Com barra e punhos canelados, oferece ajuste confortável e um acabamento clássico do modelo. Conta com 2 bolsos com zíper, garantindo praticidade e segurança para guardar seus itens no dia a dia. Uma peça curinga para quem busca conforto e atitude em qualquer ocasião. As Lojas Radan contam com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto de autenticidade garantida vendido pela Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Nome do produto: Jaqueta Masculina John Sailor Bomber Marinho Indicado: Dia a dia Tipo de Jaqueta: Bomber Composição: 100% Poliéster Fechamento: Zíper Bolsos: 2 bolsos frontais com zíper Tipo de tecido: Plano Tipo de Gola: Média Nível de Aquecimento: Médio Diferencial: Barra e punhos canelados, 2 bolsos com zíper Dimensões Aproximadas: Medidas do modelo: Altura: 1,82m - Manequm 40 Modelo veste: Tamanho M - Manga: 78cm - Comprimento: 64cm - Circunferência: 98cm Peso do produto: 670g', 219.99, 209.99, NULL, 'Men Clothes > Jackets, Coats & Vests > Winter Jackets & Coats', 'https://cf.shopee.com.br/file/sg-11134201-81zuz-mmuon1v4xhqgef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F19998263259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
