INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42179237352', 'Fluido Facial NIVEA Antimarcas Luminous 630 FPS 50 40ml', 'O que é? NIVEA Fluido Facial Cellular Luminous 630® é um produto inovador que utiliza a tecnologia patenteada Luminous 630® para reduzir manchas escurecidas e uniformizar o tom da pele. Para que serve? Sua fórmula exclusiva combina Ácido Hialurônico, Vitamina E e filtro UVA/UVB para proporcionar resultados visíveis em apenas 4 semanas de uso. Este fluido facial serve para prevenir e tratar manchas causadas pelo sol, deixando a pele mais uniforme e livre de imperfeições. Além disso, sua textura leve e de rápida absorção permite uma aplicação fácil e confortável. Com NIVEA Fluido Facial Cellular Luminous 630® você terá uma pele radiante e protegida todos os dias. Benefícios e diferenciais: - Reduz marcas escurecidas uniformizando o tom da pele - Previne manchas causadas pelo sol - Resultados visíveis em 4 semanas - Reduz a produção de melanina para uma pele com tonalidade homogênea - Para uma pele mais uniforme e iluminada,', 145.25, 145.25, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-82625-mlrr8db6y9s28e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F42179237352', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
