INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092578481', 'Protetor Solar Expertise Fps60 Antioleosidade Loréal Paris', 'Protetor solar facial para todos os tipos de peles, em especial as oleosas, L''Oréal Paris Solar Expertise Antioleosidade FPS 60 proporciona proteção contra os raios solares e prevenção ao envelhecimento precoce, Ele tambem é ideal para o uso diário, Sua formulação proporciona alta proteção contra os raios UVA/UVB, além de ajudar na prevenção do aparecimento de rugas e manchas causadas pela exposição solar. Com textura leve e fácil de espalhar, é facilmente absorvido pela pele, além de controlar a oleosidade durante o dia, garantindo um efeito matte duradouro. Como Usar: Aplique o protetor solar abundantemente antes da exposição ao sol. Se a quantidade aplicada não for adequada, o nível de proteção será significativamente reduzido. É necessário fazer a reaplicação do produto para manter a sua efetividade.', 69.9, 57.21, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbmg-ln1v8or1c2d6f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F22092578481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697413054', 'SÉRUM FACIAL ANTI IDADE LUMINOUS 630 NIVEA 30ML ( VALIDADE 06-2027 )', 'Este sérum tem uma fórmula poderosa que atua na redução de marcas escurecidas da pele, apresentando resultados visíveis em duas semanas.Com ácido hialurônico, NIVEA Luminous 630 Anti-idade preenche profundamente as rugas em 7 dias. Além disso, estimula a produção de colágeno, ajudando na recuperação de volume e firmeza da pele.Este sérum conta também com Luminous 630, um ingrediente que atua em nível celular e que é resultado de pesquisas minuciosas realizadas durante 10 anos. Seu efeito antimarcas é comprovado em todos os tons de pele, deixando-as uniformes e iluminadas. Benefícios - Anti-idade - Reduz 10 anos de marcas de idade acumuladas com primeiros resultados visiveis em 2 semanas - Fortalece a estrutura da pele, preenchendo as rugas visivelmente em 7 dias. - Uniformiza e ilumina a pele. MODO DE USO Aplique duas vezes ao dia, de manhã e à noite, no rosto limpo antes de sua rotina diária de cuidados com a pele. Espalhe o sérum por todo o rosto. (Para melhores resultados e para proteger da formação de novas marcas escurecidas, use de manhã em combinação com CELLULAR LUMINOUS630 ANTISPOT Fluido FPS50)', 129.9, 67.69, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/sg-11134201-7rcch-lt75n66q3s5r58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F23697413054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
