INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259710622', 'Papel Toalha Scala plus 2 rolos', '"O Papel Toalha Scala Plus 2 Rolos é um item essencial para a rotina da sua casa, projetado para oferecer praticidade, alta absorção e resistência nas mais diversas tarefas do dia a dia. Ideal para secar superfícies, alimentos ou absorver líquidos com eficiência. Produzido com celulose de qualidade, este papel toalha possui uma estrutura que garante boa resistência mesmo quando molhado, facilitando limpezas rápidas e sem desperdícios. Seja na cozinha, após preparar refeições, na higienização de frutas e legumes, ou para limpeza de bancadas e utensílios, o Scala Plus atende às necessidades de quem busca um produto versátil e funcional. Seu design compacto torna o uso e armazenamento ainda mais práticos, sendo perfeito tanto para uso doméstico quanto para pequenos negócios que precisam de uma solução de limpeza eficaz. Combinando absorção eficaz, durabilidade e fácil manuseio, o papel toalha Scala Plus é um aliado confiável para manter a sua casa sempre limpa e organizada."', 6.79, 6.79, NULL, 'Home & Living > Home Care Supplies > Toilet Paper', 'https://cf.shopee.com.br/file/sg-11134201-825af-mqnekmlrzdvk7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554886%2F58259710622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
