INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098914196', 'RUM MALIBU GARRAFA DE 750ML', 'Nada bate um original, e Malibu não é apenas o original, é o mais vendido rum do Caribe com sabor natural de coco no mundo, estando presente em mais de 150 países. O sabor marcante do rum Malibu é a representação da luz do sol dentro de uma garrafa - suave, com um sabor de coco fresco e um final doce - perfeito para uma experiência descontraída de beber e um sabor adequado ao estilo de vida nas ilhas do Caribe O rum Malibu de 750ml possui uma graduação alcoólica de 21%. É proibida a venda e o consumo de bebidas alcoólicas para menores de 18 anos. Se beber não dirija.', 71.99, 65.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mefubaw52sxt98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22098914196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
