INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598677022', 'Kit Giorno Lavanderia Sentire Bene Baby (2 produtos)', 'Kit Giorno Lavanderia Sentire Bene Baby (2 produtos) Giorno Lavanderia Sentire Bene Baby - Água de Passar 500ml: inspirado no toque suave dos bebês, a fragrância relembra os tempos gostosos e felizes da infância. Sua fórmula facilita o deslize do ferro de passar nas roupas, roupas de cama, mesa e banho, dificulta a reprodução de bactérias, além de perfumar com uma fragrância aconchegante. Giorno Lavanderia Sentire Bene Baby - Home Spray 250ml: inspirado no toque suave dos bebês, a fragrância relembra os tempos gostosos e felizes da infância, preenchendo seu ambiente com uma atmosfera singular através do perfume inebriante, aconchegante e único. Evoca lembranças gostosas de momentos felizes. Conselho de Aplicação Gire o bico do gatilho para destravar. Aplique a uma distância a 20cm do tecido a ser perfumado.', 73.24, 73.24, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Diffusers, Humidifiers & Oil Burners', 'https://cf.shopee.com.br/file/sg-11134201-7ra3b-mbfbfb24qd2f9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22598677022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
