INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22920371998', 'Chave biela 10 mm aço cromo vanádio - 25B Gedore', 'Produto: Chave biela 10 mm aço cromo vanádio - 25B Marca: Gedore Descrição: A Chave Biela 10 mm Aço Cromo Vanádio - 25B, da Gedore é essencial para profissionais que buscam precisão e confiabilidade, esta ferramenta é projetada para superar suas expectativas em trabalhos de montagem e manutenção. Características: • Fabricação Premium: Construída com Aço Gedore-Vanadium, um material reconhecido por sua resistência superior e durabilidade prolongada. • Acabamento Superior: Conta com um acabamento niquelado e cromado, não apenas para uma estética superior, mas também para proteção contra corrosão e desgaste. • Design Ergonômico: Modelo longo com cabeças de perfil cônico e paredes finas que facilitam o acesso a locais apertados e de difícil acesso. • Versatilidade: A chave apresenta sextavado interno nos dois lados da mesma medida, ideal para fixar ou soltar parafusos com sextavados, garantindo aperto e desaperto eficaz e seguro. Especificações: Tamanho: 10 mm Fabricado em Aço Gedore-Vanadium; Acabamento niquelado e cromado; Modelo longo, cabeças de perfil cônico com paredes finas; Chave com sextavado interno, dois lados sextavados de mesma medida. Peso: 0.33 Kg', 55.07, 55.07, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825at-mr0qr8dy49ol46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F22920371998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18553855903', 'Chave catraca reversível encaixe 1/2pol CRV 140159 MTX', 'Produto: Chave catraca reversível encaixe 1/2" aço cromo vanádio - 140159 Marca: MTX Descrição: A Chave catraca reversível encaixe 1/2" aço cromo vanádio - 140159 da MTX é uma ferramenta manual para instalar e remover conexões rosqueadas. Compatível com soquetes com soquete de 1/2". Está equipado com o mecanismo de catraca que facilita o trabalho em locais de difícil acesso. A ferramenta é usada para reparar equipamentos, carros, também é usada na vida cotidiana. Características:" Feita de aço cromo-vanádio de alta qualidade, durável e resistente ao estresse. A cromagem oferece proteção contra corrosão. O soquete não se solta durante a operação, pois é segurado com segurança por um retentor de esfera de metal. O mecanismo de inversão permite alterar rapidamente o sentido de rotação. Usando a função de liberação rápida, você pode trocar o bico em poucos segundos. A Superfície texturizada da alça evita escorregar, por isso é confortável trabalhar com a chave. Especificações: Material: aço cromo vanádio Acabamento: cromado Encaixe: 1/2" Sistema de reversão com pino Comprimento total da chave: 250 mm. Peso: 0.30 Kg', 119.3, 119.3, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mr4a0dzadcsn73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F18553855903', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
