INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399209886', 'Pedal de Cambio Esportivo Universal Moto Passador Marcha', 'Serve perfeitamente em motos que não possuem haste no câmbio como: CRF TTR XR NX XLR BROS XTZ DT 180 / 200 CG todas 125 / 150 / 160 YBR / FACTOR . Pedal de câmbio esportivo ajustável - Ideal para pilotos de competição e para uso do dia a dia, ajuste de acordo com sua necessidade, proporcionando conforto e segurança na pilotagem. Especificação: - Universal - Material: Alumínio CNC de alta qualidade - Ajuste para frente e para trás, conforto e segurança - Fácil instalação Itens inclusos: - 01 pedal de câmbio ajustável', 59.9, 40.5, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m80t7yerfqpd19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1188055013%2F20399209886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
