INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397358570', 'Tapete Higiênico Pet P/ Cães Ultra Espaço De Bicho Lavanda 80x60 90unid', 'O Tapete Higiênico Pet Like Ultra Pads Lavanda é um excelente tapete compacto, indicado para cães de todos os portes. Com tecnologia Floc Gel americana e sistema de absorção japonesa. Simples e prático, é elaborado com matérias que garantem uma super absorção. Com barreiras nas laterais de proteção, evita que o xixi vaze. O seu design garante uma melhor distribuição do xixi. Super leve e fino, o produto ainda é capaz de neutralizar o mau cheiro, conservando um ambiente higienizado. Além disso o tapete possui um atrativo canino, facilitando o treinamento do seu pet seja ele filhote ou adulto. Características: - Indicado para cães; - Com atrativo canino; - Melhor distribuição do xixi; - Barreiras que evitam o vazamento; - Com fita adesiva, melhor fixação; Cuidados: - Colocar o tapete distante da alimentação do cão; - Manter em local arejado e longe do alcance de crianças; - Caso o cão rasgue o tapete, jogue-o no lixo; - Produto descartável. Composição: - Filme de polietileno, tecido não-tecido, celulose, papel, polímero super absorvente, atrativo. Especificações: - Acessórios para pets - Modelo: Ultra Pads - Tapete higiênico - Unidades na embalagem: 90 un - Medidas: 80x60cm', 229.9, 164.9, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lryllauvg1sd2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F823664460%2F22397358570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
