INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394298516', 'Kit Polimento Para Vidro Boina Feltro Suporte E Interface 3', 'Quer um kit compacto e eficiente para polir vidros com segurança térmica e acabamento impecável? Características do Produto: – 1 Boina de Feltro para Polimento de Vidros 3" – 1 Suporte Injetado com Aderência Pluma Fixa 3" – 1 Adaptador M14 x 5/8 – 1 Interface Pluma Fixa Dupla Face 3" – Produzido com equipamentos de ponta e balanceamento mecânico preciso – Tecnologia exclusiva que reduz o aquecimento durante o polimento Por que escolher este produto: – Ideal para áreas menores e de difícil acesso – Evita o superaquecimento da superfície – Proporciona polimento uniforme e seguro – Fixação firme e componentes duráveis – Compatível com politrizes rotativas Dicas de Uso: – Use com compostos específicos para polimento de vidro – Mantenha a boina sempre em movimento para evitar marcas – Limpe bem a superfície antes do uso – Utilize em rotações moderadas Perguntas Frequentes: – É indicado para retrovisores e cantos de vidros? Sim, o tamanho de 3" é ideal para áreas pequenas e detalhadas. – Acompanha todos os acessórios necessários? Sim, o kit é completo para uso imediato com politriz. Tenha precisão e qualidade no polimento de vidros com o Kit Boina Vitro Polish 3” Rei dos Autos.', 149.0, 149.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Polisher', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md6464irukn56f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1057297696%2F23394298516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207067069', 'Tênis Dakota Casual Feminino D2291', 'Produto marca Dakota. Este é o Tênis Dakota Casual, a escolha definitiva para quem não abre mão de estilo e conforto em uma única peça. Com um design imponente e sola baixa de 2,90 cm, ele se destaca pela rica sobreposição de materiais, unindo o sintético de alta durabilidade ao couro legítimo. o grande protagonista é o detalhe em animal print, que traz a textura luxuosa do pelo ou a textura em algumas combinações, garantindo um visual autêntico e cheio de personalidade para qualquer ocasião. Desenvolvido para acompanhar o seu ritmo, este tênis oferece o ajuste perfeito através de cadarços de amarrar, proporcionando segurança e bem-estar durante todo o dia. Ele é o aliado ideal para o lifestyle urbano, transitando perfeitamente entre os compromissos do dia a dia e os momentos de lazer. Com apenas 0,709 kg, ele entrega leveza sem perder a robustez, sendo um investimento inteligente para quem busca um calçado duradouro e com acabamento premium. Eleve seu guarda-roupa com um calçado que é tendência absoluta e destaque-se com a sofisticação da marca Dakota. Seja combinando com um jeans básico ou com peças mais elaboradas, este tênis casual é o toque final que transforma o comum em extraordinário. Aproveite a versatilidade de um produto que une a resistência do couro à modernidade do design contemporâneo e sinta a diferença em cada passo. Peso: 0,709 kg', 310.9, 310.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-825zo-mlxnedxb3oy07e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F58207067069', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998912830', 'Alvos de Papel para Airsoft e Airguns 140x140mm PCT 5und - Rossi', 'Alvos de Papel Rossi para Airsoft e Airguns 14x14cm Pacote com 5 Unidades Alvos de papel para Tiro esportivo da Rossi com sistema de pontuação, indicado para treinos, prática esportiva e lazer. Por que escolher os Alvos Rossi 14x14cm? Praticidade: kit compacto e pronto para uso imediato. Compatibilidade: funciona em coletores de alvos e com armas de pressão ou Airsoft. Visual claro: marcações de pontuação em Branco e Preto facilitando o acompanhamento dos disparos. Treino completo: ideal para melhorar precisão, coordenação e desempenho. Garanta já os seus Alvos Rossi na Falcon Armas! Mais de 26 anos de experiência, pagamento seguro e envio para todo o Brasil. Características Marca: Rossi Modelo: Airsoft e Airguns Material: Papel Tamanho: 14x14 cm Quantidade: 5 alvos Cores: Branco e Preto Peso: 17 g Garantia 3 meses contra defeitos de fabricação Itens Inclusos 5x Alvos descartaveis 14x14cm Rossi 1x Nota Fiscal Imagens meramente ilustrativas. As cores e detalhes podem variar de acordo com sua tela e o produto final.', 12.9, 12.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-824jh-mf0989yks7beae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F654132276%2F23998912830', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8439020270', 'Pijama Aberto De Inverno Feminino Tamanho Grande Plus Size XG XGG EXG Blusa Comprida E Calca De Frio', 'Lindo Pijama de Inverno mangas e calcas longas, para quem gosta de dormir com um pijama confortavel, mas nao abre mao da qualidade e de estar sempre bem vestida. Confeccionado em poliester, composto por blusa e calca. Ideal para os momentos de descanso em casa; Manga longa; Pijama com tecido em Poliester; Calca com elastico no cos; Lindo, moderno e estiloso; Modelo estampado; Tamanhos plus size XG, XGG E EXG.', 99.98, 99.98, NULL, 'Women Clothes > Sleepwear & Pajamas > Pajamas', 'https://cf.shopee.com.br/file/2e5ff5ae268adeb47081498a4479faec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308601970%2F8439020270', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
