INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20403933025', 'PNEU PIRELLI PHANTOM STREET 26X1.50 SLICK MTB URBANO', '🚴‍♂️ PNEU PIRELLI PHANTOM STREET 26x1.50 – ROLAGEM RÁPIDA NO ASFALTO O Pneu Pirelli Phantom Street 26x1.50 é ideal para quem utiliza bicicleta MTB no ambiente urbano e busca mais velocidade, conforto e eficiência no asfalto. Com desenho slick (liso), proporciona menor atrito com o solo, resultando em uma pedalada mais leve, silenciosa e rápida, perfeito para deslocamentos diários, ciclovias e uso urbano. Sua estrutura garante boa durabilidade e estabilidade, mesmo em uso frequente. Produzido pela Pirelli, referência mundial em pneus. 🔧 PRINCIPAIS BENEFÍCIOS • Banda slick (lisa) para maior velocidade • Rolagem mais leve e silenciosa • Ideal para uso urbano e ciclovias • Boa durabilidade para uso diário • Excelente custo-benefício 📌 ESPECIFICAÇÕES TÉCNICAS Marca: Pirelli Modelo: Phantom Street Aro: 26 Medida: 26 x 1.50 Tipo: Slick (liso) Cor: Preto Aplicação: Urbano / MTB 🔗 COMPATIBILIDADE ✔ Bicicletas aro 26 ✔ Uso em asfalto e ciclovias ✔ Quadros compatíveis com pneus 1.50 ⚠ Verifique a medida do pneu atual antes da compra. 📦 CONTEÚDO DA EMBALAGEM • 1 Pneu Pirelli Phantom Street 26x1.50 ❗ INFORMAÇÕES IMPORTANTES • Produto original Pirelli • Produto novo e pronta entrega • Acompanha nota fiscal • Não acompanha câmara de ar ❓ FAQ – DÚVIDAS FREQUENTES Esse pneu é liso? Sim. Possui banda slick, ideal para asfalto. Serve para trilha? Não é indicado. É ideal para uso urbano. Pode usar na frente e atrás? Sim. Pode ser utilizado em ambas as rodas. É mais rápido que pneu cravado? Sim. O slick oferece menor resistência e maior velocidade no asfalto. RM BIKES', 65.99, 64.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lrreczvf262j1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369650932%2F20403933025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898578347', 'Filtro de Combustivel Zafira 2.0 8v Flex Power MPFI Comfort Elegance Elite 2007 2008 2009 2010 2011 2012', 'Similar ao original: FCI1660 *** NÃO SERVE NO MODELO GASOLINA - SOMENTE FLEX *** Usamos Fotos REAIS EM TODOS NOSSOS ANUNCIOS Produto com a qualidade Peças Premium Todos os nossos produtos acompanham nota fiscal Para compras com CNPJ de fora do Estado de São Paulo, o valor do imposto, (ST) Substituição Tributária NÃO ESTÁ INCLUSO NO VALOR DO PRODUTO ANUNCIADO, caso deseje comprar com CNPJ, após a emissão da nota fiscal, será calculado o valor do imposto de (ST), Substituição Tributária, que será COBRADO separadamente e antecipadamente. LEMBRANDO QUE O VALOR DO IMPOSTO, (ST) É COBRADO PELO ESTADO DE DESTINO e mercadoria só poderá ser despachada após o recolhimento antecipado. Peças Rápidas - O seu shopping de auto peças online!', 30.34, 30.34, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134201-7qukw-lhjfqnzn8ol3d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513651190%2F20898578347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
