INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40269768300', 'Leite De Coco Em Pó 180G Monama Vegano', 'O Leite de Coco em Pó Monama oferece de forma prática e saudável todos os benefícios do coco em forma de uma bebida vegetal instantânea, deliciosa e nutritiva! Super versátil, ele pode ser consumido como ¨leite vegetal¨, com café ou também em receitas, frutas, shakes e bowls. Experimente!. O Leite de Coco em Pó Monama é totalmente livre de lactose e glúten. • Vegano – Não contém ingredientes de origem animal. • Ótima opção para quem não pode ou não quer consumir o leite de vaca. • Forma prática e saudável de consumir os benefícios do Coco no dia a dia. • Rico em gorduras boas! Proporciona mais saciedade. • Super cremoso e com sabor incomparável. • Prático e versátil. DICA DE PREPARO: Misture 2 colheres de sopa com 250ml de água quente ou fria, e está pronto! DICA DE CONSUMO: Em forma de bebida/leite vegetal, com café, polvilhado em frutas, vitaminas e bowls, em mingau e açaí, em receitas diversas. Leite de coco, maltodextrina, conservantes INS 211 e INS 223. ALÉRGICOS: PODE CONTER AVEIA, AMENDOIM, AMÊNDOA, CASTANHA-DECAJU, CASTANHA-DO-PARÁ, AVELÃ, SOJA E NOZES. NÃO CONTÉM GLÚTEN', 35.04, 26.15, NULL, 'Food & Beverages > Dairy & Eggs > Milk', 'https://cf.shopee.com.br/file/sg-11134201-824j1-mesvjsrpkc8xba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F40269768300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799231533', 'Kit 2 Água Micelar Ácido Hialurônico Make Out 250ml Dermachem', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - APRESENTAÇÃO: Kit com 2 Unidades - - - - - DESCRIÇÃO: A Água Micelar com Ácido Hialurônico 10 em 1 Make Out Muito mais Dermachem Laboratory é diferenciado pois foi desenvolvida com ativos especiais e uma tecnologia inovada. Possui muito mais tecnologia na formação de micelas em limpar e higienizar, demaquilar e purificar a pele, possui ativos como ácido hialurônico e d-pantenol que hidratam e tonificam a pele proporcionando efeito 3D, com isso tem efeito atenuador de linhas de expressão. E mais, tem ativo calmante que deixa a pele com total sensação de descansada e com um bem estar incrível. Make out muito mais que uma água micelar, é um composto de benefícios tecnológicos para sua pele. Remove maquiagem até a prova d’água e é um produto OIL FREE. Seja bem vinda ao mundo tecnológico MakeOut Muito Mais da Dermcham Laboratory. - - - - - MODO DE USO: Para a remoção da maquiagem, aplicar sobre um disco de algodão massageando a pele com os olhos fechados até completar a remoção da maquiagem. Para efeito calmante, aplicar sobre um disco de algodão ou algumas gotas na palma da mão em quantidades mais abundantes e aplicar sobre a pele e aguardar a secagem. Para efeito 3D das linhas de expressão. aplica 2 demão em discos de algodão, de preferência sobre as linhas de expressão. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 43.0, 25.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/br-11134207-81ztc-miuewsgyapz6d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F19799231533', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
