INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16579810995', 'Kemei 1990 Profissional Fade Homens Aparador De Cabelo Máquina De Corte Elétrico Display LCD Barbeiro Cortador De Pentes De Limite Magnética', 'Característica do recurso: Há uma tela LCD no corpo, que pode exibir a eletricidade atual ao trabalhar e carregar. Lâmina de aço inoxidável afiada para aparar seus cabelos de forma rápida e precisa, nenhum cabelo fica preso e sem machucar sua pele. Uma alavanca de lâmina conveniente para ajustar o comprimento da lâmina, proporcionando um desempenho mais suave e preciso em seus cabelos. Equipado com 4 pentes de limite de comprimento diferentes, você pode controlar facilmente o comprimento do cabelo que deseja aparar e criar vários estilos de cabelo. Cordão E Uso Duplo Sem Cordão, Não Mais Longo Para se preocupar Com Sem Eletricidade, Mais Conveniente. Após 3 horas de carga total, pode ser usado continuamente por 3 horas. Especificação: Material: ABS Voltagem: 110-240V Frequência de frequência: 50/60Hz Potência: 5W Tempo de carregamento: 3 horas Tempo de uso: 180 minutos Modo de limpeza do modo de limpeza: Não à prova d''água, limpe por escova de limpeza Cor da imagem: Como mostra a imagem Conteúdo da Embalagem: 1 x Cortador de Cabelo Capa protetora de lâmina 1 x cabo USB Pentes Limite Magnético Escova de limpeza Nota: KM-809PG é pente de limite normal, não Pentes de limite magnético, a versão antiga do KM-PG1990 vem com um pente, mas a nova versão não acompanha pente.', 300.0, 126.0, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m65all0jrfsrff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450997010%2F16579810995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
