INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497650080', 'Palheta Limpador de Parabrisa Fiat Ducato ano 94 a 17 Universal', 'Descubra a excelência em limpeza de para-brisa com nossa linha de produtos premium. Projetados para oferecer durabilidade superior e desempenho sem ruído, nossos limpadores em silicone garantem uma visibilidade impecável, independentemente das condições climáticas. Encontre a solução ideal para manter sua visão nítida e sua jornada segura em todas as viagens. Compatível com: Limpador de Parabrisa Fiat Ducato ano 94 a 17 Universal. Acompanha: 1 - Palheta Limpador de Para-brisa dianteiro Motorista 22" 1 - Palheta Limpador de Para-brisa dianteiro Passageiro 22" 1 - LIMPA PARA-BRISAS FORCE ONE 100ML Universal Investindo em qualidade e confiança, nossos produtos também incluem a garantia do fabricante de 90 dias. Adquira já e desfrute de uma visibilidade máxima com nossos limpadores de para-brisa premium', 29.9, 29.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxwuav25sbkia4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F23497650080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997745441', 'Saco Para Lixo Preto 30L 30un Utilix - Dover Roll', 'Saco Para Lixo Preto 30L 30un - Utilix Mantenha seu ambiente limpo e sustentável com o Saco Para Lixo Preto 30L 30un da Utilix, uma submarca da renomada Dover-Roll, reconhecida por sua qualidade e inovação há mais de 39 anos. Estes sacos para lixo são o melhor e mais sustentável do Brasil, oferecendo uma solução confiável e acessível para suas necessidades de descarte de resíduos. A Dover-Roll, integrando e fomentando a Economia Circular, utiliza plásticos reciclados, retirados do meio ambiente, em seus produtos, contribuindo para a preservação dos recursos naturais. Além disso, a produção é alimentada por fontes de energia limpa, 100% renováveis, demonstrando o compromisso da marca com a sustentabilidade ambiental. Com o selo euReciclo, os produtos da Dover-Roll são parte de uma iniciativa que busca soluções sustentáveis para minimizar o impacto ambiental causado pelo descarte inadequado de materiais, promovendo a reciclagem como a melhor opção pela sustentabilidade. Os sacos para lixo Utilix passam por um rigoroso processo de controle de qualidade, garantindo alta tecnologia e resistência. Com medidas de 59 x 62cm, esses sacos não vazam e são ideais para uso doméstico e comercial. Escolha a qualidade e a sustentabilidade com o Saco Para Lixo Preto 30L 30un da Utilix, uma opção confiável para manter seu ambiente limpo e contribuir para um futuro mais verde. Especificações Marca: Utilix Modelo: Sacos Para Lixo Capacidade: 30 litros por saco Quantidade: 30 sacos Cor: Preto Medidas do saco: 59 x 62cm', 25.9, 25.9, NULL, 'Home & Living > Home Care Supplies > Plastic Bags & Trash Bags', 'https://cf.shopee.com.br/file/sg-11134201-7rdxz-lzs2kpn20mled1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F23997745441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698773454', 'Lampada Led Farol Alto Chevrolet Montana 2003-2010 20000lm', 'Lâmpada Led Force One Adquira já as lâmpadas automotivas com melhor custo benefício do mercado Efeito Xênon! Conteúdo da Embalagem: - 2 Super Led H7 - Alto - 2 Pingo Led - Chicotes - Manual do Usuário KIT COMPLETO PARA INSTALAÇÃO Aplicação: Chevrolet Montana 2003 Aplicação: Chevrolet Montana 2004 Aplicação: Chevrolet Montana 2005 Aplicação: Chevrolet Montana 2006 Aplicação: Chevrolet Montana 2007 Aplicação: Chevrolet Montana 2008 Aplicação: Chevrolet Montana 2009 Aplicação: Chevrolet Montana 2010 Lâmpadas Super Led ? 20000Lumêns e 6500k Aumente a projeção e alcance de luz com a tecnologia LED, com o Par de Lâmpadas, trazendo maior segurança e visibilidade durante a direção noturna. As lâmpadas não requerem utilização de reator, possui coloração branca e sistema de arrefecimento com dissipador de calor, melhora consideravelmente a luminosidade proporcionando muito mais visualização das vias! *PAR DE LÂMPADAS SUPER LED V10* Especificações Técnicas: Tecnologia Alemã. Design Compacto. Tonalidade: 6500K (Kelvins) Extremamente Branca. Tecnologia Alemã. Resistente a Água. Base e Corpo da Lâmpada em Metal. Eficiência de 20000 Lúmens do Par. Longa Vida Útil, Dura Até 2 Vezes Mais que as Lâmpadas LEDs Convencionais Potência máxima de 30 Watts. Economiza a Bateria Resistente ao Calor (Contém um Cooler por Lâmpada) Excelente Resistência a Vibrações e Emissão de Luz Estável. Opera em 12V. Acompanha Fontes Embutidas. Chip Importado de Alta Potência. Mais Segurança e Eficiência. Dimensões: 9cm altura x 4cm de comprimento. - Aumente o poder do farol de seu carro ou moto. Instalação: Não é necessário cortar fios. O chicote vem Pronto para se conectar ao sistema original do veículo. Produto com melhor durabilidade, mais foco e materiais mais nobres. Dicas de Instalação (IMPORTANTE): Para o perfeito foco da Lampada, os leds sempre devem ficar na posição horizontal, mantendo o foco perfeito. É necessário o ajuste, sem isso a iluminação não foca. Garantia: 90 dias.', 49.9, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-mdnlfv3lsdld9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F23698773454', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
