INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499842996', 'kit com 18 Unidades de Parafuso Cabeçote Para Nissan Frontier 2.5 e Nissan Pathfinder 2.5 2005 2006 2007 2008', 'SOMOS UMA EMPRESA 100% BRASILEIRA Especializada na venda de peças para carros Importados e peças para carros Nacionais. Buscamos sempre oferecer as melhores marcas, atendendo nossos clientes de forma rápida e com preço competitivo. Para isso, trabalhamos com os principais fabricantes de peças para carros Importados e Carros Nacionais. Todos os produtos são originais, novos na embalagem do fabricante e com garantia. Temos como compromisso atender à necessidade de cada cliente, oferecendo um portfólio diversificado, com peças para carros nacionais e importados, garantindo qualidade e satisfação do cliente, em todo o processo de compra em nossas unidades. Produto: 01- kit C/ 18 Unidades de Parafuso Cabeçote Para Nissan Frontier 2.5 e Nissan Pathfinder 2.5 2005/... COMPATÍVEL COM VEÍCULOS > Montadora: Nissan Pathfinder Motor: 2.5 16v Ano: 2005 2006 2007 2008 2009 2010 2011 2012 2012 2013 2014 2015 2016 2017 2018 2019 2020 2021... > Montadora: Nissan Frontier Motor: 2.5 16v Ano: 2005 2006 2007 2008 2009 2010 INFORMAÇÕES ADICIONAIS • Marca: Origina Indisa • Produto Novo • KIT COM 18PCS - Rosca: M11 - Passo da Rosca: 1,25 - Comprimento: 110mm • Peso: 1,8 • NCM: 73181500 ITENS INCLUSOS 18- kit C/ 18 Unidades de Parafuso Cabeçote Para Nissan Frontier 2.5 e Nissan Pathfinder 2.5 2005/... (86454) -------------------------------------------------- COMPATÍVEL COM AS SEGUINTES REFERÊNCIAS 81031000 / 331520 / CABNS02 /11056-AD200 / 533090031 / PC D 24DA / B904000 / PCB500400 / 73181500', 347.05, 347.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mchz6nt7iecy74', 'https://