INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394225417', 'Troninho Kingdom 3 em 1 Blue - Safety 1 St', 'Completo, ele é 3 em 1: troninho, redutor e degrau. Solução perfeita para todas as etapas, dando a tranquilidade e a praticidade que os pais precisam. O momento de deixar as fraldas exige paciência, atenção e cuidado. O Troninho Kingdom 3 em 1 da Safety 1st é ideal para acompanhar a criança desde o início do desfralde como um prático e confortável penico. O formato é ergonômico do assento em material macio, com curva antirrespingo e ele conta com compartimento higiênico removível, facilitando a limpeza. Feito em material resistente, acompanha o crescimento da criança, tranformando-se em um assento redutor e degrau, que, quando são usados em conjunto, proporcionam segurança e conforto para a criança, durante a fase de uso já diretamente no vaso sanitário. E além do uso do degrau no vaso sanitário, ele serve para a criança alcançar a pia e fazer sua higiene diária como escovar os dentes, lavar as mãozinhas, com independência e mais tranquilidade para os pais. Características: 3 em 1: troninho, redutor para vaso sanitário e degrau Confortável e ergonômico Adapta-se à maioria dos vasos sanitários Curva antirrespingo Compartimento removível para resíduos Material resistente Fácil de limpar', 162.62, 162.62, NULL, 'Mom & Baby > Diapering & Potty > Potty Training & Commode Chairs', 'https://cf.shopee.com.br/file/sg-11134201-7rdvw-mc85x109miy9ae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F23394225417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
