INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18052782368', 'NIVEA Creme Facial Antissinais Q10 Energy Noite 50g', 'O que é? NIVEA Creme Facial Antissinais Q10 Energy Noite é um creme facial que deixa a pele com aparência mais jovem e firme em apenas 2 semanas. Para que serve? Com coenzima Q10 100% pura, idêntica à da pele, este creme promove proteção antioxidante, o que resguarda as células da pele contra os danos de radicais livres e fatores externos**. A vitamina C, também presente na fórmula, é outro poderoso antioxidante, deixando a pele mais iluminada e saudável. Além disso, com a vitamina E, as linhas finas e as rugas são suavizadas, o que deixa a pele com aparência mais descansada e radiante. Além de melhorar a hidratação e fortalecer a barreira de proteção da pele, revitaliza a pele durante a noite, quando ela está mais receptiva para receber o produto. Em 8h deixa a pele mais radiante e com aparência saudável, auxiliando inclusive na melhoria dos principais sinais de stress: linhas de expressão, falta de luminosidade e pele cansada. Conta com extrato natural de laranja, trazendo uma fragrância cítrica e refrescante. Benefícios e diferenciais: - Aparência mais jovem e pele mais firme em 2 semanas - Com 3 poderosos antioxidantes - Fórmula com Q10, Vitamina C e Vitamina E - Hidrata e fortalece a barreira de proteção da pele - Deixa a pele mais saudável e radiante em 8h - Rápida absorção - Proteção antioxidante e combate às rugas - Alivia os sinais de cansaço e a falta de luminosidade - Fragrância cítrica, com extrato natural de laranja - Revitaliza a pele durante a noite - Atua na melhoria das linhas de expressão **Teste in vitro. Como usar o Creme Facial Noturno NIVEA Q10 Energy? Com a pele limpa e seca, aplique no rosto e massageie suavemente até a absorção completa do produto. Uma unidade de embalagem contém 50g"', 61.9, 61.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meedz7cjzdvn3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F18052782368', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
