INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21728458103', 'Conjunto Interruptor Luz Esquerdo Fazer 150 2014+ - Condor', '🚀 Transforme sua Fazer 150 com interruptor de luz Condor! Acionamentos precisos de buzina, pisca e luz para rodar o dia todo sem preocupações. Materiais resistentes = longa vida útil no trânsito intenso! ✅ ESPECIFICAÇÕES TÉCNICAS: Marca: Condor Lado: Esquerdo Material: Plástico reforçado anti-vibração e chuva Peso: 150g | Cor: Preto ✅ COMPATÍVEL COM: Yamaha Fazer 150 (2014 em diante) – Instalação em 5 minutos! 🎯 PERFEITO PARA MOTOS DO DIA A DIA: Motoboys: Durabilidade extrema para entregas nonstop Entregadores: Sem falhas em poeira ou molhado Garantia: 90 dias contra defeitos SKU: 1211824 | EAN: 7899248129412 | OEM: 1ST-H3963-00 #interruptorMoto #Fazer150 #Motoboy #PecasMoto #FreteGratisShopee', 54.0, 54.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-22090-8encxmprfshv92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F338071078%2F21728458103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
