INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47554762842', 'Bowl Lyor Prima de Cristal 8cm x 5,5cm', 'Bowl Lyor Prima de Cristal 8cm x 5,5cm Encante seus momentos com o refinado Bowl de Cristal Prima da Lyor. Com dimensões compactas de 8cm x 5,5cm, este pequeno tesouro adiciona sofisticação e versatilidade à sua mesa. Mini DelíciasIdeal para servir pequenas porções, sobremesas individuais ou molhos, proporcionando um toque de requinte. Complemento CharmosoPode ser usado como um charmoso complemento decorativo ou para organizar itens delicados. Mesa VersátilO Bowl Prima transforma sua mesa em um espaço versátil, adequado para diversas propostas culinárias. Seja para uma refeição íntima ou para apresentar pequenas porções com requinte, o Bowl de Cristal Prima da Lyor é a escolha perfeita. Sofisticação em cada detalhe, mesmo nas dimensões mais delicadas. Lyor - Soluções completas para o seu Lar. Contém: 1 Bowl Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 5,00cm x Largura 8,50cm x Comprimento 8,50cm Peso: 0,19Kg Cor: Incolor Material: Cristal Lavar com detergente neutro, esponja macia e secar imediatamente. Não lavar em máquinas, não utilizar produtos químico.', 32.0, 19.99, NULL, 'Home & Living > Dinnerware > Bowls', 'https://cf.shopee.com.br/file/sg-11134201-8261t-ml5m7ns1v8xt74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F47554762842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
