INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498312957', 'Coroa Multiuso 56 Dentes Aço 1045 428 Titan 2000 a 2004-Fan 125 2005 a 2008 YBR Mais Torque', 'A Coroa Starke Racing 56 Dentes é fabricada em aço 1045 de alta resistência e chapa reforçada de 7 mm, oferecendo maior durabilidade e desempenho superior. Seu número de dentes acima do original proporciona aumento de torque, tornando a moto mais forte para subidas, transporte de carga e uso em terrenos inclinados. Características Técnicas: Material: Aço 1045 Espessura da chapa: 7 mm Passo: 428 Dentes: 56 Aplicação: Coroa traseira Acabamento: Pintura eletrostática preta Origem: Nacional Fabricante: Starke Produção Benefícios: Reforçada para maior resistência e vida útil Melhora o torque e a força em subidas Ideal para quem trabalha com peso ou roda em terrenos íngremes Encaixe preciso e instalação facilitada Excelente custo-benefício Compatibilidade: Titan 125 / 150 – 2000 a 2004 Fan 125 – 2005 a 2008 Yamaha YBR 125 – Todos os anos compatíveis com passo 428 Conteúdo da Embalagem: 1 Coroa 56 Dentes Starke Racing Observações: Verifique o passo da corrente e pinhão antes da instalação. Produto nacional de alta qualidade. Shopping da Motobike – obrigado pela preferência e boas compras!', 149.9, 134.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfibui7hpl39a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F531303273%2F21498312957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
