INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694620047', 'Kit Transmissão 21v Paco com Câmbios e Alavancas', 'O kit de câmbio 21 velocidades com alavanca V-Fire é uma solução prática e eficiente para reposição ou montagem de sistemas de transmissão completos em bicicletas com 3 coroas dianteiras e 7 catracas traseiras. Composto por peças compatíveis entre si, o kit oferece funcionamento preciso e resistência, ideal para uso urbano, recreativo e mountain bikes de entrada. A alavanca de câmbio modelo V-Fire possui maçanetas em alumínio e acompanha os cabos de acionamento instalados, facilitando a montagem. O câmbio dianteiro é do tipo top pull com abraçadeira de 31,8 mm, compatível com coroas de até 42 dentes. O câmbio traseiro possui fixação direta no quadro e suporta catracas com até 43 dentes, atendendo sistemas de roda livre de 7 velocidades. Especificações técnicas: Conteúdo da embalagem: – 01 alavanca de câmbio V-Fire 21v (3x7) com maçanetas em alumínio e cabos instalados (sem conduítes) – 01 câmbio dianteiro top pull para abraçadeira 31,8 mm, compatível com coroas até 42 dentes – 01 câmbio traseiro com fixação direta no quadro, para roda livre com até 43 dentes Material: alumínio, aço e PVC Cor: preto Compatibilidade: sistema 3x7 velocidades (21 marchas) Marca: Paco', 49.34, 49.34, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8262i-mlvyzdc83v2cc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23694620047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
