INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899548310', 'Caixa Térmica 36 Litros Açaí Bel', 'Caixa Térmica 36 Litros Bel - Capacidade e Frescor para Grandes Eventos! A Caixa Térmica 36 Litros da Bel é a aliada ideal para seus dias de lazer na praia, churrascos, acampamentos ou encontros familiares. Com um design robusto e funcional, ela oferece tudo o que você precisa para manter suas bebidas geladas e alimentos frescos por mais tempo. Por que escolher a Caixa Térmica 36 Litros Bel? ✔️ Capacidade Generosa: comporta até 7 garrafas PET de 2L ou 54 latinhas de 350ml (sem gelo), perfeita para grandes reuniões. ✔️ Material Seguro e Confiável: confeccionada com polipropileno 100% virgem, livre de BPA, garantindo armazenamento seguro e resistência a odores. ✔️ Isolamento Térmico Superior: feita com Poliestireno Expandido (EPS), mantém a temperatura ideal por longos períodos. ✔️ Design Funcional: tampa com suporte para copos e trava de segurança, além de alça ergonômica para transporte fácil e confortável. ✔️ Fácil de Limpar e Altamente Resistente: ideal para uso frequente, oferecendo praticidade e durabilidade incomparáveis. Seja para compartilhar momentos especiais com amigos e família ou para garantir frescor em suas aventuras, a Caixa Térmica 36 Litros da Bel é sua parceira indispensável. Leve mais praticidade para os seus dias!', 164.79, 164.79, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-825ac-mgccbeumsjkb45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F20899548310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
