INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211222565', 'Tênis Mizuno Neo Aura Petroleo', 'Tênis Masculino Mizuno Neo Aura Transforme sua corrida com o Tênis Masculino Mizuno Neo Aura. Projetado para atletas que buscam performance e conforto inigualável, este tênis é a escolha perfeita para asfalto e academia.Tênis Masculino Mizuno Neo Aura Transforme sua corrida com o Tênis Masculino Mizuno Neo Aura. Projetado para atletas que buscam performance e conforto inigualável, este tênis é a escolha perfeita para asfalto e academia. Sua entressola com tecnologia Mizuno Enerzy oferece amortecimento ímpar e um incrível retorno de energia, impulsionando cada passada. O cabedal em têxtil sintético e o forro acolchoado garantem ajuste perfeito e durabilidade, enquanto o solado de borracha proporciona tração superior. Com perfil de amortecimento e velocidade e pisada neutra, o Neo Aura é ideal para você superar seus recordes. Sinta a diferença de um tênis que une inovação e bem-estar em cada quilômetro. Adquira agora o Tênis Masculino Mizuno Neo Aura e supere seus limites na pista. Especificações: • Modelo: Neo Aura • Gênero: Masculino • Marca: Mizuno • Tecnologia da entressola: Mizuno Enerzy • Cabedal: Têxtil sintético • Forro: Acolchoado • Solado: Borracha (tração superior) • Perfil: Amortecimento e velocidade • Tipo de pisada: Neutra • Indicação: Corrida (asfalto), academia e alta performance', 583.32, 583.32, NULL, 'Sports & Outdoors > Sports Footwear > Running Shoes', 'https://cf.shopee.com.br/file/sg-11134201-823r7-mok0moykdjilf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F476999948%2F58211222565', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
