INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898878239', 'FITA TRANSPARENTE PROTEÇÃO PARA PÉS 3M NEXCARE 3M', 'Fita Protetora para os Pés Nexcare Transparente com 1 rolo de 25mmx3m A Fita Protetora para os Pés Nexcare é indicada para proteger a pele contra o atrito dos sapatos. Transparente e discreta, ajuda a prevenir ferimentos nos pés, como bolhas, cortes, rachaduras e arranhões. Possui formato prático e portátil, ideal para levar na bolsa e utilizá-la quando necessário. Caixa contém: 1 rolo de 25 mm x 3m. Benefícios - Transparente e super discreta. - Solução ideal para se ter na bolsa e usar sempre que sentir um incômodo nos pés. - Fita flexível e fácil de cortar, sem a necessidade de tesoura. - Perfeita para áreas difíceis de cobrir, garantindo conforto ao usuário. - Como usar 3M Nexcare Protetor para os Pés? - Corte no tamanho adequado. - Cole na parte do pé a ser protegida. - Vista o sapato normalmente.', 16.9, 16.9, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-824hd-mec40vea9lojd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1402904120%2F22898878239', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
