INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397428890', 'ANTENA CELULAR EXTERNA FULLBAND AQUARIO CF-7000 4G 3G 2G LTE', 'ANTENA CELULAR EXTERNA FULLBAND CF-7000 AQUARIO 2G, 3G, 4G e 4G LTE Atende a todas as frequências e tecnologias de sinal de celular 2G, 3G, 4G e 4G LTE. Ideal para celulares de mesa e modens 4G. A verdadeira fullband! A Antena Fullband para Celular da Aquário é ideal para áreas que possuam sinal de celular fraco, sejam urbanas ou rurais. Ela funciona nas 7 principais frequências (bandas) utilizadas no país (700, 850, 900, 1800, 1900 e 2100 e 2600MHz), levando muito mais comodidade ao consumidor. Além disso, esse produto atende a todas operadoras de celular (Claro, Vivo, OI, TIM, etc.), é de fácil instalação e pode ser conectado a um celular de mesa, modem 4G ou direto no aparelho de celular através de um adaptador. Compatibilidade:Compatível com Celular de Mesa Compatível com Modem 4G Wi-fi Frequência:700 / 850 / 900 / 1800 / 1900 / 2100 / 2600 MHz Número Elementos:20 Ganho:7,9dBi Conector:SMA fêmea Material:Alumínio Dimensões:800x245mm Peso:376g Alcance do Sinal:708-960MHz 1710-2700MHz Impedância:500hms Pesquisa:Antena|Fullband|para|celular|CF-7000|Aquario', 98.61, 88.75, NULL, 'Mobile & Gadgets > Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbmb-lmt4j2vzmu6x59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F19397428890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692987185', 'Boneca Metoo Angela Candy Color', 'Chegou uma das bonecas mais pedidas: a Angela Cacheada! A Boneca Metoo Angela Candy Color foi desenvolvida exclusivamente para o Brasil e é indicada para crianças de todas as idades. Feita inteiramente em pelúcia, vem com roupinha de praia e lacinho em plush, e uma sapatilha super fofa que dá um charme todo especial! Uma excelente opção para decorar ambientes infantis e presentear crianças e bebês. Perfeita para dormir abraçadinha, os bebês adoram. E o melhor: são colecionáveis. Não deixe de conferir os outros designs. ATENÇÃO: Este produto é original Metoo. Possui etiqueta em português, selo antifraude e toda a segurança comprovada pelo INMETRO. ESPECIFICAÇÕES: - Recomendado para crianças de todas as idades a partir de 0 meses; - Este brinquedo não tem restrição de idade; - Toque aveludado e olhos fechados, pensado para acalmar os bebês. COMPOSIÇÃO: - 100% poliéster e enchimento 100% fibra de poliéster. MEDIDAS APROXIMADAS: Boneca 33 cm: - Cabeça até corpo: 33 cm. - Cabeça até pé: 36 cm. LIMPEZA E MANUTENÇÃO: - Aconselhamos lavar à mão. Caso use a máquina de lavar, indicamos rotação leve e temperatura máxima de 30º; - Não limpar a seco; - Não usar a secadora. SOBRE A MARCA: A Metoo é uma marca chinesa, criada em 2004, com o intuito de adicionar um toque de felicidade à nossa vida. Combinando os designs mais fofos e os materiais mais confortáveis, a Metoo projeta, desenvolve, fabrica e comercializa brinquedos de pelúcia e acessórios para a casa de alta qualidade. A filial brasileira da Metoo desenvolve produtos exclusivos com todo o toque de sofisticação, primando pela qualidade e segurança dos nossos pequenos. As bonecas de pano são colecionáveis, indicadas desde RN, perfeitas para decorar ambientes infantis e presentear crianças e bebês. Uma mais linda que a outra, a marca possui também diversos acessórios, pelúcias e modelos de bonecos para meninos. Conheça a coleção completa! Código Inmetro:003702/2019', 189.9, 189.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7repc-m2h4wu7fo6rf5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1240688238%2F22692987185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
